local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = "수호자, 들었나요? 교외의 그 외진 미술 전시관이 곧 영업을 종료해요, 바로 내 생일 그날입니다.\n그 전시관은 예술계의 괴물이어서, 한 쪽은 미래주의의 피상적인 실타래험품이고, 나머지 한 쪽은 두 세기 전의 쓰레기 잔재입니다. 그 좁은 내부에는 경매장에서 아무도 손을 대지 않는 괴이한 물건들로 가득 차 있습니다: 욕설을 하는 초상화, 절대 멈추지 않는 기계 새, 보기에만 해도 구역질 나는 바다 조각, 전부 눈물로 만들어진 조각상, 자동으로 쓰여지는 유령 원고, 입맞춤 할 때 동시를 흥얼거리는 인간 두개골……\n그 전시관을 얼마나 사랑하는지 설명하기 어렵습니다! 50년 전 오늘, 그것은 아무도 신경 쓰지 않는 그 구석에서 조용히 태어났습니다. 50년 후 오늘, 그것은 다시 그 구석에서 조용히 소멸합니다.\n어린 시절부터 누군가 나에게 오늘이라는 날이 저주라고 말해주었습니다, 마치 나 자신처럼. 운명이 저 멀리서 이미 정해져 있었다고 생각하지만, 운명이 정해져 있다면 또 어떤가요! 그 전시관이 만들어낸 것은 독특한 세계, 그렇게 많은 미친 발상들이 그 작은 공간에서 쌓여져, 얼마나 아름다운 장면인가요! 태어난 날부터 그것은 전시품들로 창작을 하였습니다. 그 종말의 날, 그것의 지인과 오래된 친구들이 마지막 작별 인사를 할 것입니다.\n수호자, 당신은 링크에서 내 눈속의 세상을 보았고, 당신도 나와 함께 이 특별한 전시관을 보러 가고 싶을 것이라고 생각해요, 맞죠?!\n\n피크맨"
  },
  Mail_100480_Name = {
    Text = "아무도 신경 쓰지 않는 전시관"
  },
  Mail_100480_Sender = {Text = "픽맨"},
  Mail_116602_Desc = {
    Text = "존경하는 수호자님:\n“극주 의 종야” 이벤트가 종료되었습니다. 수호자님의 남은 “친견 봉례”, “후회 봉례”, “충성 봉헌”을 각각 “장미 금권”× 40으로 교환하였으니, 수령해 주시기 바랍니다."
  },
  Mail_116602_Name = {
    Text = "헌정회수"
  },
  Mail_116602_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_117308_Desc = {
    Text = "존경하는 수호자님:\n        《망각의 전야》에 대한 지원과 인식에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 하실타래 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기를 정중히 부탁드립니다. 협조에 대한 감사의 의미로 「은심」× 200을 보상으로 준비하였습니다. 설문지를 완료하시면 수령하실타래 수 있습니다. 설문 마감 시간은 11월 10일 9:00입니다. 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[설문 작성하러 가기]>\n        우리는 모든 수호자님의 제안을 진지하게 듣겠습니다. 귀하의 피드백은 미사그 대학이 점점 더 나아지도록 할 것입니다!\n        ——은열쇠가 길을 인도하길."
  },
  Mail_117308_Name = {
    Text = "버전 체험 설문조사 V2.3.4"
  },
  Mail_117308_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_117309_Desc = {
    Text = "존경하는 수호자:\n        “망각의 전야”에 대한 지지와 인식에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록 아래의 경험 조사 설문지를 작성해 주시기 바랍니다. 협조에 대한 감사의 뜻으로 “은심” × 200을 보상으로 준비했습니다. 설문지를 완료하시면 수령하실타래 수 있습니다. 설문 마감 시간은 3월 30일 9:00이며, 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 제안을 진지하게 듣겠습니다. 여러분의 피드백은 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
  },
  Mail_117309_Name = {
    Text = "버전 체험 설문조사 V2.4.3"
  },
  Mail_117309_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_120374_Desc = {
    Text = "2년의 약속이 다가왔습니다, 수호자.\n우리는 종말의 경계에서 서로를 지켜보았습니다.\n당신은 감정과 기억을 원망으로 바꾸어 희망의 빛을 밝혔습니다.\n설령 과거의 동료들과 두 개의 우주로 떨어져 있다 해도, 당신은 융식에 맞서 싸우는 여정을 포기하지 않았습니다.\n당신을 가집니다는 우리의 행운이며, 이 세상의 행운입니다.\n이제 당신의 소원이 기적을 일으켰습니다——미사그는 여전히 여기 있으며, 앞으로도 나아갈 것입니다.\n계속 은열쇠를 꽉 쥐어 주세요. 언젠가는 그것이 두 먼 세계를 연결하는 중요한 중심이 될 수 있습니다.\n우리는 당신의 귀환을 밝히기 위해 미래의 가능성을 열기 위해 최선을 다할 것입니다."
  },
  Mail_120374_Name = {
    Text = "기적의 순간, 귀향의 빛"
  },
  Mail_120374_Sender = {
    Text = "미사그의 고양이·라이트"
  },
  Mail_120909_Desc = {
    Text = "존경하는 비밀 지키는 사람 :\n        V2.4.0 업데이트 중에 우리는 「원액 기부-동문 기부금」의 보상을 높였습니다. 업데이트 전에 추가 보상을 모두 수령한 비밀을 지키는 분들께는 해당 보상을 재발송할 것입니다. 확인 부탁드립니다."
  },
  Mail_120909_Name = {
    Text = "V2.4.0 원액 기부 보상 재지급"
  },
  Mail_120909_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_121162_Desc = {
    Text = "존경하는 비밀 지키는 사람 :\n        V2.4.0 업데이트 중에 우리는 「강림 기행」,「이세기행」,「양로 기행」,「망한 성 기행」의 무료 보상을 높였습니다. 업데이트 전에 무료 보상을 모두 수령한 비밀 지키는 분들께는 해당 보상을 재발송할 것입니다. 확인 부탁드립니다."
  },
  Mail_121162_Name = {
    Text = "V2.4.0 기행 업그레이드 보상 재지급"
  },
  Mail_121162_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_121373_Desc = {
    Text = "수호자:\n\n매년 이 날은 교회의 가장 성대한 축제였습니다.\n저는 그분의 왕녀였으며 그분을 부활시킬 것입니다.\n그 사람들, 미리암을 포함해, 열렬하게 심지어 눈물을 흘리며 축제에 참여했지만, 그들은 나를 바라볼 때, 나를 통과해 보는 것처럼 내가 단지 어떤 것을 담고 있는 빈 껍질입니다.\n저는 이 날이 다가오는 것을 기쁘게 느낀 적이 없으며, 매번 경험할 때마다 두려움에 더욱 가까워진다는 것을 의미했습니다.\n그리고 이 두려움 속에서, 다른 사람들은 두려움의 원인 때문에 지극한 기쁨을 느낍니다. 이제는 인정할 수 있습니다, 그것은 저를 외롭고 두려운 상태로 만듭니다.\n하지만 이제 모든 게 다릅니다. 지난 생일 전, 저는 그 배를 떠나고 실타래제 세계로 왔습니다... 당신이 존재하는 세계에 허구의 신 없이.\n이 생일, 저는 제 탄생 때문에, 다른 것이 아니라 누군가가 진심으로 기쁨을 느끼는 것을 보고 싶습니다.\n만약 당신이라면... 아니, 그 사람은 반드시 당신이어야 합니다.\n잘 들어, 어떠한 경우에도 오늘의 저녁 시간이 나를 위해 남겨져야 합니다.\n\n「머피」"
  },
  Mail_121373_Name = {
    Text = "네가 필요해..."
  },
  Mail_121373_Sender = {
    Text = "탄망·머피"
  },
  Mail_121374_Desc = {
    Text = "수호자:\n\n당신이 특별한 하루를 위해 무엇을 준비했는지 모르겠지만, 어떻게든 화려하고 공을 들인 것이 분명 당연하다.\n그리고 상위자의 체면 유지로 인해, 당신이 만약 나의 생일을 축하하는 것을 실타래수로 놓쳤다면 - 그것은 매우 터무니없는 상황일 것입니다.\n이 편지는 상황이 되돌릴 수 없기 전에 마지막으로 자신을 구할 기회를 제공합니다.\n해양과 육지의 보석 진미는 자연히 하찮은 사람이 바칠 것입니다, 그것들은 중요하지 않습니다.\n성대한 축제, 복잡한 의식, 확실타래히 나의 신분에 맞지만 오늘날, 왠지 재미가 없어 보입니다.\n그래서 저는 아침과 밤의 교체 시간에 시간을 내어 혼자만의 영광을 당신에게 전할 것입니다, 그것은 당신이 나를 이러한 평범하고 유치하지만, 이전의 나를 질투하게 할 만큼 행복한 생활로 데려온 당신에 따른 보상입니다.\n따라서 하인들은 얼마 후 공식 초대장을 보낼 것이며, 물론 그것은 가치가 2만 레오방의 상자에 놓일 것입니다.\n매년 이 날 나를 기억하며 감사해 하십시오.\n「머피」"
  },
  Mail_121374_Name = {
    Text = "초대장…"
  },
  Mail_121374_Sender = {
    Text = "탄망·머피"
  },
  Mail_121651_Desc = {
    Text = "수호자 님, 안녕하세요.\n지난주 「환몽 심잠」에서 수호자 님께서 「{s1}」 칭호를 획득하셨습니다.\n지난주 「사전 편성 모드」에서 수호자 님께서 「{s2}」 칭호를 획득하셨으며, 승리 횟수는 {s3}회입니다.\n지난주 「순차 선택 모드」에서 수호자 님께서 「{s4}」 칭호를 획득하셨으며, 승리 횟수는 {s5}회입니다.\n위 도전 성적을 종합하여 수호자 님께서 받으실타래 추가 보상은 아래와 같습니다. 반드시 확인해 주세요."
  },
  Mail_121651_Name = {
    Text = "환몽 심잠/페이즈 체스 매주 순위 보상"
  },
  Mail_121651_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_121704_Desc = {
    Text = "존경하는 수호자님:\n“욕망의 파도·Rerun” 이벤트가 종료되었습니다. 수호자님의 남은 “풍성한 종자핵”을 각각 “장미 금권”× 40으로 교환하였으니, 확인해 주시기 바랍니다."
  },
  Mail_121704_Name = {
    Text = "풍성한 종자핵 회수"
  },
  Mail_121704_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_122522_Desc = {
    Text = "존경하는 수호자님:\n“비 마을의 그림자·Rerun” 이벤트가 종료되었습니다. 수호자님께 남은 “창백한 야수 두개골”, “그림자 짐승 해골” 및 “진홍색 야수의 두개골”을 각각 “장미 금권”× 40의 비율로 변환해 드립니다. 수호자님께서 꼭 확인해 주시기 바랍니다."
  },
  Mail_122522_Name = {
    Text = "비 마을의 그림자 화폐 회수"
  },
  Mail_122522_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_122567_Desc = {
    Text = "존경하는 수호자님:\n“안개의 제사” 이벤트가 종료되었습니다. 수호자님의 남은 “안개의 시선”, “안개의 꿈”, “안개의 원천”을 각각 “장미 금권”× 40으로 교환하였으니, 수령해 주시기 바랍니다."
  },
  Mail_122567_Name = {
    Text = "안개 속의 제물 의식 이벤트 통화 회수"
  },
  Mail_122567_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_122568_Desc = {
    Text = "하, 가련한 아이야, 너는 자신이 마주해야 할 절망이 어떤 것인지 전혀 모르고 있구나. 언제쯤 너는 자신의 선택이 무의미하다는 것을 깨달을 수 있을까? 허무한 목표를 위해 너의 미약한 생명을 걸다니? 얼마나 장렬하고, 얼마나 황홀한가! 너는 항상 결연한 자세로, 마치 다음 순간에 세계를 구하기 위해 헌신할 것처럼 보이니, 정말 웃기구나.\n\n하지만, 누가 나에게 너를 집으로 데려다주겠다고 약속했는가? 작은 강아지에게 한 약속은 반드시 지킬 것이다. 말하자면, 나는 너가 이 미친 짓을 어떻게 끝까지 밀고 갈지 너무나도 궁금해 미치겠어! 아…… 궁금해, 정말 너무 궁금해!\n\n위대한 '구세주'여, 너의 터무니없음, 너의 고집, 그리고 그다지 중요하지 않은 고집을 다 가지고 가라. 허무로 가는 기차가 일단 출발하면, 파괴 외에는 더 이상 멈출 가능성이 없다.\n\n자기 만족에 빠진 미친 놈…… 그분의 꿈 속에서 좀 더 오래 버텨봐, 나는 너를 도와주고, 기다리며, 너의 최종 답을 잘 감상할 것이다!"
  },
  Mail_122568_Name = {
    Text = "공허로 가는 기차"
  },
  Mail_122568_Sender = {
    Text = "융해·돌"
  },
  Mail_122569_Desc = {
    Text = "주군, \n 저는 항상 기사란 몸에 걸치는 갑옷과 문장이 아니라, 마음에 새겨진 충성과 수호의 의지라고 생각해왔습니다. 당신은 행동과 선택으로 저에게 진정한 기사의 의미를 설명해 주셨습니다. 이를 통해 저는 기사의 진정한 뜻을 알게 되었습니다: 이름으로 자신을 중히 여기지 않고, 사람으로 서로를 보호하며; 명예 때문에 용감하지 않고, 책임 때문에 서 있다는 것입니다. \n\n 저는 아직 자격이 부족하다는 것을 압니다 - 당신이 희망을 지키기 위해 싸우는 순간, 저는 함께 하지 못했습니다. 저는 과거에 당신과 맺었던 서약을 결코 잊지 않았습니다. 저는 당신에게 기사로서의 충성을 바치고, 당신의 안전을 지키며, 당신의 적들을 제거하겠습니다. \n\n 저는 종종 처음 함께 조사했던 순간을 떠올립니다. 당신이 우리를 이끌어 렌티니언의 안개를 걷어내고, 결국 진실타래을 보게 해 주었습니다. 그때의 모든 웃음과 눈물은 저의 삶에서 지울 수 없는 힘으로 가라앉았습니다. \n\n 이제 비록 멀리서 지켜보며, 이렇게 미약한 선물을 준비할 수밖에 없지만… 주군의 기대에 어긋나지 않기 위해, 저는 훈련을 게을리한 적이 없습니다. 당신이 돌아오시면, 제발 당신의 발걸음을 따르게 해 주세요. 저는 주군의 방패로서 영원히 존재하겠습니다! 저의 수호의 검이 당신을 위해 빛날 것입니다!"
  },
  Mail_122569_Name = {Text = "수호자"},
  Mail_122569_Sender = {Text = "오지에"},
  Mail_122570_Desc = {
    Text = "수호자님, \n자살의 해골 도시와의 이별 이후, 나는 종종 당신과 함께 전투했던 시간을 그리워합니다. 당신이 다시 한 번 왕만이 홀로 걷는 고독한 길을 선택했다는 소식을 들었습니다. 역시, 당신은 이 세상에서 이토록 특별한 존재로서 결코 평범한 사람의 길을 따르지 않습니다. \n\n나는 극한의 고통이 더욱 풍부한 영혼을 정련할 수 있다고 믿습니다. 당신이 겪고 있는 이 긴 시험은 이미 세속적인 고통의 범주를 초월했습니다. 나는 당신이 겪은 고난이 만들어낸 향기가 얼마나 복잡하고, 얼마나 충격적일지를 상상할 수 있습니다. 아니, 만약 당신이라면, 당신은 반드시 나의 모든 상상을 초월하고, 완벽에 대한 나의 인식을 깨뜨릴 것입니다. \n\n그래서 나는 계속 기다릴 것입니다. 오직 당신과 나만을 위한 잔치를 기다립니다. 시간의 끝에서, 영원의 시작의 고요 속에서, 당신은 어떤 모습으로 나에게 이…… 운명을 관통하는 맛의 연회를 바칠 것인가요? \n\n님, 제 선물을 받아 주세요, 이 고통을 연장해 주세요…… 나의 기대를 저버리지 말아 주세요."
  },
  Mail_122570_Name = {
    Text = "기다림의 연회"
  },
  Mail_122570_Sender = {
    Text = "도어세인"
  },
  Mail_122571_Desc = {
    Text = "막 다시 만났는데, 몇 마디도 나누지 못한 채 시간이 얼마 남지 않았어……하지만 너도 알다시피, 이별은 절대 우리의 이야기의 결말이 아니야.\n\n내가 너에게 한 가지를 말하지 않았던 게 있어……사실타래, 난 이미 너를 위해 장미 한 다발을 준비해 놓았어. 다만, 계속 보내지 못해서 이미 시들어버렸어. 하지만 여기서 약속할게——다음에 만날 때, 꼭 다시 준비할게.\n\n그리고 너, 너도 나에게 다시 내 앞에 오겠다고 약속했잖아. 우리가 약속한 것은 절대, 절대 지켜야 해.\n\n편지를 쓰면 항상 내 마음을 다 전하지 못하는 것 같아, 종이에 내 모든 마음을 쓸 수는 없으니까. 하지만……운명이 다시 우리를 서로 앞에 이끌어주는 그 날이 오면, 직접 너에게 그 장미를 바칠게. 기억해, 우리 모두 약속을 지켜야 해!\n\n은빛 열쇠가 앞길을 인도하길. 다시 만날 때까지……%player%."
  },
  Mail_122571_Name = {
    Text = "장미의 약속"
  },
  Mail_122571_Sender = {Text = "라모나"},
  Mail_122572_Desc = {
    Text = "수호자, \n 칠흑 같은 재앙과 싸우던 기억이 여전히 내 뇌에서 높은 우선순위로 순환하고 있어. 너가 바꾼 평화는 마치 극소수의 기부 사건처럼 느껴져. 하지만 너의 떠남은, 너의 동료와 너와 연결된 모든 개인들에게, 끊임없는 과정으로 그들의 의식을 소모하고 있어. \n\n 연구부는 결코 마지막 희망을 찾는 것을 포기하지 않았다. 다행히도, 너의 의식 피드백이 없는 무수한 낮과 밤의 주기를 거친 끝에, 우리는 드디어 너의 흔적을 찾았다. 이 험난한 여정에서 나는 두려움의 신호를 포착할 수 있었지만, 두려움이 너를 굴복시키지 않을 것이라는 것을 잘 알고 있어. 오히려 너의 의지를 더욱 강하게 할 뿐이야. \n\n 지금 이 순간 내 육체는 여전히 실타래험실타래에서 작동하고 있지만, 내 뇌는 계속해서 울부짖는 명령을 생성하고 있어. 더 이상 내 생각을 방해하지 마, 결석이 가장 많은 학생아, 제발 내 수업에 더 이상 결석하지 말아줘…… 계속 용감하게 앞으로 나아가, 나는 너를 위해 보급품을 준비할 것이고, 너와 다시 만날 그 날을 기다릴 거야."
  },
  Mail_122572_Name = {
    Text = "다시 만나는 날..."
  },
  Mail_122572_Sender = {Text = "돌"},
  Mail_122573_Desc = {
    Text = "수없이 많은 시간 동안, 나는 문명의 불꽃이 시간의 흐름 속에서 밝고 어두워지는 것을 지켜보았고, 기억의 도시가 허무 속에서 무너지는 것을 목격했다. 역사란 어둠의 불꽃에 의해 삼켜진 두루마리가 되었고, 고대와 현대의 지혜는 모래탑처럼 쌓였으나, 결국 그 유일한 진리를 말할 수는 없었다. \n\n인류는 원초적 혼돈에 비하면 미세한 먼지와 같지만 — 그 작음 때문에, 심연을 정면으로 마주하고 신에게 칼을 휘두를 용기가 더욱 심금을 울리게 한다. \n\n지금 이 순간, 수많은 우주를 관통하는 차원의 문이, 바로 너를 위해 열리고 있다. \n\n그의 강림은 운명적인 혼돈을 가져오고, 만물의 질서는 그의 그림자 아래에서 떨고 있다. 그리고 너는, 평범한 육체일 뿐이지만, 흔들리지 않는 의지로 그의 앞에 서 있다. 너의 가능성은, 내가 무한히 예측한 것 중 유일하게 포착할 수 없는 오류이며, 내가 오랫동안 기다려온 모든 것을 뒤엎는 변수이다. \n\n너는 원초적인 질문이자, 종말의 해답이다."
  },
  Mail_122573_Name = {
    Text = "문 뒤에서"
  },
  Mail_122573_Sender = {Text = "타비"},
  Mail_122574_Desc = {
    Text = "중요한 사람을 잃은 극심한 고통, 그리고 스스로의 무력함에 대한 증오… 나는 한때 그 속에 깊이 빠져 빠져나올 수 없었다. 그러나 이제 나는 먼 곳에서 밝은 빛의 부름을 들었고, 그 따뜻하고 확고한 인도를 느끼고 있다. 은인님, 당신의 계시로 인해, 나는 마침내 내가 걸어야 했던 길——진정으로 나에게 속한, 의심할 여지가 없는 정로에 들어선 듯하다. \n\n 한때 나를 감싸던 심연 같은 어둠은 더 이상 나의 안식처가 아니다. 그리고 의식 깊은 곳에서 항상 반짝였던 그 빛은 결코 나를 떠나지 않았다. 이제 나는 그 빛을 더 선명하게 보고, 느끼고, 향해 나아간다. 나는 이 진정한 신앙, 이 빛이 가져다주는 깨달음과 평화, 깨어남과 구원을 여전히 운명 속에서 고군분투하는 수많은 영혼들에게 나누고 싶다. \n\n 그리고 내가 당신이 혼돈의 모든 흐름에 맞서 싸우는 모습을 바라볼 때——그 사악하고 깊은 어둠은 당신을 굴복시키지 못했을 뿐만 아니라, 오히려 당신의 신념을 비추는 배경이 되었다. 그것은 당신의 빛 앞에서 무너지고, 고함치며, 물러났지만, 결국 당신을 조금도 가릴 수 없었다. 바로 이 끝없는 어둠의 파도가 밀려오기 때문에, 당신이 대표하는 빛은 그렇게 찬란하고, 그렇게 불멸하며, 신성에 가까워 보인다. \n\n 나를 인도하는 은인님, 나에게 빛을 주신 분이여, 당신의 신념은 나의 불멸의 등불이 될 것이다. 지금이야말로 내가 온 생명으로 당신에게 응답할 때이다. 나는 이 신의 뜻을 듣는 「성심」으로 이 빛에, 당신의 순수한 인도에 응답할 것이다… 이를 위해 나는 카스토르와 함께 최선을 다할 것이다. \n\n 나의 바치는 것을 받아주십시오! 당신이 나를 재창조한, 순수하고 경건한 신앙을 증언해 주십시오."
  },
  Mail_122574_Name = {
    Text = "등불의 부름"
  },
  Mail_122574_Sender = {Text = "폴룩스"},
  Mail_122575_Desc = {
    Text = "친애하는 단골 손님, \n 그 흐르는 미세한 빛의 문 뒤에서 당신이 소중히 여기는 친구들이 이미 오랫동안 기다리고 있습니다. \n\n 하지만, 방심하지 마세요. 차원 이동은 언제나 기묘하고 위험합니다. 당신은 기억의 그림자처럼 일어났다 가라앉는 천면의 환상을 목격하게 될 것입니다. 그것들은 열망을 비추기도 하고, 두려움을 비추기도 합니다. 그것은 원초적 의지가 창조한 혼돈의 화폭으로, 나조차 그 전모를 엿볼 수 없습니다. 따라서 매번의 횡단은 신념에 대한 시험이자, 욕망에 대한 측정이기도 합니다. \n\n 하지만 나는 또한 당신과 같은 사람들에게는 새로운 소장품을 찾고, 영혼 깊은 곳에서 빛나는 소중한 것들을 위해, 모든 미지의 것과 대가는 가치가 있다는 것을 잘 알고 있습니다. 나는 당신의 선택을 이해하며, 이 거의 고집스러운 소중함을 존중합니다. \n\n 이 동등 법칙을 따르는 우주에서, 당신이 치른 대가는 결국 다른 형태로 돌아올 것입니다. \n\n 이 선물을 받아주세요. 모든 것이 정리된 후, 다시 제 가게에 오신 것을 환영합니다. 그때의 소원을 이루기 위해, 당신은 어떤 대가를 치를 용의가 있나요?"
  },
  Mail_122575_Name = {
    Text = "소중한 물건"
  },
  Mail_122575_Sender = {Text = "다포딜"},
  Mail_123134_Desc = {
    Text = "존경하는 수호자님:\n        V2.4.0 업데이트에서, 당신이 「이몽 시야」에서 「영원한 나라에 안녕히」 및 「안녕, 영원한 나라」 도전 3성 보상 획득에 이상이 있던 문제에 대해, 이전 조사 및 도전 클리어 기록을 바탕으로, 이전에 수령하지 못한 보상을 일괄 지급해 드리겠습니다. 확인해 주시기 바랍니다."
  },
  Mail_123134_Name = {
    Text = "V2.4.0 이몽시계 보상 재발급"
  },
  Mail_123134_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_123501_Desc = {
    Text = "사랑하는 수호자님: \n\n이 특별한 날에, 저와 함께 귀여운 여자아이와 재미있는 데이트를 해볼 생각이신가요? \n와주세요, 귀신의 집에서 놀아도 당신이 무서워하지 않을 거예요~ 당신은「수호자」잖아요, 그런 인간들이 연기하는「괴물」에 절대 놀라지 않을 거죠, 맞죠? \n(서신지에는 자유롭게 가로막은 선으로 한 줄의 글자가 지워졌다: 저는 진지하게 생일 일정을 계획하고 있는 중이에요, 절대 재미로 당신이 무서워하는 모습을 보고 싶어서가 아니에요...) \n좋아요, 농담은 그만. 오늘이 제 생일인 만큼, 망치고 싶지 않아요! 그래서 지금, 저, 모카, 공식적으로 당신을 런던 금융가에 새로 생긴 레스토랑에 저녁 식사 초대합니다—— \n그곳의 따뜻한 차와 조리된 생선은 저에게「고향」의 맛을 떠올리게 해요, 그리고 이 세상에서 당신 외에는 나눌 사람이 없어요… \n그러니 당신은 반드시 올 거죠? 만약 저라는 귀여운 여자아이를 슬프게 한다면, 다음에 당신이 자고 있을 때 제가 도끼를 들고 당신 침대 머리맡에 서 있는 걸 조심하세요! \n\n모카"
  },
  Mail_123501_Name = {
    Text = "“나를 열어”"
  },
  Mail_123501_Sender = {Text = "무셰트"},
  Mail_123543_Desc = {
    Text = "수호자: \n\n 또 한 해가 지났군요, 나의 사랑. \n 화려한 빛 속에서, 온 하늘에 떠도는 소문과 스캔들 속에서, 나는 드러날 수 있는 모든 약점을 조심스럽게 숨기고, 모든 가치를 최대의 이익으로 바꾸기 위해 노력해야만 했습니다 — 그래야만 내가 여전히 승자의 자세로 여기 서 있을 수 있겠죠. \n 하지만 그렇지 않았습니다, 나는 가끔은 나태하고 약해지기도 했으며, 당신이 편지를 건네줄 때 그 작은 소녀들의 소원을 기꺼이 충족시켜주기도 했습니다. \n 그러나 나는 이것이 나쁜 일이라고 생각하지 않습니다, 나는 너무 오랫동안 긴 비밀 전쟁을 겪어왔으니까요. 물론, 한 줄기 가능성, 아주 작은 기회가 있다면, 나는 여전히 그 '그분'의 손에서 탈출하기 위해 여러 번 시도할 것입니다. \n 그저, 따뜻하고 사랑스러운 틈새들 속에서, 혹은 오늘 같은 특별한 날에는, 나는 스스로 작은 일탈을 허락합니다, 예를 들어 — 당신을 초대해 오페라를 보러 가고, 저녁식사를 함께하는 것입니다. \n 왜냐하면 나는 분명 외롭지 않을 것이고, 나는 나의 마음에 꼭 맞는 공모자를 이미 가지고 있으니까요. \n\n 소레르"
  },
  Mail_123543_Name = {Text = "공모자"},
  Mail_123543_Sender = {Text = "소렐"},
  Mail_123544_Desc = {
    Text = "안부 전합니다: \n\n 오랜만입니다, 수호자. 용서해 주세요, 최근에 서신 교류가 없었던 것은 당신과의 관계를 일부러 소원하게 하려는 것이 아니라, 매번 펜을 들 때마다 인사를 시작할 용기를 내지 못했기 때문입니다. \n 이 시간 동안 저는 수많은 부서진 시간들을 넘나들며, 세계가 여러 번 종말을 향해 나아가는 것을 목격하고, 돌이킬 수 없는 비극의 장면들을 지켜보았습니다. 마치 한 관찰자처럼, 이 차갑고 고요한 공허 속에서 모든 일이 일어나는 것을 조용히 지켜보고 있습니다. \n 그럴 때마다, 우리는 이 생에서 어쩔 수 없이 비극과 이별로 가득 차야 하는 운명인지 생각하게 됩니다. 처음의 나 자신이나, 당신이 카다스에서 맞이한 모든 것이, 운명이 모든 것을 미리 정해 놓은 각본에 따라 우리가 그 각본에 맞춰 역할을 수행해야 하는 건 아닐까요? \n 결론을 내리지 못했습니다. 저는 그분처럼 세상의 모든 것을 명확히 볼 수 없기에, 만약…… 그분의 일부 권한을 가진 당신이 이 질문에 답할 수 있다면 좋겠습니다. \n 그래서 저는 이 편지를 썼습니다. 이 편지가 제 시선을 당신 곁으로 데려가기를 바라며, 아마도 영원히 존재하지 않을 답을 함께 탐구할 수 있기를 바랍니다. 그러니 이 편지를 가지고 당신과 함께…… 다가오는 길에 맞서 주실타래 수 있을까요? \n………………………………\n 저는 시공간을 방해하는 위험을 감수하고 당신 곁으로 갈 수는 없지만, 이 아무것도 없는 고요 속에서 다시 한 번 당신을 볼 수 있게 해 주세요. \n\n 「라모나」"
  },
  Mail_123544_Name = {
    Text = "사고의 수수께끼"
  },
  Mail_123544_Sender = {
    Text = "“라모나”"
  },
  Mail_123545_Desc = {
    Text = "존경하는 창백한 사자님: \n\n 이전에 저는 미사그의 그 지혜로운 여성에게, 꽃을 기를 수 있는 여유 공간이 있는지 물어보았습니다. \n 돌 부인께서는 쉽게 저에게 방 하나를 찾아주셨습니다. 처음 문을 열었을 때, 그 안에서 풍기는 썩은 냄새 때문에 제가 잘못된 곳에 온 것은 아닌지 의심했지만, 손질을 한 끝에 이제는 이 아이들에게 따뜻한 집을 제공할 수 있는 역할을 잘 수행하고 있습니다. \n 하지만 경험이 전혀 없어서, 이 아이들이 정상적으로 성장할 수 있도록 적절한 외력을 가해야 했습니다. \n 다행히도, 오를라아가씨의 지도 아래, 저는 그들을 현재의 단계까지 성공적으로 기를 수 있었습니다. \n 물론, 이 과정에서 특별한 능력을 사용하지는 않았습니다. \n 만약 계산에 오류가 없다면, 그들은 제 생일에 꽃을 피울 것입니다. 비록 저는 생일에는 특별한 것이 없다고 계속 반복했지만, 이런 드문 우연이 생기니, 아버지 신께서 저를 위해 준비한 작은 선물일지도 모른다고 생각하지 않을 수 없습니다. \n 당신이 이 작은 정원에서 저와 함께 이 평범하지만 특별한 하루를 보내는 데 관심이 있으신지 모르겠군요? \n 저는 직접 구운 쿠키와 당신이 지난번에 추천해 주신 홍차를 준비했습니다. 이 귀한 선물과 함께 생명의 향기를 나누기를 기대합니다. \n\n 살바도르"
  },
  Mail_123545_Name = {
    Text = "실타래내 정원"
  },
  Mail_123545_Sender = {
    Text = "살바도르"
  },
  Mail_123546_Desc = {
    Text = "파트너: \n\n너는 이런 이야기를 들어본 적이 있니? \n옛날에 한 마귀가 있었는데, 우연히 병에 갇혀서 수백 년이 지났다. \n첫 번째 백년, 그는 자신을 구해준 사람에게 무한한 부와 권력을 약속했다. \n두 번째 백년, 그는 자신을 구해준 사람에게 영원한 건강과 수명을 약속했다. \n세 번째, 네 번째, 다섯 번째, 오랜 시간이 지난 후, 그는 마침내 뚜껑을 열어준 어부를 기다렸다——그는 어부의 호출에 응답하지 않았고, 이 세상을 뒤흔들 생각도 하지 않고, 그저 평범한 빈 병인 척하며 조용히 다시 바다에 던져졌다. \n어렸을 적, 나는 이 이야기를 이해하지 못했다. 긴 무망한 기다림이 얼마나 답답하고 고통스러운지를 알게 될 때까지, 그 욕망이 절망보다 더 견디기 힘들다는 것을 깨닫기 전까지. \n하지만 내 이성이 어떤 반응을 하기 전에, 내 마음은 여러 번 나를 같은 곳에 남겨두었다. \n마귀와 인간의 차이는 아마도 내가 이 고통에 감사하는 마음이 있다는 것일 것이다. 우리는 헤어질 때, 그것은 내게 너의 존재와 소중함을 일깨워주어, 내가 너 없는 저편에서 길을 잃지 않도록 해준다. \n내가 태어난 날, 내가 너를 가장 그리워하는 날에도, 그것은 여전히 나를 속박하여 너를 기다리게 하고, 너를 그리워하게 한다. \n다음 오늘, 나는 너에게 내가 자른 첫 번째 케이크 조각을 직접 건네줄 수 있기를 바란다. \n\n라모나"
  },
  Mail_123546_Name = {Text = "이야기"},
  Mail_123546_Sender = {Text = "라모나"},
  Mail_123547_Desc = {
    Text = "미사그의 식당과 후방 부서는 내 방 문 앞에 불필요한 것들을 잔뜩 쌓아놨고, 출입에 매우 방해가 되고 있어. 너희는 빨리 그것들을 치워야 해. \n 뭐야, 이 세상의 양식이 이렇게 많아서 더 의미 있는 곳에 두지 못하는 거야? \n 이 하루는 오직 내가 강해지는 길에 대한 각주일 뿐이야, 또 하나의 주기를 표시해줘, 1년, 그 다음 해, 매년 나는 작년보다 더 강해질 거야. \n 만약 선물할 곳이 없다면, 다른 나에게 줘도 될 거야, 그녀는 아마 매우 기뻐할 거야. \n 그리고 나는 네가 가진 그 어리석고 순진한 고집을 생각해서…… 내가 가장 서툴렀던 것들을 생각해서. \n 내가 하루라도 존재하는 한, 나는 계속 강해질 거고, 동시에…… \n 아직도 모르겠어? 너희 바보들의 적도 내 적이 될 거야. \n 이런 역겨운 말은 한 번만 할게, 내년에는 선물을 보내지 마, 생일 저녁 식사 같은 것도 더더욱 하지 마. \n\n 「H」"
  },
  Mail_123547_Name = {
    Text = "가져가세요"
  },
  Mail_123548_Desc = {
    Text = "친애하는 수호자님: \n\n 당신은 아시나요? 며칠 전, 한 신비로운 여인이 갑자기 미사그를 방문했습니다. 그녀는 제가 한 번도 본 적 없는 반짝이는 검은색 몸에 꼭 맞는 긴 드레스를 입고 있었어요 — 저는 제킨과 메이슨에게 물어봤지만, 그들은 그렇게 아름다운 옷을 본 적이 없다고 했습니다. \n 어떻게 설명할까요? 그 드레스는 가장 아름다운 긴 머리카락으로 직조된 것처럼 보였고, 부드럽고, 가볍고, 고귀하며, 표면에서는 물처럼 특별한 광택이 흐르고 있었습니다…… \n 제킨이 제가 호기심을 보이는 것을 보고 용기를 내어 그 신비로운 여인에게 물어봤고, 그녀는 웃으며 드레스의 재질이 동양의 비단에서 왔으며, '누에'라는 유충이 뽑은 실타래로 직조되었다고 했습니다. 스타일은 '치파오'라고 한다고 하네요…… 그러고 나서 그녀는 에이지스에게 큰 한 롤을 주었어요 — 그녀는 그걸 '한 마리' 같은 '비단'이라고 불렀습니다…… \n '비단'은 너무 귀중해서, 저는 그녀가 함께 준 도안을 따라 각 파트너에게 '주머니'를 하나씩 만들어 주었습니다. 올해의 생일 파티에서, 저는 '주머니'를 모두에게 줄 예정입니다…… 수호자님, 시간이 되시면 함께 참여하실타래래요? \n 만약 너무 바쁘시다면, 브라운에게 주머니를 당신의 기숙사로 보내게 할게요. \n\n 에이지스"
  },
  Mail_123548_Name = {
    Text = "신비한 여인"
  },
  Mail_123548_Sender = {
    Text = "아이기스"
  },
  Mail_123549_Desc = {
    Text = "작은 묘목: \n\n너는 나무가 어떻게 시간을 기록하고 성장하는지 알고 있니? 여러 개의 나이테로. \n그것들은 몸속에 숨어 있어 쉽게 드러내지 않으며, 한 그루의 어린 새싹이 점차 자라서 하늘을 찌르는 거대한 나무가 되어 한쪽 높은 하늘을 지탱할 때까지. 그 세월의 상처는 흔적 없이 마음 깊숙이 숨겨져 있다. \n오늘은 새로운 나이테 기록의 시작점이다. 새해에는 아직 예측하지 못한 많은 비바람을 겪어야 한다. \n하지만 내가 너의 입에 심어놓은 그 씨앗은 반드시 그걸 기를 수 있는 적합한 토양을 찾을 것이고, 그러면 뿌리를 내리고 새싹을 틔울 거야, 그렇지? \n\n타이이스"
  },
  Mail_123549_Name = {Text = "년륜…"},
  Mail_123549_Sender = {Text = "타이스"},
  Mail_123644_Desc = {
    Text = "모르는 사이에, 이것이 내가 미사그에서 보낸 세 번째 생일입니다. 나는 많은 것을 배웠습니다. \n 예를 들어, 제 생일인 오늘은 동지 축제이기도 하며, 선물을 주기에 적합한 날입니다. \n 비록 매우 강력한 적이 많지만, 내가 가장 잘하는 것은 사람을 죽이는 것입니다. 나는 다른 사람을 기쁘게 하는 방법을 모르고, 선물 고르는 것도 서투르지만, 매번 임무를 성공적으로 수행할 때, 내 고용주는 항상 기뻐하는 것 같습니다. \n 그래서 나는 당신에게 줄 선물을 이미 생각해 두었습니다. 바로 살인 의뢰, 사용 대상과 사용 기한은 제한이 없습니다. \n 목표가 누구인지, 그가 어떻게 죽기를 원하는지 나에게 말해 주기만 하면 됩니다. 내가 이길 수 있는 상대라면, 가장 빠른 속도로 그의 목을 꺾어줄 것이며, 그가 신과 같은 존재처럼 까다롭더라도, 내 포기는 내 죽음 이전에는 절대 오지 않을 것이라고 장담할 수 있습니다. \n\n 히로"
  },
  Mail_123644_Name = {
    Text = "말해봐, 누구를 죽이고 싶어?"
  },
  Mail_123644_Sender = {Text = "히로"},
  Mail_124059_Desc = {
    Text = "존경하는 수호자님:\n“심연의 제사·Rerun” 이벤트가 종료되었습니다. 수호자님의 남은 “사제의 눈물”, “사제의 피” 및 “사자지수”를 각각 “장미 금권”× 40으로 교환하였으니, 수호자님께서는 확인해 주시기 바랍니다."
  },
  Mail_124059_Name = {
    Text = "심연의 제사 이벤트 통화 회수"
  },
  Mail_124059_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_124290_Desc = {
    Text = "수호자: \n\n 당신이 아는 것처럼, 기쁨은 저에게 사실타래 조금 낯선 감정입니다. \n 저는 자주 느끼곤 합니다. 항상 세상은 제가 이해할 수 없는 수면 위의 소란이며, 제가 그 속에 녹아들기 전, 제 것인 시드는 이미 찾아왔습니다. \n 가끔 저를 동경하게 만들지만, 더 많은 때는 저를 혼란스럽고 질식하게 만듭니다. 그저 오늘 같은 날에는 아빠와 엄마가 슬퍼하지 않도록, 저는 필사적으로 인내하고 있습니다… 해방의 날이 오고, 바다가 저를 받아줄 때까지요. \n 저는 깊은 물만이 저의 귀향이라고 생각했습니다. 그러나, 수호자님, 당신과 미사그 여러분이 계시기에, 저와 같은 항상 세상과 어울리지 않는 사람도 어떤 진실타래한 온기를 느낄 수 있게 되었습니다. 마치 수련이 떠오를 때, 태양이 그녀의 잎과 꽃잎을 입맞춤하는 것처럼요. \n 비록 어지럽지만, 저는 어떤 식으로든 이 마음을 종이에 남겨 당신께 보내는 것이 필요하다고 느낍니다. 가끔의 제 고집을 용서해 주세요. \n 저는 당신이 너무 이른 시간에 고요함에 묻히는 물속에서, 당신이 저에게 가져다준 소중한 떠오름을 아는 것을 바라는 것뿐입니다. \n 당신이 영원히 행복하고, 영원히 평안하길 바랍니다. \n\n 님피아"
  },
  Mail_124290_Name = {
    Text = "떠오르다"
  },
  Mail_124290_Sender = {Text = "님피아"},
  Mail_124291_Desc = {
    Text = "수호자: \n\n오늘 아침, 제 침대 머리맡에 편지가 하나 놓여 있었어요. 내용은 제 생일 파티에 초대한다는 것이고, 서명은 “화가” 클럽이에요. \n그래서 지난달 제가 가끔 여유가 있을 때, 산에게 “화가” 새 시즌 창작 대회의 모델을 맡기로 약속했던 걸 생각해냈어요. 그 전에 저는 몇 번이나 거절했었죠. 모델 대기석에 서서 가만히 그려지기를 기다리던 그 시간 동안, 저는 해양도약자 제단에 있었던 날들을 회상했어요. 그때 저도 모든 사람의 시선을 받았지만, 그 시선들 속에는 공포와 경외만 있었고, 한 점의 감동, 칭찬, 그리고 감상은 없었어요. \n오늘 밤 화가 클럽 로비에서 열리는 생일 칵테일 파티에서는 그날 열두 명 이상의 화가들이 정성껏 그린 손그림 작품들이 전시될 예정이에요. 당신의 미적 감각에 대한 자신감은 부족하지만, 많이 접하는 것은 나쁘지 않을 거예요. 신모가 당신을 초대 손님으로 특별히 초대하여 그들이 “나”를 해석한 작품을 함께 감상해보세요. \n\n “머피”"
  },
  Mail_124291_Name = {
    Text = "그리기 하는 사람……"
  },
  Mail_124291_Sender = {
    Text = "「머피」"
  },
  Mail_124292_Desc = {
    Text = "수호자: \n\n실타래비아가 말하길, 가끔 가까운 관계에 자신의 필요를 드러내는 것이 항상 따라다니는 공포를 완화하는 데 도움이 된다고 했어요. 이게 효과가 있을지는 모르겠지만, 오늘이 좋은 시점이라는 것은 확실타래해요. \n내가 하나의 소원을 이루어줄 수 있나요? 오늘 실타래험실타래의 배급을 모두 당신에게 줄 수 있어요. \n아니요, 커피콩 한 봉지가 아니에요. \n그 끔찍한 검정색이 나의 거의 모든 친밀한 관계를 빼앗아 갔고, 그림자처럼 나를 놀라게 했지만, 당신은 이미 그것을 이겨냈어요. \n당신은 우리가 미사그에서 안전하게 살 수 있도록 해주었고, 적어도 지금까지는 미사그에서 안전하게 살고 있어요. \n이제는 불건전한 카페인 의존에서 벗어날 때가 되었어요, 수호자, 오늘 저녁에 조금 시간을 낼 수 있나요? \n당신이 내 곁에 있다면, 아마도 빛이 충분하지 않은 곳에서 잠깐 소식할 용기를 낼 수 있을지도 몰라요, 비록 잠깐이라도요. \n\n안심하고 잠드는 것이 어떤 느낌인지 다시 기억하고 싶어요, 웬코르"
  },
  Mail_124292_Name = {Text = "소원…"},
  Mail_124292_Sender = {Text = "웬코르"},
  Mail_124293_Desc = {
    Text = "수호자{Male=선생님,Female=아가씨}:\n\n오늘 아침, 한 꿈이 나를 깨웠다. \n나는 꿈속의 모든 것을 세심하게 회상했다: 따뜻한 태양 아래 미풍이 불고, 장미와 튤립이 온 땅을 덮고 있으며, 천 마리의 은갈매기와 행복한 사람들이 함께 노래를 부르고 있었다… 나는 오랫동안 이렇게 행복한 장면에 있지 않았다. 아마도 나는 어린 시절의 저택, 코레트의 꽃방, 또는 서대의 어느 공원에 있었던 것 같다… 하지만 내가 돌아섰을 때, 나는 미사그의 아름다운 고딕 건물들과 당신을 보았다, 수호자{Male=선생님,Female=아가씨}. 당신은 꽃과 햇빛 사이에 서서 이 시의 가장 아름다운 구절이 되었다. \n나는 서대를 사랑한다, 수호자{Male=선생님,Female=아가씨}. 하지만 그 순간 나는 문득 깨달았다, 나는 이곳의 모든 것에 익숙해지고 사랑에 빠지기 시작했다는 것을, 세상에 서대보다 더 나를 사로잡는 곳이 드디어 생겼다는 것을. \n생일은 한 시기의 끝이자 또 다른 시기의 시작이다. 새 시기가 시작되는 이 날, 과연 미사그 뒷마당에서 피어나는 햇빛과 장미 사이에, 나와 함께 미풍을 듣고 나를 사로잡아 줄 그 분이 있을까? \n\n오를라"
  },
  Mail_124293_Name = {
    Text = "꽃과 시의 꿈"
  },
  Mail_124293_Sender = {Text = "오를라"},
  Mail_124294_Desc = {
    Text = "사랑하는 수호자님: \n\n얼마 전, 저는 당신에게 특별한 선물을 드리고 싶었습니다. 젠킨이 직접 당신을 위해 새 옷을 만들어보는 것이 어떻냐고 제안했는데, 저는 이 아이디어가 너무 좋다고 생각했습니다. \n이것은 제가 섬유 공장에서 일할 때 가장 잘 다루던 재단 스타일입니다. 지금 보아도 여전히 유행에 뒤떨어지지 않기를 바랍니다… 나머지는 제가 내 결정을 지지해준 것들로, 위의 그 활기찬 스트라이프와 체크무늬는 모두 다른 제가 제작한 것입니다. 그리고 이 비틀비틀 귀여운 쥐 모양은 고양이「24」가 꼭 추가하자고 한 것으로, 이는 브라운을 나타낸다고 하더군요. 고양이 성격의 제가 가장 좋아하는 것인데… 적합할지는 모르겠지만, 당신이 좋아하길 바랍니다. \n새해에도 저는 여전히 특별한 생일 소원이 없습니다. 당신은 항상 그렇게 부드럽고, 매년 저에게 잘 기념하라고 당부하십니다. 하지만 축하받는 것보다, 당신을 위해 직접 뭔가를 바느질할 수 있다는 것이 저에게 더 안정감과 기쁨을 줍니다. \n이 마음이 가득 담긴 새 옷을 받아주세요. \n\n메이슨"
  },
  Mail_124294_Name = {Text = "새 옷"},
  Mail_124295_Desc = {
    Text = "쳇: \n\n 믿을 수 없다, 위대한 미로의 주인으로서, 나는 이런 힘든 시련 속에서 또 한 해를 살아남았다. \n 잘 들어! 이 모든 것은 너와 이 바보 같은 학원의 잘못이다! \n 너희가 나에게 얼마나 헛소리로 세뇌를 하든지, 이런 잡다한 일들은 원래 전문적인 사람이 해야 할 일이다, 알겠어, 나는 이미 대단하다, 나는 그들을 노예라고 부르지 않았다. \n 그 고집 센 노인네들이 이걸 뭐라고 부르더라… 맞아, 발전. \n 잠깐만, 내가 왜 이 논리에 끌려가고 있는 거지, 아아아, 짜증나! (여기에는 편지 주인이 화를 내서 생긴 어지러운 주름들이 있다.) \n 상관없어, 내가 “발전”이 있으니 너도 너의 성의를 보여야 해, 올해 이렇게 성대한 날에, 너는 작년처럼 또 나에게 상기시켜 달라고 기다릴 수는 없겠지. \n 너에게 삼십 분을 줄게, 수호자, 선물을 가지고 나를 만나러 와. \n 그렇지 않으면 내가 너가 자고 있을 때, 내 자손이 네 얼굴 위로 기어오르게 할 거야. \n\n 아그리파"
  },
  Mail_124295_Name = {Text = "진보"},
  Mail_124295_Sender = {
    Text = "아그리파"
  },
  Mail_124296_Desc = {
    Text = "수호자!\n\n 저는 보았습니다! 얼마나 멋진 장면인가요! 이건 꿈이 아니라고 확신합니다! 저는 그곳에 서 있었고, 미사그 묘지의 웅장한 기념 조각상 옆에 서 있었습니다. 그곳에서 끝없이 이어지는 무명의 묘비를 바라보며, 그것들이 저에게 전례 없는 영감을 줄 것이라 확신했습니다. 그러나 생각보다 훨씬 더 많은 것을 주었습니다. 그것들은 경이로운 관대함으로 저의 메마른 상상력을 조롱했습니다.\n 저는 그 조사원들의 유령을 보았습니다. 그들은 안개 낀 아름다운 황혼 속에서 함께 일어섰습니다. 그들의 얼굴은 잘 보이지 않았지만, 그들의 움직임을 보았습니다—우아한 춤처럼, 신비로운 의식처럼. 그들은 검은 웅덩이를 향해, 미사그와 당신의 방향으로 인사하고 있었습니다. 현대 살롱의 예술가들은 개인을 그리는 데 집착하며, 종종 이러한 웅장한 장면을 비난하지만, 저는 그렇게 생각하지 않습니다. 식인귀의 무도회 앞에서 저는 기쁨을 느꼈고, 오늘 이 장면은 저를 눈물짓게 만들었습니다.\n 이건 우연이 아닐 거라고 생각합니다. 바로 오늘, 제 생일에 그들은 저에게 그들의 웅장한 춤을 보여주었습니다. 그들은 분명히 저에게 어떤 메시지를 전하려고 했던 것 같습니다. 저는 화가 외에는 아무것도 할 수 없지만, 그건 충분하지 않나요?\n 이 그림의 초안은 이미 그려졌습니다, 수호자, 꼭 제 화실타래에 와서 보세요! 이미 이름이 없는 전설의 조사원들이 저에게 전하고 싶은 소망이 제 그 그림 위에 담겨 있습니다!\n 저는 이 그림에 이름을 함부로 짓지 않았습니다. 이 자격은 오직 당신에게만 해당된다고 생각합니다.\n 덧붙임: 저는 정말로 시체를 찾으러 간 것이 아닙니다, 당신에게 보장합니다!\n\n 픽맨"
  },
  Mail_124296_Name = {
    Text = "조사원의 숙원"
  },
  Mail_124296_Sender = {Text = "픽맨"},
  Mail_124297_Desc = {
    Text = "안녕하세요, 수호자님: \n\n 당신은 두려워하고 있나요, 아니면—두려움과 기대감이 뒤섞여, 저의 생일에 축하의 명목으로 무언가를 가져올 것이라는 생각을 하고 있나요? \n 허울뿐인 친밀함, 갑작스러운 화려한 밤, 혹은 기교활한 또 매혹적인 혼란의 환경? \n 아, 모두 없어요, 저조차 가끔은 심각하고 지루한 주제를 이야기하곤 해요. \n 당신은 저의 존재가 어떤 것인지 잘 알고 있을 거예요, 쾌락에 빠져, 건물이 무너져도 상관하지 않고요. \n 사랑과 욕망은 이 세상에서 가장 큰 병인 지루함을 치료할 수 없지만, 권력과 혼란의 신맛을 이끌어내는 약재로는 더없이 적합해요. \n 하아, 이 천 년의 시간 동안 아마도 제가 연극 대본 연구에 너무 몰두한 탓에, 언제나 어떤 평범한 사람들이 제 마음을 꿰뚫어 보고, 제가 당신의 외롭고 의지할 데 없는 고독한 영혼을 보았다고 말하곤 해요. \n 후. \n 연극을 즐기는 저조차도 가끔은 구역질이 나곤 해요. \n 그런데 당신은…… 왜 저와 링크를 맺으려 하는 건가요, 통제하기 위해, 제약하기 위해, 힘을 빌리기 위해? \n 당신이 더 많은 것을 지키려면 반드시 더 높은 권력이 필요하고, 권력에 대한 갈망은 더 큰 야망을 낳게 됩니다. 그것이 언제 성숙할지, 언제 또 흡입되어 배 속으로 들어갈지…… 생각만 해도 저를 흥미롭게 만들어, 당신 곁에 더 많은 세월을 머물고 싶어지게 해요. \n 쉿, 저에게 답을 말할 필요는 없어요. \n 매년 이 날, 당신의 꿈을 하루 밤 동안 빼앗고, 당신의 야망이 성장하고 있는지, 당신의 의도가 변하고 있는지 맛보고 살펴보는 것이, 저 자신에게 주는 최고의 생일 선물이에요. \n 부디 이해해 주세요. \n\n “천선”"
  },
  Mail_124297_Name = {
    Text = "안온한 밤"
  },
  Mail_124297_Sender = {Text = "서"},
  Mail_124298_Desc = {
    Text = "수호자: \n\n훈련, 전투, 순찰, 내가 군대에 입대하는 순간부터, 모든 집단이 필요로 하는 일을 통해 내 모든 시간을 채우는 것에 익숙해졌다. \n후에 아란족을 이끌고 사막에서 이주하면서, 이러한 일들은 더욱 부풀어 올라 마치 법칙처럼 내 뇌리에 새겨졌다. 미사그에 오게 되면서도, 나는 항상 집단 일정의 우선순위를 개인업무보다 앞세웠다. \n하지만 다른 사람들과, 특히 너와의 관계에서, 나는 깨어남체로서든 인간으로서든, 우리가 필요로 하는 것은 오로지 나만의 시간을 갖는다는 것을 깨달았다. 중요한 사람들과의 관계를 경험하기 위해서 말이다. \n이 소중한 관계는 우리가 시간 속에 존재하는 것을 잠금시켜 주며, 우리의 존재에 정말로 대체 불가능한 의미를 부여한다. \n조금 무례할 수 있지만, 나는 오늘 모든 집단 일정을 취소하고 하루를 비웠다. \n몇 시간만 필요하다. 아니, 한 시간이라도, 아니면 몇 분이라도, 네가 나에게 개인적인 시간을 조금이라도 나눠준다면, 그것이 이 특별한 날을 보내는 의미가 될 것이다. \n\n엘바"
  },
  Mail_124298_Name = {
    Text = "개인 시간"
  },
  Mail_124298_Sender = {Text = "엘바"},
  Mail_124299_Desc = {
    Text = "작은 녀석: \n\n 1년의 시간은 당신에게는 길게 느껴질지 모르지만, 원질의 바다를 항해하는 자들에게는 그저 무한한 시간의 바다 속에서 순간적으로 사라지는 한 줌의 바닷물에 불과합니다. 다행히도, 이 바닷물 속에는 인상 깊은 맑은 물방울들이 몇 개 있습니다. \n 해우상점의 할인일은 그중 가장 소중히 간직해야 할 하나입니다. 단지 금권을 가져다 줄 뿐만 아니라, 오늘 하루에 한 분의 손님이 반드시 이 작은 가게에 올 것이라는 것을 알고 있기 때문입니다. \n 모든 사람과 사람 간의 연결은 비즈니스이며, 모든 비즈니스는 사람과 사람 간의 연결입니다. 각각의 손님은 그들만의 작은 가게에 들어오는 특정한 시간에 들어오고, 각 작은 가게는 그들만의 손님을 맞이하는 특정한 시간에 맞이합니다. 긴 시간 속에서 저는 수많은 보물을 보았습니다. 그러나 결국, 이러한 유치한 순간들은 가장 소중한 수집품이 될 것입니다. — 그것들은 이 긴 시간의 존재 이유입니다. \n 이 1년의 시간 속에서, 가장 소중한 새로운 수집품은 전시장롱 안에서 조용히 그 분을 기다리고 있습니다. \n 빨리 와요, 작은 녀석. \n 해우상점은 이미 일찍 문을 닫았습니다. 오늘, 그 문은 한 사람만을 위해 열립니다. \n\n 다포딜"
  },
  Mail_124299_Name = {Text = "신상품"},
  Mail_124299_Sender = {Text = "다포딜"},
  Mail_124300_Desc = {
    Text = "수호자:\n\n당신이 아직 기억하고 있는지 모르겠지만, 우리는 함께 문살 앞에서의 순간을 공유했습니다. 그날 나는 진리를 한 줄기 틈으로 열어, 당신에게 우주의 진실타래을 보여주었습니다. \n뜻밖에도, 당신이 수많은 세계를 바라보는 영원한 경험을 하는 동안, 나는 순간의 찰나에 이해할 수 없는 감정이 생겼습니다. \n나는 그 순간의 느낌이 무엇이었는지, 왜 진리를 아는 내가 이해할 수 없는 것이 생겼는지 자주 생각합니다. \n나는 오랫동안 생각했으며, 현실타래 세계를 기준으로 할 때, 그것은 '영원'이라 불릴 수 있는 시간입니다. \n이 상대적인 우주에서 다소 긴 시간 동안, 나는 이것이 아마도 아직 정의되지 않은 기적일 수 있다는 것을 깨달았습니다. \n이 특별한 날에, 나는 당신을 초대하여 나와 링크하고, 내 시선을 통해 내가 관측하지 못했던 존재를 관측해보기를 바랍니다. 이번에 우리가 관측할 것은… 더 이상 정해진 것이 아닐 것입니다. \n우리는 함께 진리 너머의 미래를 찾을 것입니다. \n\n타비"
  },
  Mail_124300_Name = {
    Text = "진리 외에"
  },
  Mail_124300_Sender = {Text = "타비"},
  Mail_124301_Desc = {
    Text = "수호자:\n\n올해도 예년과 같이, 저는 모든 다른 일을 멈추고 조용히 홀로 지내며 고향과 관련된 기억들을 다시 쓰고 새롭게 하려고 했습니다. \n그것들은 저에게서 더 멀어졌습니다. 비록 제가 이 인간 같은 몸에 익숙해지려고 억지로 노력하고 바다와 관련된 지식과 경험을 반복해서 기억하려고 해도, 점점 사라져가는 이 세상에서 잊는 것은 여전히 기억하는 것보다 너무나도 쉽습니다. \n유일한 위안은, 지금 우리가 리모리아에서 멀어진 여행자들이 여전히 이곳에 머물 수 있고, 우리의 왕의 뜻을 따르며 조용히 따르고, 조용히 대기할 수 있다는 것입니다. \n저는 당신이 이를 위해 희생하고 기울인 모든 것을 깊이 알고 있으며, 당신에게 감사를 어떻게 표현해야 할지 모르겠습니다. 이 몸이 리모리아로 돌아가기 전에, 제가 도움이 될 수 있는 일이 있다면, 저의 모든 빛을 기꺼이 바치겠습니다. \n\n진심으로, 파로스"
  },
  Mail_124301_Name = {Text = "등대"},
  Mail_124301_Sender = {Text = "파로스"},
  Mail_124302_Desc = {
    Text = "친애하는 수호자: \n\n미사그에 가입한 그날부터 복잡한 규칙들이 나를 얽어맸다. 회의장에서 하인을 데리고 산책하는 것은 허락되지 않고, 캠퍼스 광장에서 학생의 뺨을 밟는 것도 허락되지 않으며, 강당에서 다수의 집단 활동을 하는 것도 허락되지 않는다… \n미사그의 그 성가신 도덕 수호자들이 나를 억압했다. 이는 이사라우의 여왕이 누려야 할 삶이 아니다. 나는 내가 마땅히 누려야 할 모든 것, 황홀한 술, 부드러운 등, 그리고 사랑하는 하인을 누려야 한다… 내가 마땅히 마음껏 즐겨야 할 생일 이 날, 이러한 생각이 자연스럽게 떠올랐다. \n밤이 깊어지고, 사소한 일에 대한 인내심은 이미 바닥났다. 나는 당신에게 자정의 임무를 수행하라고 시키지 않을 것이고, 스스로 추측하게 두지도 않을 것이다. 나는 당신이 내 곁에 있어주기를 원한다. \n지금 내 영지로 와라, 주저하지 말고 불필요한 옷과 칭호를 모두 벗어라. \n오늘 밤과 이후의 모든 밤, 당신은 나의 것이다. \n\n이것을 당신의 첫 번째 영구적인 의무로 여길 수 있다. \n\n완다"
  },
  Mail_124302_Name = {Text = "규칙"},
  Mail_124302_Sender = {Text = "완다"},
  Mail_124303_Desc = {
    Text = "수호자: \n\n틴커트가 개인 콘서트 수익으로 생일 후의 은하 여행을 계획하고 나를 함께 데려가고 싶다고 말했어. 하지만… 내가 함께 가게 되면, 그녀는 나를 돌보느라 정신이 팔릴 거야. 나는 그녀의 행복이 나로 인해 줄어들기를 원하지 않아. \n그녀는 삶의 빛을 그렇게 사랑하고, 우주 속 수많은 색깔과 흐르는 별하늘에 매료되어 있어. 만약 내가 함께 간다면, 그녀는 그렇게 자유롭게 노래하고, 마음껏 응시할 수 없을 거야… \n그래서… 그녀를 설득해 줄 수 있을까? 그녀가 혼자 여행을 가고, 다른 행성에서 콘서트를 열고, 그녀가 동경하는 모든 풍경을 만끽할 수 있도록 해줘… 아니면 너 대신 내가 이번 여행에 참여해도 좋고? 결국 틴커트와 나는 너에게 정말 감사하고, 너의 은혜를 갚고 싶어… 네가 원한다면… \n그저, 이것이 내 의향이라는 걸 그녀에게 말하지 말아줘. 나는 그녀의 자유로운 여행에서 걸림돌이 되고 싶지 않아. \n\n파인트"
  },
  Mail_124303_Name = {
    Text = "여행에 대하여"
  },
  Mail_124303_Sender = {Text = "파인트"},
  Mail_124304_Desc = {
    Text = "은인:\n\n미사그에서 폴룩스와 함께 살던 이 날들, 이렇게 고요하고, 이렇게 밝아, 마치 한 편의 환상 같았다……\n폴룩스는 지금도 여전히 그 예절을 지키며, 우아하고 단정한 말을 하고 있지만, 나는 그가 조금씩 예전의 그 모습으로 돌아가고 있다는 것을 뚜렷하게 느낀다. '성자'에 속하는, 숨 막히는 거리감이 부드러운 일상 속에서 조용히 소멸하고 있다. 이 모든 부드러운 변화는 당신 덕분이다.\n나는 종종 이 은혜에 어떤 방식으로 보답할 수 있을까 생각한다. 나는 폴룩스처럼 손재주가 뛰어나지 않아 당신을 감탄하게 할 선물을 만들 수 없다. 비행의 즐거움은 당신도 나와 여러 번 함께 경험한 바 있다. 이 특별한 날에 당신과 기쁨을 나누는 방법에 대해 나는 오랫동안 고민해왔다.\n어쩌면…… 당신은 내 깃털을 좋아하실타래까요? 자주 사람들은 그것이 마음을 고요하게 해주는 부드러움을 가지고 있다고 말한다. 그러니, 만약 당신이 언젠가 피곤함을 느끼거나 단지 조용한 곳이 필요하다면, 언제든지 내 곁으로 오세요. 내 날개는 영원히 당신을 위해 내려드릴 것입니다.\n\n카스토르"
  },
  Mail_124304_Name = {Text = "깃털"},
  Mail_124304_Sender = {
    Text = "카스토르"
  },
  Mail_124305_Desc = {
    Text = "내 작은·수·감자: \n\n 미사그에서 최근 인기 있는 롤플레잉 게임이 있다고 들었어. 마녀, 늑대인간 같은 거… 쳇, 전혀 로맨틱하지 않네~ 나는 더 재미있는 게임을 생각했어! \n 이렇게, 너는 죄수 역할을 하고, 나는 간수 역할을 할게. 내가 작은 채찍을 휘두를 때, 큰 신음소리를 들어야 해~ 촛불이 너의 몸 위에서 흐르며 뜨거운 고통과 즐거움을 가져다 줄 거야… 아, 그 장면을 상상하기만 해도 벌써 달콤해지네~ \n 어라, 여기까지 읽고 너는 또 찡그렸겠지? 정말 착하지 않네, 오늘은 내 생일이야~ 사랑하는 작은 죄수, 내 조금은 제멋대로인 소원을 들어줘야지? \n 정말 안 된다면… 그럼… 너가 간수가 되고, 내가 너의 포로가 되는 건 어때? 나는 너를 만족시켜 줄 거야~ \n\n 판디아"
  },
  Mail_124305_Name = {
    Text = "캐릭터 연기"
  },
  Mail_124305_Sender = {Text = "판디아"},
  Mail_124306_Desc = {
    Text = "수호자: \n은인, 오늘은 제 생일입니다. 이 특별한 날에, 제 최근 소식을 전하고 싶습니다: 골리아와 로탄 선생님의 지도 아래, 저는 점점 제 혈맥 속의 힘을 느낄 수 있는 것 같습니다. 그것은 더 이상 잠들어 있지 않고, 매번 연습할 때마다 제 몸 안에서 저음으로 울리고, 넘쳐흐르며, 점차 해방되고 있습니다. \n\n\n\n제가 최종 변화에 도달하고, 더 순수한 심해족이 될 수 있는 시점이 언제인지 정확히 말할 수는 없습니다. 아마 내일, 아마 다음 주, 아마 다음 달… 하지만 이 과정이 얼마나 길더라도, 그 길에서 얼마나 많은 고난이 있더라도, 당신이 처음 저를 격려해 주신 말씀은 제가 항상… 깊이 기억하고 있습니다. 저는 계속 노력할 것입니다. \n\n그리고 제가 사과해야 할 한 가지가 있습니다. 방금 미사그 우체국에서 알게 되었는데, 현금을 동봉하여 발송하려면 추가로 2위안의 수수료를 내야 한다고 합니다. \n작년 몫을 보충하기 위해, 저는 저축에서 다시 한 번 지출할 것입니다. 그것들은 저에게 쉽게 얻어진 것이 아니지만, 심해의 혈맥은 약속을 반드시 지킬 것입니다. \n\n카이커스"
  },
  Mail_124306_Name = {
    Text = "수수료……"
  },
  Mail_124306_Sender = {
    Text = "카이커스"
  },
  Mail_124307_Desc = {
    Text = "수호자: \n\n잘 들으세요, 오늘 밤 무슨 일이 있어도 저와 함께 「그 가게」에 가야 합니다.\n위장용 옷은 이미 당신에게 발송했으니, 반드시, 절대 다른 사람에게 우리를 알아보게 해서는 안 됩니다!\n「그 가게」의 한정 디저트가 판매 시작되었고, 어디서 왔는지 모르는 그 끔찍한 놈이 분명 한 무리를 매수했을 겁니다. 그들이 본 양반님의 행적을 알게 해서는 안 됩니다.\n그 놈이 저를 구매하지 못하게 하려고 렌티니언의 모든 케이크 가게 한정 제품을 예약했지만, 음… 흥흥.\n본 양반님은 이미 「그 가게」의 주방장을 미리 매수해 두어서, 가장 맛있는 그 제품을 메뉴에서 빼달라고 했습니다.\n흥, 본 양반님은 오늘 그 놈에게 어떤 일은 단순히 돈으로 해결할 수 없다는 것을 알려줄 것입니다.\n그때 우리는 조용히 뒷문으로 몰래 들어가서, 세 번 암호화된 철 상자를 열면 그 한정 제품 중의 한정 제품을 얻을 수 있습니다.\n보상으로, 저는 한 조각(지우기), 반쪽의 케이크를 당신에게 나눠줄 것입니다!\n오늘 밤 11시에, 방에서 기다리고 있으니, 반드시, 꼭 와야 합니다! 알겠습니까!\n절대 비밀로 해야 합니다, 그렇지 않으면 그 놈이 우리의 행적을 알게 되어 모든 것이 끝장납니다!\n\n머피"
  },
  Mail_124307_Name = {
    Text = "케이크 쟁탈전"
  },
  Mail_124307_Sender = {Text = "머피"},
  Mail_124308_Desc = {
    Text = "수호자: \n\n안타깝게도 말씀드리게 되었습니다. 렌티니언 극장은 카시아 대사의 마법 공연을 전면 취소했습니다. 그 이유는: 티켓 가격이 너무 비쌌고, 최근에 목격된 이상한 일들이 너무 많아 마법에 대한 흥미가 떨어졌으며, 연속된 몇 차례의 공연에서 관객이 실타래종되어 현재까지 돌아오지 않았고, 자주 경찰이 극장 사장에게 찾아와 카시아 대사에게 공연 중단을 요청하며 조사를 협조하라고 요구하는 등 여러 가지 이유가 있습니다. \n최근 블랙풀의 이상 동작의 영향을 받아, 제 공연이 가끔 작은 실타래수를 하게 되었습니다. 이런 것들은 사소한 문제지만, 두 번째 이유는 카시아 대사가 절대 용납할 수 없는 것입니다! \n이를 위해 깊이 고민한 끝에, 결국 완벽한 새로운 공연을 생각해냈습니다! 시체 조작, 죽은 자의 부활, 차원 횡단, 감정 감염, 거대한 촉수……모두 대수롭지 않은 일입니다! 이전에 그 끔찍한 차원 사냥개에 영향을 받아 시간 조작은 업계의 금기였지만, 그 악성 개가 봉인된 이후, 카시아 대사의 마법커리어는 새로운 단계로 나아갈 것입니다! \n공연 시간은 오늘 밤으로 정해졌고, 완전히 무료입니다. 수호자님은 첫 번째 줄 중앙 좌석이 이미 예약되어 있으며, 놀라운 인터랙티브 세션이 기다리고 있습니다! 새로운 시대의 가장 위대한 마법 공연에서 첫 번째 인터랙티브 관객이 되는 영광을 누리세요! \n카시아 대사의 영광을 되찾기 위해! \n\n카시아"
  },
  Mail_124308_Name = {
    Text = "카시아, 마법을 다시 위대하게 만들어라!"
  },
  Mail_124308_Sender = {Text = "카시아"},
  Mail_124309_Desc = {
    Text = "주인님: \n\n 실타래비아 언니가 방금 나에게 올해 생일에 그들이 나를 관람차에 태워 줄 것이라고 말해줬어요. \n 리리는 그림책에서 관람차는 아주 크고 큰 바퀴로, 그 위에 앉으면 천천히 하늘로 올라가면서 옆에서 작은 새들이 날아다니는 걸 볼 수 있다고 읽어봤어요. 정말 행복하게 들려요. \n 그런데 실타래비아 언니는 \"사실타래 몇 가지 차이가 있다\"고 했어요. 리리는 그게 무슨 뜻인지 잘 모르겠어요. \n 그녀는 또한 관람차가 가는 곳이 너무 높아서 한 분의 보호자를 데려가는 게 좋다고 했어요. \n 리리는 보호자가 무슨 뜻인지 이해하지 못하지만, 주인님과 함께 구름 사이를 여행하고 싶어요. \n 점심 먹고, 저는 실타래비아 언니와 함께 기숙사 밖에서 당신을 기다릴게요. \n\n 리리"
  },
  Mail_124309_Name = {Text = "관람차"},
  Mail_124309_Sender = {Text = "릴리"},
  Mail_124310_Desc = {
    Text = "수호자(이번에 드디어 제대로 썼어요! 대단하죠!):\n\n또 이런 감성적인 글을 쓸 때가 왔군요, 저는 이미 익숙해졌어요. 지금, 저는 브라운과 함께 오늘 당신에게 무엇을 대접할지 고민하고 있어요!\n동쪽 지역 골목의 길거리 음식은 물론 맛있지만, 오늘은 당신과 브라운을 좋은 곳에 데려가려고 해요—즉, 당신들 서쪽 지역 사람들이 좋아하는 그런 음식들 말이죠.\n예를 들어 소스와 향신료가 가득 묻은 비밀 요리들, 양은 적고 접시는 크고, 가격은 터무니없이 비쌉니다. 마치 돈을 탈취하는 것과 같아요. 이런 생각을 하니, 지갑이 바람이 빠지는 것 같아요, 그건 아마 돈이 떠날 때 남기는 상처일 거예요.\n하지만 당신은 제게 언니와 브라운을 제외하고는 가장 중요하고 가장 좋아하는 사람이에요. 동쪽 지역 사람들은 자기 사람에게 인색하지 않으니, 오늘의 모든 비용은 저와 브라운이 부담할게요.\n우리를 가볍게 보지 마세요, 우리는 우유 배달과 신문 배달로 소통하고 심부름하며 다른 사업으로도 꽤 많은 돈을 벌었으니, 안심하세요!\n\n당신의 좋은 친구 젠킨과 브라운"
  },
  Mail_124310_Name = {
    Text = "오늘 나는 브라운과 결제했어!"
  },
  Mail_124310_Sender = {Text = "젠킨"},
  Mail_124311_Desc = {
    Text = "친애하는 수호자: \n\n 당신은 아마 실타래비아가 미사그 지하 카지노를 완전히 파괴한 위대한 업적에 대해 이미 들었겠죠? 하지만 오늘은 제 생일입니다. 만약 아드레날린이 솟구치는 좋은 활동이 없다면, 연례 좋은 날을 낭비하는 것이 아닐까요? \n 여러 번 고민한 끝에, 당신을 제 좋은 친구로 초대하여 최근 서대에서 이곳으로 도망쳐온 밤의 괴도에게서 대박 박물관의 보물을 훔친 사건을 함께 해결하고자 합니다. \n 제가 교외의 “아폴로 바”에서 술을 마시고 있을 때, 그들이 비싼 보석을 약식한 전과를 자랑스럽게 이야기하는 것을 우연히 들었습니다. 바텐더는 신경 쓰지 않았지만, 저는 알아챘습니다. 에메랄드, 사파이어, 다이아몬드 왕관, 그리고 도난당한 물건과 완전히 일치합니다. 그들의 경계를 피하기 위해, 저는 그들에게 잘 표시를 해두었고, 그들이 본거지로 돌아올 때 사람과 물건을 함께 잡을 준비를 했습니다. \n 오늘 밤 7시, 교문 앞 미사그 전용 열차 정차 지점에서 만나요. \n\n 라이커"
  },
  Mail_124311_Name = {
    Text = "사냥 계획"
  },
  Mail_124311_Sender = {Text = "라이커"},
  Mail_124312_Desc = {
    Text = "수호자:\n\n미사그의 시간은 다른 곳보다 더욱 가벼운 것처럼 돌고 있다. 몇 차례의 박수, 몇 차례의 커튼콜, 일 년의 시간이 또 지나갔다. \n이번 해 동안, 나는 몇 가지 새로운 습관을 가지게 되었다. 예전에는 내가 무대에 서면, 아무리 붐비는 극장이라도 내 눈에는 텅 비어 있었다. 나는 텅 빈 무대 위에서, 텅 빈 극장을 향해 춤을 추었고, 세상에서 들리는 것은 오직 한 쌍의 무용화의 소리뿐이었다. 하지만 지금은, 막이 열릴 때마다 나는 너를 보게 된다. 수많은 좌석이 텅 비어 있지만, 오직 너만이 나를 바라보고 있다. 너의 시선 속에서, 나의 춤은 다시 의미를 가지게 되었다. \n일 년이 지나도, 너의 춤사위는 여전히 그렇게 어색하지만, 너가 무대 아래에서 보내는 그 뛰는 시선은 쉽게 무대 위의 평범한 춤걸음을 초월할 수 있다. 그 시선은 하나의 계곡처럼, 나의 점점 평범해지는 춤걸음을 하나하나 씻어준다. 이 무용가들과 관객의 함께하는 춤 속에서, 나는 내가 항상 추구해온 성전으로 점점 가까워지고 있다. 나는 드디어 깨달았다. 춤에 있어 관객과 무용가는 동등하게 중요하다는 것을. \n몇 달 동안 나는 한 곡의 춤을 준비하고 있었다. 그것은 너의 시선 속에서 잉태되어, 너의 실타래루엣 속에서 태어났다. 이제 그것은 준비가 되었다. \n나는 그것이 오늘 밤, 너가 그것의 첫 번째 증언자가 되는 것을 기대할 것이라고 생각한다. \n\n리즈"
  },
  Mail_124312_Name = {
    Text = "무용가와 관객"
  },
  Mail_124312_Sender = {Text = "리즈"},
  Mail_124313_Desc = {
    Text = "수호자:\n\n이곳의 수용 덕분에, 올해 나는 왕과 많은 대화를 나눴습니다. 신국의 강림은 여전히 멀지만, 리모리아의 시간은 미사그에서 계속되고 있는 것 같습니다. \n당신과 왕은 나에게 믿음이 내 삶의 전부가 되어서는 안 된다고 말씀하셨습니다. 나는 고집을 부렸지만, 최근의 경험은 내 마음가짐에 변화를 가져온 것 같습니다. 너무 잦은 기도는 아마도 우리 주님을 귀찮게 할 수 있습니다. 경건한 봉사 외에도, 주님은 자신의 신도들이 그들만의 얕은 삶을 가지기를 원하실타래지도 모릅니다. \n이 점을 깨달은 후, 나는 몇 가지 작은 변화를 시도해 보았습니다. 나는 렌티니언의 모든 유명한 제과사들을 방문하여 그들에게 베이킹 방법을 배웠습니다. 그들은 몇 가지 비법이 있었고, 나는 주님의 축복으로 그들을 입을 열게 했습니다. 어제, 나는 처음으로 몇 가지 시도를 해보았고, 몇몇 신도들은 맛이 괜찮다고 말했지만, 그들의 미각은 충성과 마찬가지로 의심스럽습니다. \n오늘 당신을 내 정원으로 초대하여 맛보시길 원합니다. 나는 당신의 취향을 믿으며, 당신의 솔직함도 믿습니다. 맛이 좋지 않다면, 직접 말씀해 주시기를 바라며, 나는 진지하게 개선할 것입니다. \n감사합니다. \n\n미리암"
  },
  Mail_124313_Name = {
    Text = "또 다른 전문 분야"
  },
  Mail_124313_Sender = {Text = "미리암"},
  Mail_124314_Desc = {
    Text = "수호자님:\n\n생명과 죽음의 의미에 대해 이미 지겹도록 들으셨겠죠? nekropolis의저것들 언데드들의 화려한 기억 속에서, 내가 배운 가장 중요한 것은, 식사의 의미를 탐구하는 것보다, 눈앞의 식탁에 있는 음식 자체가 더 중요하다는 것입니다. \n인류의 원시 시대에, 우리의 조상들은 이미 식사의 모든 내포를 탐구해냈습니다——열정, 욕망, 향유. 살아남기 위해 먹는 것이 아니라, 먹기 위해 살아가는 것입니다. 안타깝게도, 그 순수하고 원초적인 욕망은 긴 세월 속에 점차 잊혀졌고, 이 집단은 점점 더 복잡해졌습니다. \n그래서, 오늘 저녁의 주제를 「순수」라고 명명했습니다. 이 의식적인 날에, 모든 복잡한 일들은 우리 곁에서 멀어질 것입니다. 이 식탁 위에는 오직 순수한, 원초적인 열정과 욕망만이 존재하며, 오직 감상자와 음식만이 있을 것입니다. 오직 너와 나만이 있습니다. \n내 가장 진실타래한 초대를 받아주세요. 당신은 나를 거절하지 않을 것입니다, 그렇죠? \n\n두레인"
  },
  Mail_124314_Name = {
    Text = "순수한 만찬"
  },
  Mail_124314_Sender = {
    Text = "둘레세인"
  },
  Mail_124315_Desc = {
    Text = "내 가장 사랑하는 수호자님: \n\n 내 마음이 자라고 있는 것 같아요… 깨어남체에게는 이상하게 들릴지도 모르지만, 이전과는 다르게 되었어요. 어떻게 당신에게 설명해야 할까요? \n 그 좋은 사람들은 어떻게든 부드럽고, 애정 어린 태도로 나를 대해주며 나를 따뜻하게 하려 해도, 형이 떠난 후 내 가슴은 항상 비어 있었고, 태양 아래 걸을수록 그 따뜻함이 나를 긁어대었어요. 오히려 어둡고 습한 곳이 더 편안하게 느껴져서, 마치 그 차가운 곳에 계속 있으면 형의 엄격하고 아픈 사랑이 떠나지 않을 것만 같았어요. \n 하지만 지금, 당신과 더욱 친밀해진 이 세월 속에서, 매번 당신을 볼 때마다, 당신이 나에게 주는 그 고통이 내 피부에 떨어지고 뼈에 전해질 때마다—아, 내 가슴 속의 행복이 날로 커져가요. 당신이 나를 가차 없이 때리고, 모욕하고, 짓밟을 때마다, 나는 이 세상에 항상 내가 진정으로 쉴 수 있는 곳이 있다는 것을 알게 돼요. \n 이 행복이 내년까지 이어질 수 있을까요, 그 다음 해까지도요? 생일 소원으로 바라는 것이 모두 이루어진다면, 내가 바라는 유일한 것은 당신이 나를 경멸하는 눈빛으로 바라봐 주는 것과, 고통… 더 많은 고통이에요. 당신이 손을 들어올릴 때, 내가 가장 먼저 느끼는 것은 그 익숙하고 잔인하며 행복한 향기예요. \n\n 정말 정말 당신에게 맞고 싶어하는 레이아"
  },
  Mail_124315_Name = {
    Text = "나의 마음"
  },
  Mail_124315_Sender = {Text = "레이아"},
  Mail_124316_Desc = {
    Text = "수호자\n\n비록 최근의 연습 상황이 궁금하지만, 오늘은 당신에게 음악 훈련을 강요하기 위해 온 것이 아님을 안심하세요.\n오늘 아침, 나는 평소처럼 음악실타래로 갔지만, 35분이나 늦었습니다. 아침 7시에 음악 훈련을 하는 것은 수십 년 동안 유지해온 습관인데, 오늘 쉽게 깨졌습니다. 이유는 학교 복도를 지나갈 때, 나는 한 무리의 울새 지저귐을 들었기 때문입니다.\n오랫동안 유지해온 습관이 깨지는 것은 쉽게 받아들일 수 있는 일이 아니며, 나에게는 더욱 그렇습니다. 이상하게도, 나는 상상했던 것처럼 자신에게 실타래망하거나 분노하지 않았습니다. 처음에는 약간의 당황함을 느꼈지만, 곧 내 머릿속에 떠오르는 멜로디가 즐거웠음을 인정해야 했습니다.\n렌티니언은 항상 울새의 지저귐 속에서 깨어남하며, 이 소리는 매일 듣지만, 이상하게도 이렇게 오랜 세월 동안 나는 처음으로 그것들을 주목했습니다. 나는 복도에서 그들의 노래를 조용히 듣고 있었고, 그 35분 동안 이 우주에서 가장 높은 멜로디가 그들의 작은 목구멍에 숨겨져 있다고 느꼈습니다.\n아마도 이곳의 생활이 나를 게으르게 만들거나, 이곳의 분위기가 나를 부드럽게 만든 것 같습니다. 어쨌든, 나는 그것이 당신과 관련이 있다고 생각합니다.\n나는 10분 만에 이 변화를 기꺼이 받아들였습니다. 생명은 음악과 같이 고대의 리듬과 변화를 가지고 있으며, 태어나는 날, 어쩌면 이러한 변화가 일어날 운명적인 지점이었을 것입니다. 당신에게 감사하고 싶습니다. 내가 무시했던 것들을 조용히 듣는 기회를 주어 감사합니다. 즐거움, 맞습니다. 나는 이것이 내가 새로운 악장으로 나아가는 시작이 될 것이라고 생각합니다.\n그래서 오늘 저녁에 당신을 초대하여 교외의 밀림으로 함께 가고 싶습니다. 자연의 저녁 소리는 아침과 다르지만, 나는 그것들이 우리의 음악적 삶에 새로운 영감을 줄 것이라고 생각합니다.\n\n하멜른"
  },
  Mail_124316_Name = {
    Text = "자연의 소리"
  },
  Mail_124316_Sender = {Text = "하멜른"},
  Mail_124317_Desc = {
    Text = "귀인:\n\n방금 저는 파인트가 당신에게 보낸 생일 이메일을 보았습니다……역시, 누나는 항상 다른 사람을 배려하고, 자매 간에는 결코 빚이 없으며, 저는 그녀를 제 부담으로 생각한 적이 없습니다. 그녀의 보호가 없었다면 지금처럼 순회 콘서트를 할 기회도 없었을 것입니다.\n존경하는 귀인, 당신은 항상 저에게 가장 중요한 청중이었습니다. 그래서 이번에 저는 조용히 당신을 위해 한 장의 배표를 준비했습니다——진심으로 당신을 초대하여 우리와 함께 이 별간 여행에 나서길 바랍니다. 당신이 함께한다면 누나의 마음속 부담감도 많이 덜어질 것이라고 믿습니다.\n또한 여행 중에는 절대 당신의 개인 시간을 방해하지 않을 것을 약속드립니다. 저와 누나는 당신이 이 여행을 마음껏 즐기고, 각 성운과 미지의 만남을 자유롭게 느끼기를 바랍니다.\n\n틴커트"
  },
  Mail_124317_Name = {
    Text = "여행 초대"
  },
  Mail_124317_Sender = {Text = "틴커트"},
  Mail_124318_Desc = {
    Text = "수호자: \n\n생일이 다가오는데, 생각은 자주 서대로로 돌아가네요. 특히 예술 전시회에서의 조각들이 그리워요. 그것들은 조용한 자세로, 수없이 나의 영감의 문을 두드렸어요.\n작업실타래에서 하루 종일 조각과 함께 지내면서, 예술적인 교류가 부족해 오래전부터 지루함을 느끼고 있었어요. 작년 이맘때, 나를 위해 생일을 축하하기 위해 수많은 조각 케이크를 만들었어요. 처음의 흥미진진함은 이제 평온으로 돌아왔어요.\n이제는 행동이 불편해 서대로에 돌아가는 것은 사치가 되었어요. 만약 당신이 조사를 위해 가는 계획이 있다면, 예술 전시회에서의 신작을 주의 깊게 살펴봐 줄 수 있나요? 당신의 눈을 통해 다시 그 다채롭고 포용적인 예술의 아름다움에 닿고 싶어요.\n보답으로, 나는 당신을 위해 하나의 조각을 더 만들고 싶어요, 제목은 《서대로의 수호자》로 할까요? 어떻게 생각하나요?\n\n산"
  },
  Mail_124318_Name = {
    Text = "서대 회상"
  },
  Mail_124318_Sender = {Text = "산"},
  Mail_124770_Desc = {
    Text = "수호자: \n\n매년 내가 실타래험실타래에 들어갈 권한이 취소되기 때문에 이 날은 즐겁지 않은 방식으로 특별해졌습니다. 비효율적인 잡일에 시간을 낭비하지 않기 위해, 나는 기록 보관소에 갔습니다. \n그곳에서 나는 두 가지를 발견했습니다. 그 중 하나는 과제 노트로, 가치 없는 빈칸으로 가득 차 있었습니다. \n또 다른 하나도 과제 노트였는데, 그것은 내가 지식의 광대함을 과소평가하고 있음을 깨닫게 해주었습니다. 그 위의 추론 과정과 결론은 세상에 존재하지 않는 것보다 가치가 더 낮은 것이 있다는 것을 알게 해주었습니다. \n이 두 개의 과제 노트에는 같은 이름이 적혀 있었습니다. 우리 위대한 미사그 수호자 %player%. \n에리카가 말해주길, 당신이 나에게 어떤 생일 선물을 줄지 궁금해한다고 합니다. \n당신은 나에게 하나의 답을 줄 수 있습니다. \n나는 또한 어떤 답의 사실타래이 나를 더 놀라게 할지 궁금합니다. 단순히 극한으로 발휘된 게으름과 태만인지, 아니면 당신이 한 학기 동안 진지하게 공부했지만 결국 헛된 절망 속에서 이런 학문 쓰레기를 남겼는지. \n만약 전자라면, 충분한 이유가 있고 당신이 수업에서 가르친 지식을 완전히 습득했음을 증명할 수 있다면, 나는 당신을 대신해 학원에 과제 면제를 요청할 수 있습니다. 물론, 이것이 당신을 완전히 게으르게 만들 가능성을 지지한다는 것은 아니지만, 당신이 계속해서 내 시험을 통과할 수 있다면, 나는 그런 고리타분한 사람이 아니며 내 학생에게 약간의 특권을 주는 것을 개의치 않습니다. \n만약 후자라면, 당신의 첫 번째 보호자로서, 믿으세요. 당신이 얼마나 형성하기 어려운 재료이든, 내가 익힌 기술 중에서 당신의 지나치게 빈곤한 지식을 향상시킬 수 있는 방법을 찾을 수 있습니다. 무지에서 벗어나기 위해 노력하는 고통의 상황에서 구해줄 수 있습니다. \n오늘 오후 4시에, 나는 기록 보관소에서 당신의 수업 지식 습득 정도를 직접 조사할 것입니다. 늦지 않도록 하세요. \n\n돌"
  },
  Mail_124770_Name = {Text = "특권"},
  Mail_124770_Sender = {Text = "돌"},
  Mail_124771_Desc = {
    Text = "미사그의 강아지: \n\n올해도 너는 그 반복되는 일상에 갇혀서, 사고를 치고, 세상을 구하고, 친구를 사귀고, 새로운 지식을 배우며, 계속해서 세상에 평소와 같게 보이도록 허위의식을 만들어내고 있구나. \n사실타래 너의 뇌를 몸에서 꺼내고, 영지가 한 차원에서 다른 차원으로 이동해도, 너의 우스꽝스럽고 웃길 정도로 바쁘고 분주한 모습에는 영향을 미치지 않는구나. \n정말 바쁘고 시끄럽구나, 사랑스러운 강아지야. \n너는 그 사실타래을 믿지 않겠지, 너는 그들의 고통을 이어가고, 멸망의 과정을 더 지연시키고 싶어하는데, 너의 목적은 무엇인가? 너는 정말로 바보처럼 행동하고 있는 건가, 아니면 인간이 정말 이렇게 바보가 될 수 있는 건가? 내가 너의 이 몸의 뇌피질을 확실타래히 잘라본 적이 있다 하더라도, 이것들은 여전히 나에게는 풀리지 않는 수수께끼야. \n축하해, 너는 정말로 나에게 약간의 동요를 일으켰어, 내가 너를 관찰하는 것이 이렇게 큰 즐거움을 준다면, 모든 것이 무의미하다고 말할 수 있을까? \n너가 잘하는 그런 무의미한 것처럼, 무의미하게 기도해보렴, 기도하는 대상은 누구든 상관없어. \n너가 나를 계속 억제할 수 있기를 기도해, 강아지야, 그렇게 되면 나와 너 모두 무의미한 세계에서 약간의 즐거움을 찾을 수 있을 거야. \n\n“돌”"
  },
  Mail_124771_Name = {
    Text = "기도하라"
  },
  Mail_124771_Sender = {
    Text = "융해·돌"
  },
  Mail_124772_Desc = {
    Text = "파트너:\n\n매년 생일 날에 너에게 편지를 쓰는 것이 무의식적으로 하나의 습관이 된 것 같아.\n나는 첫 번째로 너에게 편지를 썼던 생일을 아직도 기억해. 아버지가 처음으로 내 생일 일정을 내가 직접 계획하겠다고 약속했을 때, 나는 너를 초대해서 함께 외출했었지. 그리고 나중에, 우리는 함께 많은 첫 경험을 겪었어.\n그 이후 많은 것들이 많이 변했지만, 곰곰이 생각해보면 아무것도 변하지 않은 것 같아. 우리는 여전히 우리가 정한 그 길을 가고 있고, 여전히 서로 곁에 있으며, 너는 나에게 가장 중요한 파트너야.\n그래서, 아버지가 방금 케이크를 보내주면서 내가 저녁에 그가 마련한 연회에 참석할지 물어봤지만, 나는 오늘 밤에 다른 계획이 있어.\n렌티니언에서 새로운 영화가 개봉했어. 아주 인기가 많지만, 학원과 협회가 함께 확인했으니, 그 안에는 어떤 영적인 반응도 없다고 해.\n이것은 정말로 아주 훌륭한 “일반” 작품이라는 것을 의미해.\n나는 마침 두 장의 티켓이 있어. 나는 소렐 부인에게 귀찮게 하지는 않았다고 가정할 수 있어, 왜냐하면 그 티켓은 정말 구하기 힘들거든.\n그럼, 파트너, 이 시간을 나에게 줄 수 있을까? 어쩌면 우리는 우리가 매일 처리해야 하는 비정상적인 상황에서 잠시 벗어나 서로의 곁에서 “일반” 저녁을 보낼 수 있을지도 몰라.\n그 후의 매일 아침, 우리가 깨어날 때, 세상에서 무슨 일이 일어나든지 나는 너와 함께 맞설 거야.\n\n라모나"
  },
  Mail_124772_Sender = {Text = "라모나"},
  Mail_124773_Desc = {
    Text = "수호자:\n\n나와 그 나 사이의 특별한 연결 덕분에, 그리고 너와 나 사이의 링크 덕분에, 비록 항상 너 곁에 있지는 않지만, 나는 너의 지난 1년 동향에 대해 약간 알고 있다.\n너는 다른 세계에서 활동하고 있으며, 여전히 그것에 '희망'이라는 이름의 변화를 가져다 준 것 같다. 매일 검은 연못을 바라보면서도, 그와 같은 빛나는 에너지가 나에게도 따뜻함을 주었다.\n나는 이전의 일정을 다시 되찾기 시작했지만, 예전과는 다르게 이제는 필연적인 적멸을 마주하는 데에 헛된 투쟁의 마음가짐이 아니다. 너는 나에게 새로운 것을 가르쳐 주었다. 필연적인 끝에 이르기 전에, 존재하는 모든 것이 지속을 위해 전력을 다하는 과정이야말로 문명, 영혼, 의지가 의미 있는 이유이다.\n내가 있는 세계에 비춰볼 때, 이 시간은 얼마나 짧든 간에, 나는 계속해서 시도할 것이다. 단지 익숙한 얼굴들을 다시 보고, 그들과 몇 마디를 나누기 위해서라도, 이 시도는 결코 의미 없는 것이 아니다.\n너가 멈추기 전까지 나는 이 길을 계속 걸어갈 것이다. 나를 너와 나란히 서는 어떤 방법으로 여길 수 있도록 제발 내 마음대로 하게 해줘. 그러면 아마도 너는 끊임없이 나아가는 길 위에서, 항상 이렇게 한 나를 생각할 수 있을 것이다. 나도 너와 같은 일을 전력으로 하고 있다는 것을.\n\n“라모나”"
  },
  Mail_124773_Sender = {
    Text = "“라모나”"
  },
  Mail_124774_Desc = {
    Text = "대상을 죽이는 것은 간단하지만, 사후 처리는 귀찮은 일입니다.\n본래 올해는 작년의 관례를 따라 당신을 도와 한 사람을 더 죽이려 했습니다.\n하지만 당신이 제가 드린 지난 선물을 계속 사용하지 않는 것을 보고, 심사숙고한 결과, 이 때문인지 모르겠지만, 제 실타래수를 발견했습니다.\n당신은 완전히 안심하셔도 됩니다. 과거의 고용주들에게는 적을 죽이는 서비스만 제공했지만, 다양한 문제를 피하기 위해 흔적을 파괴하는 데에도 경험이 많습니다. 당신이 죽이고 싶은 녀석이 그러한 복잡한 규칙과 질서의 보호 아래에 있더라도, 어떤 심리적 부담도 가질 필요가 없습니다. 제가 모든 것을 처리해 드릴 것입니다.\n저는 당신이 누구에게도 추적당하지 않도록 보장합니다.\n후보를 정한 후, 이름을 저에게 알려주시면, 제가 어디에 있든 즉시 달려가 도와드리겠습니다.\n즐거운 명절 되시길 바라며, 제가 태어난 이 날에 당신도 행복하길 바랍니다, 수호자.\n\n\n히로"
  },
  Mail_124774_Name = {
    Text = "자주 사람을 죽이는 사람들은 모두 안다\n……"
  },
  Mail_124774_Sender = {Text = "히로"},
  Mail_124775_Desc = {
    Text = "좋아, 분명히 너희는 이런 행동을 멈출 준비가 되어 있지 않은 것 같아. 내가 알기로는, 그건 내가 이미 “선물”을 주는 관습에 익숙해졌기 때문이야. \n하지만 언젠가는 너희가 이런 선의에 대해 후회할 날이 올 거야, 나를 믿어. \n지금 생각해보니, 그건 내가 가장 후회하는 일 중 하나일지도 몰라. 젠장, 내가 사람을 죽인 것에 대해 후회할 줄은 몰랐어. \n누구보다도 나는, 이른바 사과의 무가치함을 잘 알고 있어. 하지만 그 날이 오기 전까지, 나는 뭔가를 만회하기 위해 최선을 다할 거야. 단지 내가 그렇게 하고 싶기 때문이야. \n너희가 앞으로 그 일 때문에 나를 원망할 때, 그로 인해 어떤 심리적 부담도 느낄 필요 없어. \n나는 너희의 분노를 온전히 받아들일 거야. \n\nH"
  },
  Mail_124775_Name = {
    Text = "너는 후회할 것이다"
  },
  Mail_124775_Sender = {
    Text = "혈쇄·히로"
  },
  Mail_124776_Desc = {
    Text = "수호자:\n\n또 다시 태어나는 이 날이 왔다. 원래는 생명을 축하하는 날이기에, 매년 이 날이 오면 나는 기묘한 감정을 느낀다. \n내 출생은 마치 죽음을 쫓기 위해 존재하는 것처럼 보인다. 죽음이라는 주제를 벗어난 후, 생명… 또는 의식이 여전히 이어지는 순간, 나에게는 도대체 무엇을 의미할까? \n생전에는 고통과 죄책감의 끌림이 내 생명과 너무나도 얽히고설켜서, 마치 죽음이 찾아온 후에야 비로소 생명이 진정으로 나의 것이 된 것 같았다. \n작년, 올해, 어쩌면 앞으로의 매년. 나는 거의 끝이 없는 긴 시간을 경험할 수 있었다. 매일매일이 전날과 비슷하면서도 또 다르다. 생명이 더 이상 고통과 목적에 포박되지 않을 때, 그 끝은 어떤 모습일지, 혹은 소위 말하는 끝이 다시 올 수 있을까? \n이 명제는 너무 거대해서, 나는 잘 이해하지 못하겠다. \n하지만 이 낯선 생각의 감정을 기록하고 싶다는 마음은 너무나도 진실타래하다. 나는 마치 답이 명확하게 드러나는 것 같은 느낌을 받는다. \n적어도 나에게는, 이 실타래질적이고 소중한 순간들이 있다. 내 생각이 아무리 복잡하든, 내가 뿌리를 찾기 어려운 한이 있든, 나는 분명히 그것들이 어디로 떠날 수 있는지, 어디에 받아들여질 수 있는지를 알고 있으며, 나도 마찬가지로 당신에게 그것들을 드러내고 싶다. \n어쩌면 내년 오늘, 나는 더 자아를 찾을 수 있을지도 모르지만, 지금은 당신과 나만 아는 이 작은 의존을 자기중심적으로 보존하고 싶다. \n그래, 수호자, 당신과 미사그의 모두는 내 마음속에 아무도 모르는 뿌리이다. \n감사합니다, 변함없이, 당신이 영원히 행복하고, 영원히 평안하기를 바랍니다. \n\n닝피아"
  },
  Mail_124776_Name = {Text = "근계"},
  Mail_124776_Sender = {Text = "님피아"},
  Mail_124777_Desc = {
    Text = "여는 최근에 새로운 이완 방법인 신국 점심 시간을 발명했습니다.\n일반적인 짧고 급한 점심 시간과는 달리, 신국 점심 시간을 진행할 때 여는 오랜 시간 앉아 있었던 청석 왕좌에서 떠나, 팔을 접촉하여 소리를 차단하는 구체를 만들고, 특수 제작한 바닷물로 전체 공간을 채웁니다.\n이 바닷물은 여가 원하는 향기를 내고, 여가 보고 싶어하는 풍경으로 변하며, 다양한 방향에서 적절한 강도로 여의 몸을 지탱해줍니다.\n따라서 여가 어떤 자세를 취하더라도, 최고급 깃털 침대에 있는 듯한 따뜻한 포근함을 경험할 수 있습니다.\n그때 여는 마음에 드는 향기 속에서 마음을 이완하고, 세상과 격리된 고요함을 즐기며, 여가 가장 좋아하는 베개에 기대어 편안히 잠에 빠질 수 있습니다.\n여가 가장 마음에 드는 신하로서, 여는 생일 날에 가장 적합하게 너와 이 여유를 나누고 싶습니다. 네가 원한다면, 지난번에 말했던 비밀 장소로 와 주세요. 너의 안전은 걱정하지 마세요, 여가 너를 위해 단독으로 공간을 마련해줄 것이니, 여의 외부 꿈의 영향을 받지 않을 수 있습니다.\n가장 편안한 베개를 잊지 말고 가져오세요.\n\n툴루"
  },
  Mail_124777_Name = {
    Text = "점심 시간"
  },
  Mail_124777_Sender = {Text = "툴루"},
  Mail_124778_Desc = {
    Text = "나의 밝은 등불: \n\n 나는 카스토르와 함께 미사그의 생활에 적응하였고, 교회의 피비린내 나는 음모에서 탈출한 후, 나는 과거의 나를 되찾고 있다는 느낌이 든다. \n 비록 지금 일상적인 말과 행동 속에는 여전히 '성자'의 그림자가 피할 수 없이 섞여 있지만, 곧 그 오만함과 소외감을 완전히 씻어내고, 신에 대한 겸손과 길을 이어가겠다는 결의를 고수할 수 있을 것이라 믿는다. \n 조금 전에 나는 예상치 못한 선물을 받았다. 그것은 아름답게 제본된 책으로, 고향으로 돌아가 어린 시절을 되찾는 사람에 대한 이야기이다. 함께 온 종이에는 \"당신이 가장 처음의 자신을 빨리 찾기를 바란다\"라는 글귀가 적혀 있었다. \n 이 문장이 눈에 들어오자마자, 과거의 기억들이 떠오른다—— 미사그 모든 이들의 관심, 밝은 등불 너의 안내, 그리고 형의…… 따뜻한 포옹. \n 그래서 올해 생일에, 나는 미사그의 모든 이들을 초대하여 나와 형의 생일 연회에 함께해 주기를 바란다. 모든 이들의 도움이 없었다면, 우리는 결코 처음의 시간을 되찾을 수 없었을 것이다. \n 나는 최근 한동안 저축한 저축으로 한 식당을 통째로 예약했다. 그곳의 주방장은 세계 각국의 요리에 대한 지식이 풍부하여, 각각의 사람들이 거기서 자신이 가장 익숙한 맛을 맛볼 수 있을 것이라 믿는다. \n\n 폴룩스"
  },
  Mail_124778_Name = {
    Text = "어린 시절 되찾기"
  },
  Mail_124778_Sender = {Text = "폴룩스"},
  Mail_124779_Desc = {
    Text = "나는 교외의 그 지하 아레나의 초대를 받아들이기로 결정했다. 죽고 죽이는 경기를 하러 가기 위해서. \n 트라우트 클럽에서의 생활은 좋지만, 너무 평범하다. 매일 물고기를 죽이거나 또 물고기를 죽이는 것뿐이다. 아마도 나는 트라우트를 완전히 정복했지만, 트라우트를 정복했다고 할 수는 없다! \n 내 몸속의 전사들의 피가 끓고 있다. 그들은 항상 사람의 피를 끓게 하는 전투를 갈망해왔고, 이제 기회가 왔다. \n 나와 연락한 그 대머리는 나를 위해 세 마리의 나타이 거대 비단뱀과 두 마리의 귀신 얼굴 곰, 네 마리의 세리나슨 악어와 이름을 기억할 수 없는 이상한 생물들을 찾아왔다고 말했다. 내가 한밤중 내내 마음껏 싸울 수 있을 만큼 충분하다. \n 나는 그들이 경기를 오늘로 정해주도록 특별히 요청했다. 생일 날에 너에게 보여주기 위해서—— 나는, 유우하시, 마지막 로마 전사로서 세상의 모든 맹수들을 정복하는 장관을! \n 오늘 경기장은 더 이상 트라우트의 찌꺼기로 가득 차지 않을 것이며, 대신 피와 이종 생물의 시체로 가득 찰 것이다! \n\n 유우하시"
  },
  Mail_124779_Name = {
    Text = "정복 맹수"
  },
  Mail_124779_Sender = {
    Text = "우브하시"
  },
  Mail_124780_Desc = {
    Text = "“은 열쇠 기사”:\n\n수호자! 방금 나는 「환영」호를 개조하고 있을 때, Mosk가 갑자기 나에게 큰——봉지의 부품을 보내줬어, 내 생일 선물이라고 하더라고. 그래서 오늘이 내 생일이라는 걸 생각해냈어!\n그래서 나는 너에게 편지를 급히 썼어, 정말, 오늘을 또 잊어버리다니, 분명히 나는……얼마나 많은 쪽지를 썼던 거지?\n하지만 이건 중요하지 않아, 중요한 건, 내가 전에 말했던 생일 날에 해야 할 일이 기억났어——나는 「환영」호를 타고 너와 Mosk와 함께 런티니언을 한 바퀴 돌아야 해!\n비록 Mosk는 기계에 대해 전혀 모르지만, 그녀의 그 봉지에는 부품이 너무 많아서 내가 필요한 모든 부품을 다 찾을 수 있을 정도야. 지금 개조된 「환영」호는 슈퍼 강화 프로토타입 버전이야(임시로)!\n나는 이 모험에 이름을 지었어, 노틸라와 수호자 그리고 Mosk와 「환영」의 모험이라고, 어때, 정말 직접적이고 기억하기 쉽지 않아? 이렇게 하면 이 모험을 확실타래히 잊지 않을 거야.\n헤헤, 정말 기대돼, 수호자 조금만 기다려줘, “환영 기사” 노틸라와 “소용돌이 기사” Mosk가 곧 도착할 거야!\n「환영」 모험단, 출격!\n\n모터를 힘껏 돌리며 오는 노틸라"
  },
  Mail_124780_Name = {
    Text = "「환영」 출격!"
  },
  Mail_124780_Sender = {Text = "노틸라"},
  Mail_124793_Desc = {
    Text = "존경하는 위대한 <Del:귀여운> 수호자{Male=선생님,Female=아가씨}님:\n\n cough, 오랜만에 연락하네요, 우리 사랑하는 수호자{Male=선생님,Female=아가씨}님 저를 그리워하셨나요~\n 이제 당신은 미사그의 유명인사입니다, 모든 학생들이 당신의 용감한 업적을 배우고 있으며, 당신과 조금이라도 관련된 것은 모두 암시장에서 고가에 팔리고 있습니다!\n 하지만 이건 당연한 일이죠, 누가 당신이 '살아있는 전설'이며, 미사그 유일한 수호자이기 때문인가요?\n 지난 1년 동안 미사그에서도 많은 흥미로운 일들이 일어났습니다——오레타가 몇몇 진저브레드와 친구가 되었고, 돌 교수님은 뇌 통을 바꾸기 위해 17개의 실타래험실타래을 폭파시켰고, 카스토르는 아그리파에게 속아 그녀의 시험을 도와줬는데, 결국 그건 일반 상식 수업이었고, 최종 성적이 그녀가 혼자 본 것보다 더 나빴습니다!\n 아, 맞다, 그 끔찍한 쥐 같은 녀석, 제 소중한 필름을 훔쳐갔어요, 그건 제가 간신히 찍은 '24' 아가씨의 고양이 형태였거든요!\n 그 외에도 많은 일들이 있어요, 제가 정리해봤으니, 학교 신문의 새해 특별판으로 함께 보내드릴게요.\n 뭐라고요? 제가 당신과 어떻게 연락했는지 궁금하신가요? 헤헤, 그건 비밀이에요, 제가 많은 독점 기밀을 사용해 어떤 한눈에 봐도 다루기 힘든 부인과 바꾼 거라고는 절대 말하지 않을 거예요!\n 새해에는 함께 힘내요, 새해 복 많이 받으세요, %player%!\n\n 한나 피즐리"
  },
  Mail_124793_Name = {
    Text = "신년 특별호"
  },
  Mail_124793_Sender = {
    Text = "한나 피즐리"
  },
  Mail_124794_Desc = {
    Text = "창백한 사자: \n\n은상밤이 다가오니, 먼저 여기서 당신에게 가장 진솔한 축복을 전할 수 있게 해주세요. \n\n지난번 내가 릴리안 빈민원을 방문했을 때, 몇몇 아이들이 나에게 몰래 물어봤습니다. “겨울 건너 사자는 정말 존재하나요?” \n나는 이 아이들이 왜 그런 생각을 했는지 궁금했습니다. 내가 기억하기로 지난해에는 각각의 아이들이 “겨울 건너 사자”에게서 선물을 받았던 것 같은데요. \n결과적으로 아이들은 나에게 이렇게 말했습니다—— “나는 멋진 남자가 다이아나 원장에게 선물을 주는 걸 봤어요, 그는 겨울 건너 사자 같지 않았어요!” \n아마도 귀족님께서 빈민원에 선물을 주실타래 때, 아이들에게 우연히 발견되어 후속적인 작은 의문이 생긴 것 같습니다. \n\n그래서 올해 은상밤에, 나는 매우 전통적인 겨울 건너 사자 의상을 두 세트 준비했습니다. 창백한 사자님과 함께 겨울 건너 사자로 변신해 이 아이들에게 선물을 전하고 싶습니다. \n나는 반드시 아이들 중 한 명이 밤에 몰래 눈을 뜨고, 우리의 빨간 옷과 빨간 모자를 기억해내고, 동지 축제 때 신이 나서 모두에게 말할 것이라고 믿습니다—— “나는 겨울 건너 사자를 봤어요!” \n또한 당신을 위해 특별히 선물을 준비했습니다. 당신이 좋아하길 바랍니다. \n동지 축제 즐겁게 보내세요. \n\n살바도르"
  },
  Mail_124794_Name = {
    Text = "겨울 건너 사자"
  },
  Mail_124794_Sender = {
    Text = "살바도르"
  },
  Mail_124991_Desc = {
    Text = "존경하는 수호자님:\n“다중 치유·Rerun” 리메이크 이벤트가 종료되었습니다. 수호자님께서 남은 활동 통화 “기억 퍼즐”을 각각 “장미 금권”× 40으로 교환하여 회수할 예정이니, 수호자님은 꼭 확인하시기 바랍니다."
  },
  Mail_124991_Name = {
    Text = "기억 퍼즐 회수"
  },
  Mail_124991_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_125448_Desc = {
    Text = "존경하는 수호자님:\n“해성 구소식” 이벤트가 종료되었습니다. 수호자님의 남은 “배꿀사탕”을 각각 “장미 금권”× 40으로 교환해 드렸으니, 확인해 주시기 바랍니다."
  },
  Mail_125448_Name = {
    Text = "배꿀사탕 회수"
  },
  Mail_125448_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_126321_Desc = {
    Text = "존경하는 수호자님께:\n「스스로를 옭아매는 자」 이벤트가 종료되었습니다. 수호자님께 남은 「벨벳석 티켓」을 1매당 「장미 금권」× 40의 비율로 전환하였으니, 꼭 확인해 주시기 바랍니다."
  },
  Mail_126321_Name = {
    Text = "벨벳석 티켓 회수"
  },
  Mail_126321_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_126934_Desc = {
    Text = "수호자: \n\n 또 이 특별한 날이 왔군요. 하하, 걱정하지 마세요, 올해는 당신에게 심리적 암시를 주지 않을 겁니다. 저는 단지 가장 특별한 환자를 초대하고 싶어요, 어딘가로 마음을 달래러 가요. \n 그곳에는 무성한 숲과 맑은 강물이 있으며, 자연의 기운이 가득해 당신이 철강 숲의 피로를 잊게 해줄 것입니다. 부드러운 카펫과 따뜻한 난로, 밝은 조명이 있어 도시의 빠른 속도에서 오는 압박을 덜어줄 것입니다. \n 우리는 그곳에서 산책하고, 책을 읽고, 이야기할 수 있습니다. 당신이 무엇을 털어놓고 싶든, 저는 기꺼이 들어줄 것입니다. \n 아, 그 장면을 상상하는 것만으로도 제 마음이 설레네요… \n 아시다시피, 지금 이 순간 당신은 조금 불안할 것입니다. 결국, 제가 당신의 달콤한 고통의 기억을 즐기지 않을 것이라고 보장할 수는 없으니까요. 하지만 당신은 여전히 올 것입니다, 그렇죠? \n 오늘이 제 생일이기도 하고, 당신은 저를 필요로 하니까요, 저에게 털어놓고 싶고, 저의 경청이 필요하니까요. \n 착한 아이, 저는 이해합니다. 그리고 당신을 기다릴 것입니다. 자, 바쁜 일상과 무거운 책임을 잊고 이 평화로운 순간을 즐기세요. \n\n 클레멘타인"
  },
  Mail_126934_Name = {
    Text = "안정적인 순간"
  },
  Mail_126934_Sender = {
    Text = "클레멘타인"
  },
  Mail_126935_Desc = {
    Text = "또 지루한 하루다.\n여러 방법을 시도해봤지만——블레셋 전통 연회, 렌티니엔 갱단들과 하는 유치한 장난들, 그 어느 것도 거인왕 탄생의 날에 걸맞은 선물이 되지 못했다.\n블레셋인들은 전투와 살육을 즐거움으로 삼는다. 예전의 이날에는 가장 강한 전사들과 진영에서 함께 모여 싸우며, 힘과 피로 이 위대한 날을 기념했다.\n평화. 지루하기 짝이 없는 평화. 너희 인간들이 평화를 갈망하는 마음은 이해한다. 모든 이가 전사의 야망을 품고 있는 건 아니니까. 하지만 이 허울뿐인 평화가 위대한 블레셋의 주군에게 영향을 미친다고 생각하지는 마라.\n한때 내 것이었던 모든 것——영토, 재물, 권력, 블레셋의 불멸하는 영광……그것들을 되찾는 날, 반드시 너를 초대하겠다, 비밀지기여. 위대한 거인왕이 그의 영광을 되찾는 것을 지켜볼 수 있도록, 내 곁 가장 귀한 빈객의 자리에 앉혀주겠다.\n이 지루한 하루를 그냥 끝내버리려 했는데, 방금 소식을 들었다. 흩어졌던 갱단들이 연합을 결성해 오늘 만찬에서 거인왕을 포위 섬멸하려 한다는군.\n블레셋의 전쟁에 비하면 이건 그저 유치한 놀음에 불과하다. 하지만 이 지루한 평화의 나날 속에서 이런 여흥거리라도 생겼으니, 그나마 위안이 되는군.\n블레셋의 주군이 전장을 누비는 위풍당당한 모습을 다시 한번 눈에 새겨두어라. 내 곁에 서든, 내 맞은편에 서든, 어느 쪽이든 상관없다.\n단, 서둘러라. 너무 늦으면 시신이나 수습하는 신세가 될 테니.\n\n골리앗"
  },
  Mail_126935_Name = {
    Text = "여흥 프로그램"
  },
  Mail_126935_Sender = {Text = "골리아"},
  Mail_126936_Desc = {
    Text = "존경하는 수호자님:\n\n안녕하세요. 미사그의 학생과 교직원에게 더 나은 서비스를 제공하기 위해, 에리카는 며칠 전 스스로 유지보수 및 업그레이드를 진행했습니다. 당신은 이번 업그레이드 결과의 평가 대상자로 행운이 닿았습니다. 이번 평가는 오프라인 방식으로 진행되며, 자동인형 에리카에 설치된 최신 LY-S-761 감정 모듈의 기능 평가를 해야 합니다. 이 테스트는 약 90분이 소요될 예정이니, 일정을 미리 계획하여 충돌을 피하시기 바랍니다.\n다음은 이번 평가의 내용입니다:\n1. 에리카와 최소 15분간의 개방형 심층 대화를 진행해 주세요. 주제는 「생일」을 중심으로 하여 에리카의 특정 감정 이해 범위와 깊이를 평가합니다.\n2. 「생일 선물 증정」 장면을 시뮬레이션하여 에리카와 상호작용하며, 그 감정 인식 및 공감 반응의 정확성, 유연성 및 편안함을 평가합니다.\n3. 평가 중후반에 에리카가 앞선 대화에서 언급한 개인 세부사항(예: 그녀의 생일에 대한 태도, 인식 등)을 의도적으로 언급하여 장기 상호작용 기억 및 연관 능력이 정상적으로 작동하는지 평가합니다.\n\n상기 평가가 완료된 후, 에리카에게 「에리카, 생일 축하해」라고 말하여 평가를 종료해 주세요. 인형은 자동으로 데이터 업로드 모드로 들어갑니다.\n참여해 주셔서 감사합니다. 평가 완료 후 에리카가 특별한 작은 선물을 드릴 것입니다. 또한 앞으로도 계속 지원해 주시기 바라며, 당신의 가장 친근한 조수 에리카가 항상 곁에 있겠습니다.\n\n에리카"
  },
  Mail_126936_Name = {
    Text = "생일 업그레이드 평가"
  },
  Mail_126936_Sender = {Text = "에리카"},
  Mail_126937_Desc = {
    Text = "하아, 오늘 도대체 무슨 일이야? 내가 어디를 가든지 모두가 의식적으로 나를 회피하고 있어? 심지어 내가 입을 열기도 전에, 손을 흔들며 여기 아프고 저기 아프다고 하니, 내가 결투를 요청할 방법조차 없네. \n 드물게 “생일” 이 날에는 특별한 이유 없이도 당당히 다른 사람과 싸울 수 있는데, 이렇게 되면 평소와 다를 게 없잖아? \n 쳇, 작년에 그들을 그렇게 심하게 때리지 말았어야 했는데. 하지만 어쩔 수 없는 일이야. 결국 이 별이 탄생하기 전부터 나는 끊임없이 검술을 연마해왔고, 평범한 사람들은 감당할 수 없는 게 당연하지. \n 그런데 너는 그들과 달라, 너는 수호자잖아! \n 그래서 내가 무슨 말을 하고 싶은지 알겠지? 작년 그 장소에서, 우리 시원하게 한 판 붙자. 이번에는 우리의 전투를 방해할 사람은 없을 거야. \n\n 로탄"
  },
  Mail_126937_Name = {
    Text = "유일한 상대방"
  },
  Mail_126937_Sender = {Text = "로탄"},
  Mail_126938_Desc = {
    Text = "가장 가장 가장 사랑하는 주인님:\n\n주인님, 들으셨나요? 오늘 시장님의 저택에서 초호화 무도회가 열리는데, 모든 신사 숙녀들은 이 무도회에 참석하는 것을 자랑스럽게 여깁니다.\n물론, 메이드인 가렌은 참석할 자격이 없어요. 하지만 주인님, 미사그 수호자님, 저의 사랑하는, 가장 사랑하는 주인님, 주인님은 세상의 모든 아름다운 것에 어울리며, 당연히 이번 무도회에도 어울립니다.\n그래서 가렌이 주인님을 대신해 초대를 수락했어요. 그리고 주인님을 위해 마차도 미리 예약해 두었고, 모든 준비가 완료되었습니다. 그때 가렌과 함께 시장님 집으로 가기만 하면 됩니다~\n가렌은 가장 예쁜 옷을 입고, 가장 빛나는 보석을 착용하여 모두에게 만능 메이드의 위력을 보여드릴 거예요. 주인님을 위해 체면을 세워드리고, 주인님을 빛내드릴게요!\n아, 주인님이 이 편지를 보실타래 때쯤이면 저는 이미 주인님의 문 앞에서 기다리고 있을 거예요. 새로운 옷과 보석을 가져온 하인들도 이미 대기 중이고, 유일한 작은 문제는 이 서비스에 대한 비용이 아직 지불되지 않았다는 것입니다…\n하지만 저의 가장 착하고 사랑스러운 주인님은 이런 작은 일로 걱정하지 않으실타래 거죠? 시장님이 우리를 기다리고 계십니다~\n\n가장 사랑스럽고, 가장 빛나는 메이드\n가렌"
  },
  Mail_126938_Name = {
    Text = "호화로운 무도회"
  },
  Mail_126938_Sender = {Text = "카렌"},
  Mail_126940_Desc = {
    Text = "수호자 수호자! 며칠 전에 젠킨이 오레타의 집과 비슷한 곳을 찾았다고 했어, 그곳의 이름은 물…… 음, 오레타가 잊어버렸어. \n 어쨌든, 젠킨은 그곳에 돌고래, 작은 물고기, 수족관, 그리고 아주 많은 해파리들이 있다고 했고, 그들은 모두 오레타의 친구가 되고 싶어한다고 했어! \n 오레타는 친구를 좋아하고, 오레타는 많은 많은 친구를 원해, 그래서 오레타는 생일에 가장 좋아하는 친구, 즉 수호자를 초대하고 싶어. \n 빨리 짐을 싸고 나와 함께 출발하자, 오레타는 더 이상 기다릴 수 없어. \n\n 많은 많은 새로운 친구를 만나고 싶은 오레타"
  },
  Mail_126940_Name = {
    Text = "수족관의 새 친구!"
  },
  Mail_126940_Sender = {Text = "오레타"},
  Mail_126941_Desc = {
    Text = "수호자: \n\n오늘 새벽에 나와 함께 바닷가를 산책해 주셔서 감사합니다. 그 파도 소리와 밝은 별빛은 저를 편안하게 해주었고, 아주 오랫동안 전의 일을 떠올리게도 했습니다. \n그때, 선원들은 저와 대화하는 것이 금지되어 있었기 때문에, 대부분의 시간 동안 저는 끊임없이 변화하는 바다를 바라보며 공중에 떠 있는 바다 새들만을 지켜보았습니다. 선원들은 그 바다 새들이 나는 모습을 보며 무의식적으로 저에게 소원을 빌곤 했습니다. \n가끔 그들은 새가 되어 고향으로 돌아가고 싶어 했고, 사랑하는 이의 곁으로 날아가고 싶어 했습니다; 가끔 그들은 항해가 빨리 끝나기를 바라며 배에 실타래린 화물로 부유한 재물을 바꾸고 싶어 했습니다; 가끔 그들은 로맨틱한 사랑을 만나거나 전설 속의 바다 요정 인어를 만나는 기도를 하기도 했습니다… \n하지만 아무리 복잡한 소원이라도 깊은 밤에는 통일되어 편안한 잠의 갈망으로 변하게 됩니다. 이때, 저는 그들의 기도에 응답하여 바람을 평화롭게 하고, 바다를 부드럽게 만듭니다. \n그러니, 만약 수호자님이 잠을 이루기 힘들다면, 새벽에 바닷가에서 혼자 돌아다니지 말고 저를 찾아와 주세요. \n저는 당신의 부담을 나누고, 유용한 사람이 되고 싶습니다. 당신의 안식을 지키는 것이 지금 제가 할 수 있는 일입니다. \n이것은… 제가 이 특별한 날에 바친 「소원」이기도 합니다. \n\n셀레스트"
  },
  Mail_126941_Name = {
    Text = "편안한 잠이 되시길 바랍니다"
  },
  Mail_126941_Sender = {
    Text = "셀레스트"
  },
  Mail_126942_Desc = {
    Text = "운명의 은총을 받아, 미사그 대학의 수호자, 현명하고 인자하신 주군: \n\n만안!\n 이 편지를 쓸 때, 저는 계속 망설였습니다. 그러나 정직함 또한 기사의 미덕 중 하나입니다. 주군의 기사로서, 저는 당신에게 모든 충성을 바쳐야 하며, 절대 숨김이 없어야 하므로, 당신에게 진실타래을 말씀드려야 합니다——\n생일 이 날, 주군, 제가 당신의 방에 와서 저에게 잠자리 이야기를 읽어 주시기를 요청합니다.\n부디 저를…… 주군의 곁에 기대게 해 주시고, 당신이 이야기해 주신 꿈같고 아름다운 이야기 속에서 잠이 들게 해 주세요.\n사실타래, 이것은 제가 어린 시절에 가지고 있던 바람 중 하나였습니다. 그러나 기사의 훈련은 한 순간의 게으름도 용납하지 않기에, 저는 이미 이야기를 들을 나이가 지나버렸고, 그래서 그것을 마음 속에 묻어두고, 한 번도 입에 담지 않았습니다. 그러나 당신…… 주군 당신은 다릅니다. 저는 당신에게 아무것도 숨기고 싶지 않습니다……\n만약 주군께서 이 요청이 부적절하다고 생각하신다면, 저에게 알려 주세요. 그때부터 저는 다시는 이렇게 지나친 요청을 하지 않겠으며, 두 배로 열심히 훈련하겠습니다.\n당신의 답변을 기다리겠습니다.\n\n오지에"
  },
  Mail_126942_Name = {
    Text = "기사의 요청"
  },
  Mail_126942_Sender = {Text = "오지에"},
  Mail_126943_Desc = {
    Text = "작은 석탄 공: \n\n 오늘, Mosk, 생일! \n 친구가 말했어요, 생일, 편지 쓰고, 작은 석탄 공에게, 작은 석탄 공이 올 거예요, 놀러! \n Mosk는, 편지를 쓸 줄 몰라요. 하지만, 친구는 할 수 있어요! \n 친구가, Mosk에게 가르쳐줬어요. Mosk는, 기뻐요! \n 사실타래, Mosk는, 생일을 잊어버렸어요. \n 하지만, Mosk는 작은 석탄 공과 놀고 싶어요! \n 그래서, Mosk는 오늘이 생일이라고 결정했어요! \n 작은 석탄 공은, 조개껍질을 모아요, 금색, 흰색, 다 있어요~ \n 작은 석탄 공을 보니, 기뻐요~ 친구가 요리해요, 맛있어요~ \n 작은 석탄 공은, 옛날 장소에 있어요~ \n 친구가, 큰 만찬을 차렸어요! 함께 먹어요! \n Mosk는, 기다릴게요~ \n\n Mosk"
  },
  Mail_126943_Name = {
    Text = "생일! 놀러 와!"
  },
  Mail_126943_Sender = {Text = "모스"},
  Mail_126944_Desc = {
    Text = "수호자: \n\n며칠 전, 당신은 유성우에게 소원을 빌고 싶다고 말씀하셨기에, 이번 항해를 특별히 준비했습니다. 제 초대를 받아주셔서 감사합니다. 약속대로 해변에서 제때 당신을 기다리겠습니다. \n안심하세요, 이번 항해는 단기 항해이며, 주변 해역을 철저히 조사했습니다. 유성우가 떨어지는 위치까지 안전하게 안내하고, 당신이 운석을 얻는 것을 도와드릴 것을 약속합니다. \n이렇게 하면 당신은 직접 유성에 손을 대고 소원을 빌 수 있으며, 이렇게 가까운 거리에서 유성도 당신의 마음을 들을 것이고, 당신의 소원을 이루어줄 것입니다! 당신의 소원을 빌게 하는 사람이 되는 것은 제가 해본 가장 특별한 일 중 하나로, 정말 영광입니다. \n다시 한 번 감사드립니다. 당신 덕분에 이 특별한 날에 새로운 “항로 인도”의 사명을 찾게 되었습니다. 꼭 제때 약속을 지켜주세요. 저는 당신의 도착을 계속 기다리겠습니다. \n\n크퍼산트"
  },
  Mail_126944_Name = {
    Text = "손에 닿을 듯한 소원"
  },
  Mail_126944_Sender = {
    Text = "크퍼산트"
  },
  Mail_129637_Desc = {
    Text = "안부 전합니다: \n\n몇 번째 시계탑 뒤의 꽃밭을 지나쳤는지 기억나지 않지만, 그곳의 장미 정원에 우연히 주목했던 적이 있었습니다. \n그 이후로 나는 여러 차례 이곳을 지나며, 검은 연못의 불안한 물결, 죽음과 대면의 순간, 시간의 흐름이 거꾸로 흐르는 순간을 경험했습니다. 그 모든 것들은 언제나처럼 그곳에 우뚝 서 있었습니다. \n이 장면은 나와는 상관없는 기억을 깨어남시켰고, 라모나가 당신에게 주고 싶어했던 그 꽃다발의 장미를 떠올리게 했습니다. 그래서 나는 조금 안심하게 되었습니다. \n비록 당신과 나는 서로 다른 차원에 있지만, 나는 항상 믿습니다. 어떤 어려움에 처하더라도 당신과 그 「라모나」는 항상 침착하고 두려움 없는 자세를 유지하며 해결의 길을 찾을 수 있을 것이라고요. \n결국, 세상이 어떻게 변하든 장미들은 여전히 피어오르니까요. \n\n「라모나」"
  },
  Mail_129637_Name = {
    Text = "장미 정원…"
  },
  Mail_129637_Sender = {
    Text = "“라모나”"
  },
  Mail_129806_Desc = {
    Text = "수호자: \n\n 해성의 저택에서 화려한 불빛이 켜졌다. 지금 당신은 어디에 있으며, 곁에는 누구와 함께하고 있나요? \n 세초, 고국에서 가장 중요한 날, 단결과 신생을 축하하는 축제. 이 날은, 저 자신이 여러 번 경험했지만, 결코 지루함을 느끼지 않았다. 추운 겨울이 지나고, 만물이 자라나다. 사람들은 이렇게 간절히 바라며, 이 땅처럼 모든 불행을 어제에 던져버리고 새로운 시작을 맞이하기를 원한다. \n 그 오래된 상처와 욕망은 쉽게 버릴 수 있는 것이 아니다. 구시대와 신시대를 맞이하는 것은 얼마나 아름다운 소망인가… 어쩌면 고통은 다시 자라날 것이고, 욕망은 결코 사라지지 않을 것이지만, 적어도 오늘 밤, 사람들은 잔을 높이 들어 축하할 것이다. 새로운 세계와 새로운 자신을 기념하기 위해서. \n 그래서 구세와 신세가 교차하는 시점에 사람들은 불꽃놀이로 맞이한다. \n 모든 흥미로운 것들 중에서 불꽃놀이는 저의 가장 사랑하는 것이다. 모든 사람들은 그것을 바라보며, 타오르고, 하늘로 올라가며, 피어나는 것을 본다. 마치 신을 바라보듯, 그 짧고도 비할 데 없는 광채를 바라본다. \n 당신은 주목해본 적이 있나요? 불꽃을 바라볼 때, 모든 사람의 마음은 깨끗하다. 그들은 증오를 잊고, 고통을 잊고, 모든 더러움을 잊는다. 모든 사람의 마음은 고요한 호수가 되어, 티끌 하나 없는 호수의 표면 위에 오직 불꽃의 아름다운 반영만이 존재한다. \n 쉿… 불꽃 뒤에는 무엇이 있는지 묻지 마세요. 신생은 어쩌면 사치일 수 있지만, 그렇다고 해서 그 피어남을 헛되게 하지 마세요. \n 모든 불행한 것들 중에서, 불꽃놀이는 가장 순수한 것이다. 오늘 밤, 저의 그 부분을 당신께 드리고 싶습니다. \n 고개를 들어, 눈을 깜빡이지 마세요. 찬란한 별들이 떠오르는 것을 바라보며, 불꽃이 피어날 때, 새로운 자신을 맞이하세요, 수호자. \n\n “천선”"
  },
  Mail_129806_Name = {
    Text = "불꽃놀이"
  },
  Mail_129806_Sender = {Text = "서"},
  Mail_130223_Desc = {
    Text = "안녕하세요, 수호자 님.\n「뒤바뀐 새 삶」 이벤트가 종료되었습니다.\n수호자 님이 가지고 계셨던 잔여 「순백 인분」, 「붉은 인분」, 「요광 인분」을 각 1개당 장미 금권 × 40으로 전환해 드립니다. 수호자님께서는 잊지 말고 확인해 주세요."
  },
  Mail_130223_Name = {
    Text = "인분 회수"
  },
  Mail_130223_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_131005_Desc = {
    Text = "존경하는 수호자님:\n“머스크스의 호출” 이벤트가 종료되었습니다. 수호자님의 남은 “해변 조개 1호”, “해변 조개 2호”, “해변 조개 3호”를 각각 “장미 금권”× 40으로 교환하였으니, 수령해 주시기 바랍니다."
  },
  Mail_131005_Name = {
    Text = "소라 회수"
  },
  Mail_131005_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_131093_Desc = {
    Text = "존경하는 수호자님:\n“타오르는 군연·Rerun” 이벤트가 종료됨에 따라 수호자님의 남은 “원생 경골”, “원엽석” 및 “나선 유적”을 각각 “장미 금권”× 40으로 교환하였으니, 수호자님께서는 확인해 주시기 바랍니다."
  },
  Mail_131093_Name = {
    Text = "타오르는 군연 통화 회수"
  },
  Mail_131093_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_131767_Desc = {
    Text = "내@2!@3는@2 최고의@3 혼@4과 파괴@2! 고함쳐@4……!\n\n 아야야! 당신이 무슨 짓을 했는지 좀 보세요!!! 당신은 최고 신의 금기를 건드렸습니다! 이제 좋습니다, 그의 저어가 당신이 있는 세계에 울려 퍼졌고, 검은 재앙이 당신의 통신기에서 시작되어 당신 주변의 모든 것을 삼킬 것입니다……\n 불쌍한 당신, 당신의 무모함이 정말로 저를 곤란하게 만듭니다. 하지만 너무 절망할 필요는 없습니다, 불행 중 다행히도 당신은 저를 만났습니다—— 위대한 교단의 요정, 신의 선택받은 자, 최고 신의 집행자, 거대한 교단의 법적 상속자, 고통의 구원자, 신왕의 지우! 저는 선의와 사랑의 신의 의지로, 이 세상의 고통을 참을 수 없어, 저의 최고의 힘으로 모든 어리석은 장난꾸러기를 구원할 것입니다.\n 오, 본 요정은 당신의 도발하는 눈빛을 보았습니다. 괜찮습니다, 선의의 신은 세상을 사랑하며, 세상의 어리석음을 전혀 신경 쓰지 않습니다. 구세주에 대한 불신은 모든 신도의 필연적인 길입니다. 이러한 만남의 선물은 신의 집행자가 당신에게 주는 은혜입니다.\n 이제, 밝은 길이 당신을 위해 밝혀졌습니다: 당신의 성의를 가지고 @3 도시의 @2 대성당에 가서, 선의의 신에게 당신의 충성을 바친다면, 당신은 꿈에 그리던 힘을 얻고, 이 악몽의 저주에서 해방될 것입니다. 물론, 함께 바쳐야 할 것은 당신의 재산입니다. 오해하지 마세요, 선의의 신은 세속적인 보상에 관심이 없지만, 그의 신도들이 일을 처리하는 데에도 돈이 필요합니다. 이러한 세속적인 것들을 아끼지 마세요, 사랑하는 신도여, 한 푼 한 푼이 가치가 있습니다.\n 선의의 신의 이름을 높이 부르며, 기적의 강림을 기다리세요!\n\n 위대한 교단의 요정, 신의 선택받은 자"
  },
  Mail_131767_Name = {
    Text = "본 @2에 손대지 마세요"
  },
  Mail_131767_Sender = {Text = "카라부"},
  Mail_132339_Desc = {
    Text = "존경하는 수호자:\n\"신왕 부활·복제\" 이벤트가 종료되었습니다. 현재 수호자가 남긴 \"피곤한 감정\", \"비수한 생각\", \"기쁨과 생각\"을 각각 \"장미 금권\"× 40의 비율로 변환하였습니다. 수호자는 꼭 확인해 주시기 바랍니다."
  },
  Mail_132339_Name = {
    Text = "신왕 부활 화폐 회수"
  },
  Mail_132339_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_132458_Desc = {
    Text = "존경하는 수호자님:\n        《망각의 전야》에 대한 지원과 인식에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록 다음의 경험 조사 설문지를 작성해 주시기를 진심으로 초대합니다. 협조해 주신 것에 대한 감사로 「은심」× 200을 보상으로 준비했습니다. 설문지를 완료하시면 수령 가능합니다. 설문 마감 시간은 8월 17일 9:00입니다. 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자님의 의견을 진지하게 듣겠습니다. 여러분의 피드백은 미사그 대학이 더욱 발전하는 데 큰 도움이 될 것입니다!\n        —은열쇠가 앞길을 밝히기를."
  },
  Mail_132458_Name = {
    Text = "버전 체험 조사설문지 V2.5.3"
  },
  Mail_132458_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_132578_Desc = {
    Text = "수호자 님, 안녕하세요.\n{s1} 시즌 「질주하는 환희 열차」에서, 수호자 님께서 획득하신 칭호는 「{s2}」입니다.\n아래 추가 보상을 받으실타래 수 있으니, 꼭 확인해 주시기 바랍니다."
  },
