  },
  Mail_132581_Desc = {
    Text = "수호자 님, 안녕하세요.\n{s1} 시즌 「페이즈 체스: 순차 선택 모드」에서, 수호자 님께서 획득하신 칭호는 「{s2}」입니다.\n아래 추가 보상을 받으실타래 수 있으니, 꼭 확인해 주시기 바랍니다."
