  Mail_132581_Name = {
    Text = "「페이즈 체스: 순차 선택 모드」 시즌 정산"
  },
  Mail_132581_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_132605_Desc = {
    Text = "찍찍찍, 찍찍찍찍찍!\n(수호자, 만우절 축하해!)\n찍찍찍, 찍찍!\n(증명사진, 기념!)\n「어지러운 습기 있는 해달 발자국」\n「불량 밀랍 낙인이 남긴 흐릿한 조개 인쇄」\n                                                         —하나의 바른 해달 발자국 서명"
