  Mail_132605_Sender = {Text = "지!"},
  Mail_133276_Desc = {
    Text = "존경하는 수호자님께:\n「위대한 정복·복각」 이벤트가 종료되었습니다. 수호자님께 남은 「맛있는 레오 바비큐」를 1매당 「장미 금권」× 40의 비율로 전환하였으니, 꼭 확인해 주시기 바랍니다."
