  Mail_133276_Name = {
    Text = "맛있는 레오 숯불구이 화폐 회수"
  },
  Mail_133276_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_133703_Desc = {
    Text = "존경하는 수호자님께:\n{s1} 버전이 종료되어, 수호자님의 남은 「공환의 은핵」를 1개당 「무구의 은핵」× 1의 비율로 자동 전환하였습니다. 이번에 총 「무구의 은핵」× {s2} 가 전환되었으니, 수호자님께서는 꼭 확인해 주시기 바랍니다."
  },
  Mail_133703_Name = {
    Text = "「공환의 은핵」 만료 전환"
  },
  Mail_133703_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_133704_Desc = {
    Text = "존경하는 수호자님께:\n{s1} 버전이 곧 종료됩니다. 수호자님께서는 남은 「공환의 은핵」을 기한 내에 사용해 주시기 바랍니다. 이번 학기 과제 종료 후 수호자님의 남은 「공환의 은핵」은 1개당 「무구의 은핵」× 1의 비율로 전환됩니다."
  },
  Mail_133704_Name = {
    Text = "「공환의 은핵」 만료 알림"
  },
  Mail_133704_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_134024_Desc = {
    Text = "존경하는 수호자님께:\n「일일 시험훈련」이 제거되었습니다. 수호자님께 남은 「대리 증표」를 1매당 「장미 금권」× 10000의 비율로 전환하였으니, 꼭 확인해 주시기 바랍니다."
  },
  Mail_134024_Name = {
    Text = "대리 증표 회수"
  },
  Mail_134024_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_134067_Desc = {
    Text = "수호자님께:\n\n오늘 특별히 상의하고 싶은 일이 있어요.\n그냥 거리를 아무렇게나 걸으면서, 평범하게 재미있는 것들을 구경하고, 마음 가는 대로 이곳저곳 돌아다니며, 평범한 하루를 보내고 싶어요.\n\n그래서 학사처에 물어봤거든요. 그랬더니 안전상의 이유로, 당신이 동행하는 경우에만 외출을 허가한다고 하더라고요.\n다른 사람을 놀라게 하지 말라느니, 밖에서 아무거나 입에 넣지 말라느니. 정말 실타래례잖아요.\n뭐, 그런 사정이에요. 아무튼 같이 나가서 좀 걸을 수 있을까요? 다 같이요.\n\n……왠지 문득 떠올랐는데, 민들레 씨앗은요,\n언젠가 바람을 타고, 자신의 운명이 있는 곳으로 여행을 떠나잖아요.\n어쩌면 내일일 수도 있고, 아주 먼 훗날의 일일 수도 있고요.\n그런 생각을 하다 보니, 지금 다 같이 더 많은 일을 해두는 것도 나쁘지 않겠다 싶었어요.\n\n아무튼, 기숙사 앞에서 기다리고 있을게요. 부탁해요!\n\n사야"
  },
  Mail_134067_Name = {Text = "산책…"},
  Mail_134067_Sender = {Text = "사야"},
  Mail_134068_Desc = {
    Text = "수호자님께:\n\n오늘은 특별한 날이라고 생각해요. 하지만 기억의 윤곽은 여전히 흐릿하기만 해요.\n오직 「사야」라는 이름만이, 간신히 저를 이곳에 묶어두고 있어요.\n\n그 느낌은 외로움도 아니고, 슬픔도 아니에요. 그렇게 선명한 감정은 아니에요.\n굳이 이 마음에 이름을 붙여야 한다면…… 아마, 「공백」이겠죠.\n아무것도 없이, 끝없이 맑고 투명한, 고요한 시간.\n\n만약 언젠가, 바람을 타고 날아가는 민들레 씨앗이,\n이 세계의 모든 구석구석에서, 그저 하얗게, 조용히 내려앉는다면……\n그때, 저는 아마 비로소 이 세계가 \"특별하다\"고 느낄 수 있을 거예요.\n\n그때, 런디니엔에 자욱한 잿빛 안개도, 석양에 타오르는 붉은 노을도, 그리고 당신이 늘 학교 광장에서 올려다보던 하늘도, 모두 민들레로 뒤덮여 순백의 색으로 변할 거예요. 저만의 색으로.\n\n그러니…… 만약, 저에게 무언가를 주고 싶으시다면.\n선물이 아니어도 괜찮아요, 그저 하나의 \"기억\"이면 돼요.\n\n저는, 민들레가 만개한 순백의 세계에서,\n그저 조용히, 그 순간이 찾아오기를 기다리고 있을게요.\n\n언젠가 다시 미사그 광장에서 하늘을 올려다볼 때,\n시야 가장자리를 스쳐 지나가는 그 한 줄기 하얀 솜털을,\n한때 당신과 이야기를 나누었던 저의 모습과 살짝 겹쳐 주세요.\n\n사야"
  },
  Mail_134068_Name = {
    Text = "민들레의 약속…"
  },
  Mail_134068_Sender = {Text = "사야"},
  Mail_139809_Desc = {
    Text = "존경하는 비밀의 수호자님:\n        「망각 전야」에 대한 지지와 성원에 감사드립니다. 비밀의 수호자님께서 미사그 대학교에서 더 나은 게임 경험을 누리실타래 수 있도록, 아래의 체험 설문 조사 작성을 정중히 요청드립니다. 협조에 감사드리는 마음으로 「은빛 코어」× 200을 보상으로 준비하였으며, 설문 완료 후 수령하실타래 수 있습니다. 설문 마감 시간은 5월 16일 9:00이오니, 기한 내에 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        저희는 모든 비밀의 수호자님의 의견을 성실타래히 경청할 것이며, 여러분의 피드백이 미사그 대학교를 더욱 발전시켜 나갈 것입니다！\n        ——은빛 열쇠가 앞길을 인도하기를."
  },
  Mail_139809_Name = {
    Text = "버전 체험 설문 조사 V2.5.0"
  },
  Mail_139809_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_139927_Desc = {
    Text = "안녕하세요, 수호자 님.\n「무형의 교향곡·복각」 이벤트가 종료되었습니다.\n수호자 님이 가지고 계셨던 잔여 「고창 악장」을 각 1개당 「장미금권」× 40으로 전환하였으니, 확인 부탁드립니다."
