  },
  Mail_140084_Desc = {
    Text = "존경하는 수호자님:\n\"하늘에서 내려오는 수많은 빛: Rerun\" 활동이 종료됨에 따라, 수호자님의 잔여 부의 \"인장\", 선혈의 \"인장\", 전쟁의 \"인\"을 각 1개당 장미 금권 × 40으로 전환해 드립니다. 수호자님께서는 잊지 말고 확인해 주세요."
  },
  Mail_140084_Name = {
    Text = "총알 회수"
  },
  Mail_140084_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_140478_Desc = {
    Text = "존경하는 수비인께:\n「사랑의 원류」 이벤트가 종료되었습니다. 이벤트에서 아직 수령하지 않으신 보상을 발송해 드리오니, 확인 부탁드립니다."
