  Mail_140478_Name = {
    Text = "「사랑의 원류」 보상 재발송"
  },
  Mail_140478_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_140690_Desc = {
    Text = "수호자 님, 안녕하세요.\n「눈이 녹을 때·Rerun」 이벤트가 종료됨에 따라, 수호자 님께서 가지고 계셨던 잔여 「냉동 꽃봉오리」, 「은상 꽃봉오리」, 「일광화포」를 각각 「장미 금권」× 40의 비율로 전환할 예정이니, 수호자 님께서는 잊지 말고 확인해 주세요."
  },
  Mail_140690_Name = {
    Text = "꽃봉오리 회수"
  },
  Mail_140690_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_140751_Desc = {
    Text = "존경하는 수호자님:\n\"봄이 시들기 전에: Rerun\" 활동이 종료됨에 따라, 수호자님의 잔여 \"기쁜 시\", \"우울한 시문\", \"유감의 시문\"을 각 1개당 장미 금권 × 40으로 전환해 드립니다. 수호자님께서는 확인해 주세요."
  },
  Mail_140751_Name = {
    Text = "시문 회수"
  },
  Mail_140751_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_141372_Desc = {
    Text = "안녕하세요, 수호자 님.\n「영원한 에뷔노스」 이벤트가 종료됨에 따라, 수호자 님께서 가지고 계셨던 잔여 신선한 「사냥감」, 거대한 「사냥감」, 오래된 「사냥감」을 각 1개당 장미 금권 × 40으로 전환해 드립니다.\n수호자님께서는 잊지 말고 확인해 주세요."
  },
  Mail_141372_Name = {
    Text = "영원한 에뷔노스 아이템 회수"
  },
  Mail_141372_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_141470_Desc = {
    Text = "존경하는 수호자님:\n\"미러 수인: Rerun\" 활동이 종료됨에 따라, 수호자님의 잔여 상식의 책, 수리의 책, 문학의 책을 각 1개당 장미 금권 × 40으로 전환해 드립니다. 수호자님께서는 잊지 말고 확인해 주세요."
  },
  Mail_141470_Name = {
    Text = "거울 포로 화폐 회수"
  },
  Mail_141470_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_141507_Desc = {
    Text = "수호자:\n\n탄생의 날, 너에게는 아마 중요한 날일 것이다?\n나에게는 운명의 그물 위의 매일의 무게가 동일하다. 다른 이야기들이 이 날에 특별한 의미를 부여했을 뿐이다.\n나는 이 날 태어나고, 이 날 예언을 깨닫고, 이 날 운명을 짜는 자의 방적기를 얻고, 이 날 복잡한 운명의 실타래선과 그 실타래선 끝의 악몽을 보았다.\n운명의 짜는 자에게 이 날은 평범하다. 무대 위의 배우에게 이 날은 축하할 만하다. 그리고 모든 신분 중에서 나를 가장 기쁘게 하는 것은 배우로서의 나이다.\n수호자, 오늘, 운명 극장의 불빛은 모두 꺼졌고, 오직 하나의 무대만이 화려하게 빛나고 있다. 너는 내가 경험했던 운명을 더 많이 보고 싶다고 말했었다. 그리고 지금, 이 무대에서 공연될 것은 나 자신의 이야기이다.\n나는 그것이 어떤 이야기가 될지 모르겠다. 나는 기억을 무대로 보내고, 그녀는 그 강렬한 순간들 속에서 너가 가장 보고 싶어하는 이야기를 선택하여 오늘 밤의 무대에서 선보일 것이다.\n그 이야기는 나를 고통스럽게 할 수도 있고, 나를 난처하게 할 수도 있지만, 그것은 중요하지 않다, 그렇지 않니? 나는 가끔 방적기가 스스로 운명을 짜도록 하고, 순수한 관중이 되는 것이 즐거운 일이라고 생각한다.\n이 공연의 유일한 입장권은 지금 너의 손에 있다. 이 편지를 가지고 와라, 수호자. 오늘 밤, 더 이상 아무도 알지 못하는 이야기가 너의 도착을 기다리고 있다.\n\n아라크네"
  },
  Mail_141507_Name = {
    Text = "은밀한 스토리"
  },
  Mail_141507_Sender = {
    Text = "아라크네"
  },
  Mail_141833_Desc = {
    Text = "존경하는 수호자님:\n「초승달과 깊은 눈」 활동이 종료됨에 따라, 수호자님께 남은 「붉은 사과」, 「황금 사과」, 「사과 사탕」을 각 1개당 「장미 금권」× 40의 비율로 전환해 드립니다. 수호자님께서는 잊지 말고 확인해 주시기 바랍니다."
  },
  Mail_141833_Name = {
    Text = "사과 회수"
  },
  Mail_141833_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_141957_Desc = {
    Text = "존경하는 수호자님:\n        \"망각의 전야\"에 대한 지지와 인정에 감사드립니다. 수호자님께서 미사그 대학에서 더 나은 게임 경험을 즐기실타래 수 있도록, 아래의 체험 설문 조사를 작성해 주시기를 정중히 요청드립니다. 협조에 감사드리며, 보상으로 \"은심\" × 200을 준비했습니다. 설문 완료 후 수령 가능합니다. 설문 마감 시간은 2월 15일 9:00이오니, 기한 내에 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        저희는 모든 수호자님의 의견을 성실타래히 경청할 것이며, 여러분의 피드백이 미사그 대학을 더욱 발전시킬 것입니다!\n        —은열쇠가 앞길을 밝히기를."
  },
  Mail_141957_Name = {
    Text = "버전 체험 설문 조사 V2.7.2"
  },
  Mail_141957_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_141958_Desc = {
    Text = "존경하는 수호자님:\n        \"망각의 전야\"에 대한 지지와 인정에 감사드립니다. 수호자님께서 미사그 대학에서 더 나은 게임 경험을 즐기실타래 수 있도록, 아래의 체험 설문 조사를 작성해 주시기를 정중히 요청드립니다. 협조에 감사드리며, 보상으로 \"은심\" × 200을 준비했습니다. 설문 완료 후 수령 가능합니다. 설문 마감 시간은 12월 21일 9:00이오니, 기한 내에 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        저희는 모든 수호자님의 의견을 성실타래히 경청할 것이며, 여러분의 피드백이 미사그 대학을 더욱 발전시킬 것입니다!\n        —은열쇠가 앞길을 밝히기를."
