  },
  Mail_141959_Desc = {
    Text = "존경하는 수호자님:\n        \"망각의 전야\"에 대한 지지와 인정에 감사드립니다. 수호자님께서 미사그 대학에서 더 나은 게임 경험을 즐기실타래 수 있도록, 아래의 체험 설문 조사를 작성해 주시기를 정중히 요청드립니다. 협조에 감사드리며, 보상으로 \"은심\" × 200을 준비했습니다. 설문 완료 후 수령 가능합니다. 설문 마감 시간은 1월 18일 9:00이오니, 기한 내에 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        저희는 모든 수호자님의 의견을 성실타래히 경청할 것이며, 여러분의 피드백이 미사그 대학을 더욱 발전시킬 것입니다!\n        —은열쇠가 앞길을 밝히기를."
  },
