  },
  Mail_141962_Desc = {
    Text = "존경하는 수호자님:\n        \"망각의 전야\"에 대한 지지와 인정에 감사드립니다. 수호자님께서 미사그 대학에서 더 나은 게임 경험을 즐기실타래 수 있도록, 아래의 체험 설문 조사를 작성해 주시기를 정중히 요청드립니다. 협조에 감사드리며, 보상으로 \"은심\" × 200을 준비했습니다. 설문 완료 후 수령 가능합니다. 설문 마감 시간은 5월 10일 9:00이오니, 기한 내에 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        저희는 모든 수호자님의 의견을 성실타래히 경청할 것이며, 여러분의 피드백이 미사그 대학을 더욱 발전시킬 것입니다!\n        —은열쇠가 앞길을 밝히기를."
  },
  Mail_141962_Name = {
    Text = "버전 체험 설문 조사 V2.7.5"
  },
  Mail_141962_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_142101_Desc = {
    Text = "오랜만이야, %player%:\n\n네가 이 편지를 받을 때쯤, 나는 아마 야그로의 상공을 지나고 있을 거야. 매년 이맘때면 내 순찰 여정은 언제나 조금 더 멀어지곤 하지.\n적들의 비명과 울부짖음보다 생일 배경음악으로 더 어울리는 건 없어. 게다가 나는 충분한 우리를 준비해 뒀으니, 고통 외에는 아무런 구원도 가져다주지 않는 그 가짜 신들을 믿는 멍청이들이 있는 한, 천애 어디에 있든 내가 그들에게 자신의 잘못을 깨닫게 해줄 거야.\n가끔, 악몽이 구름층을 뚫고 달을 볼 수 있을 때, 정말로 황당한 생각들이 내 머릿속을 스쳐 지나가기도 해.\n예를 들면 이런 시간이 언제 갑작스럽고 거스를 수 없이 강제로 멈추게 될까, 마치 삶이 처음에 아무런 예고도 없이 무너져 내렸던 것처럼.\n하지만 곧 나는 스스로 웃음이 나오더라고. 내가 그 길에 발을 들인 날부터, 나는 물러설 곳 없는 여정 위에 있었어. 네가 내 말을 분명히 이해할 거라고 믿어, 꼬마야. 이 세상에서 너와 나만큼 처지가 같은 사람은 없을 거야.\n우리 둘 다 선택의 여지가 없는 선택들을 골랐지. 좋은 소식은, 우리 둘 다 자신의 선택을 즐기고 있다는 거야.\n새해에도, 내가 선물한 사냥 호루라기를 불기만 하면 나는 언제든 네 곁에 나타날 거야.\n물론, 별일 없다면 우선 이 여정을 마음껏 즐기게 해줘. 다음 달에 기념품과 새로운 견문을 가져다줄게.\n모든 일이 잘 되길 바라며, 행복하길 바라.\n\n당신의 사랑하는 \"외삼촌\""
  },
  Mail_142101_Name = {Text = "견문"},
  Mail_142101_Sender = {
    Text = "당신의 친애하는 「외삼촌」"
  },
  Mail_143935_Desc = {
    Text = "존경하는 수호자님:\n“임시 텍스트” 이벤트가 종료되었습니다. 수호자님의 남은 “임시 텍스트”, “임시 텍스트”, “임시 텍스트”를 각각 “장미 금권”× 40으로 교환하였으니, 확인해 주시기 바랍니다."
  },
  Mail_143935_Name = {
    Text = "임시 텍스트 회수"
  },
  Mail_143935_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_145435_Desc = {
    Text = "수호자 님, 안녕하세요.\n「레비아탄의 놀음」 이벤트가 종료됨에 따라, 수호자 님께서 가지고 계셨던 잔여 「핏빛 제물」을 1개당 「장미 금권」× 40의 비율로 전환하였습니다.\n수호자 님께서는 잊지 말고 확인해 주세요."
  },
  Mail_145435_Name = {
    Text = "핏빛 제물 회수"
  },
  Mail_145435_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_145468_Desc = {
    Text = "수호자 님, 안녕하세요.\n「평소와 같게: Rerun」 이벤트가 종료됨에 따라, 수호자 님께서 가지고 계셨던 잔여 「해변 특산물 조개」를 1개당 「장미 금권」× 40의 비율로 전환하였습니다. 수호자 님께서는 잊지 말고 확인해 주세요."
  },
  Mail_145468_Name = {
    Text = "해변 특산물 조개 회수"
  },
  Mail_145468_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_146401_Desc = {
    Text = "역법이라는 건 지루한 발명이라고 생각한다. 모든 날이 별반 다를 게 없지, 오늘도 마찬가지고.\n\n너희들의 역법에 따르면, 오늘이 내가 태어난 날이라고 한다. 근데, 「태어났다」는 표현은 내게 정확하지 않아. 나는 혼돈으로부터 찢겨 나온 잔해일 뿐, 수많은 전투 속에서 연마되어 만들어진 칼날일 뿐이다. 나를 빚어낸 건, 모체가 아니라 나와 맞섰던 모든 상대들이지. 그리고 넌, 그중에서도 가장 중요한 상대다.\n너희들은 이런 날에 연회나 선물, 축사 같은 것들을 중요시하지. 하지만, 나한테는 필요 없어.\n내가 원하는 건 단 한 가지, 바로 한판 승부뿐이다.\n지금까지, 너는 기이할 정도로 많은 일들을 해내왔다, 하지만 나는 알고 있지. 네가 보여준 건, 네 한계와는 거리가 멀다는걸.\n오늘 해 질 녘, 훈련장이다. 거기서 기다리고 있을 테니, 무기를 들고 오도록 해라. 승부에 얽매일 필요 없고, 부상 같은 것도 신경 쓸 것 없다. 칼날이 아낌없이 맞부딪치는 그 순간이, 내가 유일하게 기대하는 축하 선물이니까.\n@4의 파편이, 대체 무엇을 해낼 수 있는지를, 한 번 내게 보여줘 보거라.\n\n네가 나를 놀라게 해줄 거라 믿고 있겠다, 나의 「라이벌」이여.\n\n「로탄」"
  },
  Mail_146401_Name = {
    Text = "유일한 기대"
  },
  Mail_146401_Sender = {
    Text = "침식·로탄"
  },
  Mail_146873_Desc = {
    Text = "존경하는 수호자님:\n“임시 텍스트” 이벤트가 종료되었습니다. 수호자님의 남은 “임시 텍스트”, “임시 텍스트”, “임시 텍스트”를 각각 “장미 금권”× 40으로 교환하였으니, 확인해 주시기 바랍니다."
  },
