    Text = "존경하는 수호자님:\n“임시 텍스트” 이벤트가 종료되었습니다. 수호자님의 남은 “임시 텍스트”, “임시 텍스트”, “임시 텍스트”를 각각 “장미 금권”× 40으로 교환하였으니, 확인해 주시기 바랍니다."
