  },
  Mail_147875_Desc = {
    Text = "존경하는 수호자님:\n        Ⅴ2.6.0 업데이트에서 망각편 조사 작전 H7-9의 숨겨진 보상이 누락된 문제를 수정하였습니다. 수정 전에 이미 H7-9를 클리어하신 경우, 누락된 숨겨진 보상을 직접 재지급해 드립니다. 확인해 주시기 바랍니다."
