  Mail_148083_Desc = {
    Text = "존경하는 수호자님:\n        Ⅴ2.6.0 업데이트에서 「사전 선택 레벨」의 보상을 상향하였습니다. 업데이트 전에 이미 추가 보상을 모두 수령하신 수호자님께 해당 보상을 재지급해 드립니다. 확인해 주시기 바랍니다."
