  Mail_148478_Desc = {
    Text = "존경하는 수호자님:\n        제 {s1} 기 「학기 과제-고급 과제」에서 획득한 보상이 아직 수령되지 않았습니다. 미수령 보상을 메일 첨부 파일로 발송해 드리오니, 인벤토리를 정리한 후 수령해 주시기 바랍니다."
