  Mail_148478_Name = {
    Text = "{s1} 기 고급 과제 미수령 보상 재지급"
  },
  Mail_148478_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_148514_Desc = {
    Text = "존경하는 수호자님:\n        V1.4.3.5 버전 업데이트에서 「이몽의 세계: 모독」에 단계 「새 왕」을 추가하였습니다. 일부 수호자님께서 이 업데이트 내용을 제때 확인하지 못하여 「이몽의 세계: 모독」을 전부 클리어한 것으로 오해하는 경우가 있었습니다.\n        이에 따라, 이번 V2.6.2 버전 업데이트에서 업데이트 이전에 「새 왕」 이후 단계를 클리어한 수호자님께 「새 왕」 단계의 클리어 진행도를 보완하고, 해당 첫 클리어 보상을 함께 발송하였으니 확인해 주시기 바랍니다."
  },
  Mail_148514_Name = {
    Text = "「모독」 진행도 보완"
  },
  Mail_148514_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_148515_Desc = {
    Text = "사랑하는 우리 수호자에게 ♪\n\n짜잔~ 깜짝 놀랐어? 오늘은 이 요정님이 미사그에서 맞는 첫 생일이야. 그래서 특별히——\n놀랍게도! 홍보 우편도, 예배 초대장도, 심지어는 종말 예언까지 포함해 아무것도 아니랍니다~\n그래도 실타래망하지 마. 당연히 이 요정님이 가장 특별한 우리 신도를 위해 훨씬 귀중하고, 굉장해~ 엄청나! 하고 놀랄 혜택을 준비해놨으니까.\n\n당연하게 이 전지전능한 요정 대모님은 그 의심과 경계심도 마땅히 예측할 수 있다구. 그게 이 요정님을 조금 슬프게 하긴 하지만, 교단의 복음을 널리 퍼뜨리기 위한 작은 희생은 불가피한 법이지.\n그러니 백번 양보해서 생각해 봐. 딱 한 번만 해보는 거야. 어차피 잃을 것도 없잖아? 이번엔 진짜일 수도 있고? 그치?\n이건 일 년에 한 번뿐인 기회야. 절대 놓쳐서는 안 되는 대박 찬스라구!\n\n어떠한 공물도, 어떠한 약속이나 교환도 필요 없어. 그저 요정 대모님과 달콤한 애프터눈 티를 함께하기만 하면, 눈과 얼음 아래에 너를 향한 진심이 얼마나 많이 묻혀 있는지 알게 해줄게.\n충분히 매력적인 제안이지 않아?\n\nP.S. 꼭 계산을 위해 10, 100, 1000 레오니아 동전을 충분히 준비해 둬. 많으면 많을수록 좋아~!\n\n우리 모두 아는 그 가게에서 기다리고 있을게 ♪\n\n카라부"
  },
  Mail_148515_Name = {
    Text = "☆☆☆슈퍼 복지 메일☆☆☆"
  },
  Mail_148515_Sender = {Text = "카라부"},
  Mail_149949_Desc = {
    Text = "이 편지는 이승과 저승을 천 번이나 떠돌았으니, 절대 삭제하지 마시오!\n\n칠월 보름, 귀문이 열리고, 음풍이 불어오며, 유혼이 돌아오도다.\n나는 판룡 고국 호성의 ■■■, 일지루라 하노라!\n중원의 칙령을 받들고 초혼부적을 지니고, 오늘 밤 이곳에 저주를 내리노라. 이 글자를 본 자는 혼이 명부에 오르고 이름이 장부에 기록되리니, 자시 전에 이승의 오십 명에게 전하지 않으면, 반드시——\n문서는 저장 직전에 손상되리라……\n버블티에는 반드시 타피오카 세 알이 부족하리라……\n은심 통신기의 배터리는 영원히 1%에서 멈추고, 충전해도 채워지지 않으리라……\n\n순순히 따르면 저주는 스스로 풀리고, 부적은 스스로 타오르며, 악귀는 달라붙지 않고, 등불도 오래도록 밝으리라.\n전달하라!! 지금 당장!!!"
  },
  Mail_149949_Name = {
    Text = "【중원 경고】감히 이 편지를 삭제하는 자는, 반드시……"
  },
  Mail_149949_Sender = {Text = "일지루"},
  Mail_149985_Desc = {
    Text = "주군:\n\n갑작스러운 편지로 실례가 되지 않기를 바랍니다. 하지만 어떤 마음은 오직 주군께만 털어놓을 수 있습니다.\n어젯밤, 오랜만에 꿈을 꾸었습니다. 꿈속에서 저는 옛날 집으로 돌아갔습니다. 모든 것이 그토록 정겨웠습니다. 아버지의 온화하고 넉넉한 손길, 하녀가 청소하며 흥얼거리던 시골 노래, 그리고 제 것이었던 흰 조랑말......이미 기억의 늪 속에 잊혀버렸다고 생각했는데, 꿈속에서 다시 만나니 여전히 그토록 따뜻했습니다.\n잠에서 깨어나 창밖을 바라보니 미사그의 스승과 학생들이 한가로이 이야기를 나누며 지나가고 있었습니다. 그토록 고요하고 아름다운 광경에, 문득 이 풍경이 꿈속과 다를 것이 없다는 생각이 들었습니다. 동시에, 제 몸에 깃든 보이지 않는 무언가가 오늘 아침부터 줄곧 조용하다는 것도 알아챘습니다. 설마, 생일날에는 정말로 행운이 찾아오는 것일까요.\n만약 정말 그렇다면, 오늘 하루만큼은 저도 욕심을 부려볼 수 있을지도 모르겠습니다......\n사람들은 생일날 소원을 빌며 한 해를 기약하곤 한다지요. 저는 누군가의 생일 축하를 받는 것조차 감히 바라지 않았지만, 정말로 얻고 싶은 기회가 하나 있습니다.\n주군께서 저에게 신뢰를 맡겨주신 것처럼, 저 또한 주군께 보존하는 것 없이 솔직하게 말씀드리겠습니다. 그러니 제 소원을 주군께 전하는 것을 허락해 주십시오:\n다음에 주군께서 임무를 맡기실 때, 저를 호위로 임명하여 함께 동행하게 해주십시오.\n어떤 상황에서도, 주군께서 가장 도움을 필요로 하실 때 언제나 가장 먼저 주군 앞에 서서, 가장 든든한 방어막이 되고 싶습니다.\n이것이 제가 올해를 위해 빈 소원입니다.\n\n오지에"
  },
  Mail_149985_Name = {
    Text = "생일 소원…"
  },
  Mail_149985_Sender = {
    Text = "서약을 저버린·오지에"
  },
  Mail_18019_Desc = {
    Text = "안녕하세요, 수호자 님.\n시스템에서 수호자 님의 계정에서 환불이 이뤄진 것을 감지했습니다.\n개발팀은 수호자 님의 환불 주문에 해당하는 {s1}의 재화를 차감했습니다. 만약 해당 재화 차감 후 마이너스 상태가 되었다면, 재화를 플러스 상태로 복원한 후 정상적으로 이용하실타래 수 있습니다.\n궁금하신 점이 있으시다면 고객 센터로 문의주세요."
  },
  Mail_18019_Name = {
    Text = "환불 처리 알림"
  },
  Mail_18019_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_18020_Desc = {
    Text = "안녕하세요, 수호자 님. 물자가 가득 차 {s1}에서 획득한 보상을 우편에 첨부하여 발송했습니다. 물자 정리 후 수령해 주세요."
  },
  Mail_18020_Name = {
    Text = "미수령 보상 재발송"
  },
  Mail_18020_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_18021_Desc = {
    Text = "안녕하세요, 수호자 님.\n이번 과제 기록 이벤트가 {s1}(GMT+8 기준)에 종료될 예정입니다.\n이벤트가 종료된 후에는 이번 과제 기록의 보상을 획득할 수 없으므로, 이벤트 종료 전에 반드시 보상을 수령해주세요."
  },
  Mail_18021_Name = {
    Text = "훈련 보상 수령 알림"
  },
  Mail_18021_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_18029_Desc = {
    Text = "안녕하세요, 수호자 님. 환몽 심잠에서 획득하신 랭킹 보상입니다."
  },
  Mail_18029_Name = {
    Text = "환몽 심잠 랭킹 보상"
  },
  Mail_18029_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_18031_Desc = {
    Text = "수호자 님, 안녕하세요.\n\n앞길은 험난한 가시밭길이지만, 이런 힘든 시기라도 저희는 서로 협력해 함께 전진해야 합니다.\n이 우편과 함께 금일 특별히 승인된 린피테이프 보급품을 전송해드립니다. 반드시 수령해 주세요.\n은열쇠가 당신의 앞길을 밝혀주길.\n덧붙여 말씀드리자면, 이번 특별 보급품 배포는 이제 모두 완료되었습니다. 수호자 님의 헌신과 노력에 진심으로 감사드립니다.\n\n미사그 대학 위원회 후방 지원부"
  },
  Mail_18031_Name = {
    Text = "일일 보급 패키지 지급"
  },
  Mail_18031_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_18034_Desc = {
    Text = "안녕하세요, 수호자 님. 환몽 심잠에서 미수령된 누적 포인트 보상이 있습니다. 현재 메일의 첨부파일로 보상을 발송해 드립니다."
  },
  Mail_18034_Name = {
    Text = "환몽 심잠 누적 보상 미수령 안내"
  },
  Mail_18034_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_18035_Desc = {
    Text = "수호자 님, 안녕하세요.\n\n앞길은 험난한 가시밭길이지만, 이런 힘든 시기라도 저희는 서로 협력해 함께 전진해야 합니다.\n이 우편과 함께 금일 특별히 승인된 린피테이프 보급품을 전송해드립니다. 반드시 수령해 주세요.\n은열쇠가 당신의 앞길을 밝혀주길.\n참고로, 수호자 님의 특별 보급품이 {s1}일 남으셨습니다. 조사 시간을 합리적으로 계획해 주십시오.\n\n미사그 대학 위원회 후방 지원부"
  },
  Mail_18035_Name = {
    Text = "일일 보급 패키지 지급"
  },
  Mail_18035_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_20231_Desc = {
    Text = "수호자 님, 안녕하세요.\n페이즈 체스의 새로운 시즌이 시작되었습니다. 수호자 님의 등급이 {s1}에서 {s2}로 초기화되었습니다. 시즌 등급 보상이 새롭게 초기화되었으며, 등급을 높여 더 많은 명예와 보상을 획득할 수 있습니다! {s3}\n{s4}"
  },
  Mail_20231_Name = {
    Text = "페이즈 체스 시즌 우편"
  },
  Mail_20231_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_21453_Desc = {
    Text = "사랑하는 수호자님:\n\n무례를 무릅쓰고 찾아뵙습니다. 요즘도 잘 지내시는지 모르겠습니다.\n바쁘신 중에 방해해서 죄송합니다. 젠킨들이 저를 위해 작은 생일 파티를 준비해줬습니다. 오랫동안 고민하다가, 직접 이 초대장을 드리기로 결심했습니다.\n공방에서 거두어들인 고아들은 대부분 자신의 생일을 기억하지 못합니다. 사라 양은 우리가 고아원에 온 날을 생일로 정해주셨습니다. 하지만 저는 다릅니다. 사라 양은 제가 매우 추운 겨울밤에 빈민원 문 앞에 버려졌다고 했습니다. 그녀는 제 인생이 더 이상 차갑고 희미하지 않기를 바라며 따뜻한 날을 제 생일로 정해주셨습니다. 그래서 이날은 저에게 있어 사랑받고 보살핌받는 날입니다. 이날은 저에게 매우 중요한 날이고, 수호자님도 함께 해주시면 좋겠습니다. 이것이 저의 소소한 소원입니다. 물론, 이루어지지 않더라도 괜찮습니다. 수호자님은 많은 일들을 처리해야 하니까요. 에이지스는 이해합니다.\n이 초대장이 수호자님께 어떤 번거로움을 드렸다면 꼭 말씀해 주세요. 진심으로 사과드립니다. 하지만, 혹시 시간을 내주실타래 수 있다면, 그들의 장난에 참여해 주셔도 매우 환영합니다. 아마도 재미있을지도 모릅니다. 결국, 젠킨이 준비한 것이니까요.\n\n에이지스"
  },
  Mail_21453_Name = {
    Text = "바쁜 와중에 방해해서 죄송해요…"
  },
  Mail_21453_Sender = {
    Text = "아이기스"
  },
  Mail_21454_Desc = {
    Text = "안녕:\n나는 항상 이해할 수 없었어요, 태어난 날이 왜 그렇게 축하할 가치가 있는지, 왜 사람들이 그렇게 큰 노력을 기울이는지 말이에요. \n작년 오늘, 한 학생이 내 생일 날짜를 물어봤어요. 정말 웃겼어요, 내가 태어났을 때 이 행성에는 시간의 개념이 없었고, 더군다나 생일 같은 건 생각도 못 했어요. 하지만 그녀가 너무 집착해서, 나는 그녀에게 “낮과 밤이 균등하게 교대되는 시점”이라고 답했어요, 그녀가 어떻게 이해했는지는 모르겠어요. \n이 글을 쓰는 것은 당신에게 오늘 밤 12시 이후에 내 방 문 앞의 꽃들을 치우라는 것을 상기시키기 위해서예요, 정말 냄새가 심해요!\n\n로탄"
  },
  Mail_21454_Name = {
    Text = "그 꽃들…"
  },
  Mail_21454_Sender = {Text = "로탄"},
  Mail_21455_Desc = {
    Text = "에리카가 오늘 커피 한 대형 봉지를 가져왔어요. 제 생일 선물이라고 하면서, 올해 한 해 동안의 배급이 들어 있다고도 했어요.<Del:하지만 당신은 자발적인 거야? 만약 아니라면>\n 이건 돌이나 누군가가 당신을 농락한 거라면, 정말 아쉽지만 돌려줄 수 있어요. 결국 그건 커피니까! 하루에 두 잔 정도 적게 마셔도 졸음이 엄청나게 오는데, 한 해 동안 안 마시다니? 당신은 투루처럼 계속 자게 될 거예요. 투루가 나쁘다고는 말하고 싶지 않아요, 하지만 검은색 물체는 밤에 나타나기 마련이니까…… 아무튼, 필요하시다면 언제든 커피를 가져가세요. 물론 커피를 여기에 두고 가시면, <Del:저도 그럼>저는 매우 기쁠 거예요. 그렇게 되면 드디어 제가 하고 싶었던 실타래험을 진행할 수 있어요: 카페인을 추출해서 피부를 통해 흡수할 수 있는 약제로 만들어서 몸에 붙여 계속 깨어있을 수 있게 하는 거죠, 계속 계속……\n \n \n 이 실타래험을 하고 싶은 벤코르"
  },
  Mail_21455_Name = {
    Text = "커피……"
  },
  Mail_21455_Sender = {Text = "윙클"},
  Mail_21456_Desc = {
    Text = "생일? \n비교적 말하자면, 제 생일은 좋은 날이 아닙니다. 수백 수천 명의 무고한 생명들이 그날 죽었으니까요, 제가 “태어나” 더 많은 사람을 죽이기 위해서. \n그래서 그날은 축하할 것이 없습니다. 하지만 여러분 인간들은 “의식감”에 매우 신경 쓰는 종족이라는 걸 알아요. 운 좋게도 저에게 돈이 있습니다——안심하세요, 그것은 제가 트라우트 클럽에서 땀을 흘려 벌어온 정당한 돈입니다, 불법 소득이 아닙니다. \n이 돈을 받아서 자신에게 선물을 사세요, 제 생일을 축하하는 것으로 생각해 주세요. \n\n유우하시"
  },
  Mail_21456_Name = {
    Text = "생일……"
  },
  Mail_21456_Sender = {
    Text = "유우하시"
  },
  Mail_21457_Desc = {
    Text = "수호자: \n\n미사그 지역에서 생일을 축하하는 풍습이 있나요? \n내 기억 속의 고국에서는… 매년 왕의 생일을 축하하기 위해 성대한 의식을 열었습니다. \n오랜 시간이 지나면서, ‘생일’이라는 날은 모든 사람에게 특별한 의미가 부여되었습니다. \n오래전에는 생일날마다 동료들과 친구들이 멀리서 찾아와 저를 둘러쌌습니다. \n사랑하는 이들에 둘러싸인 그 느낌… 태양에 안긴 듯한 따뜻함… 그것이 바로 과거를 놓지 못하는 이유일지도 모릅니다. \n아… 이야기가 길어졌네요, 당신의 일을 방해했나요? \n저는 과거에 자주 먹던 차와 간식을 준비했습니다. 함께 나누고 싶습니다. \n만약 당신이 시간을 내주시면, 저녁 식사 후에 저를 찾아주세요. \n\n팔로스"
  },
  Mail_21457_Name = {
    Text = "불멸의 빛…"
  },
  Mail_21457_Sender = {Text = "파로스"},
  Mail_21458_Desc = {
    Text = "오늘은 정말로 기념할 만한 날이다: 이날, 위대한 고리아의 주인, 거인의 왕이 세상에 강림하셨다; 이날, 바다는 떨었고, 별들은 그 빛을 잃었다. \n학교에서는 낭비를 금지한다고 하니, 내 생일 파티는 과거 규모의 십분의 일로 진행하도록 하자 — 구운 돼지 새끼 열 마리, 오징어 꼬치 백 개, 그리고 고리아 민요를 연주할 수 있는 밴드, 그리고 춤추는 여자들이 열두 명… \n뭐, 이것도 안 된다고? \n그렇다면 춤추는 여자들만 있으면 되겠군… 열두 명은 필요 없고, 네댓 명 정도면 될 것 같아. \n뭐, 이것조차도 안 된다고?! \n이런 초라한 규모는 내 신분에 걸맞지 않다. 이제 내가 선언한다, 파티 계획을 취소한다! \n\n고리아"
  },
  Mail_21458_Name = {
    Text = "만찬 계획……"
  },
  Mail_21458_Sender = {Text = "골리아"},
  Mail_21459_Desc = {
    Text = "수호자——\n\n 오늘 시엘비아 씨와 기억 훈련을 하던 중, 그녀가 내 생일에 대해 물어봤어. 너도 알다시피, 방금 놓은 렌치를 내가 돌아서면 잊어버릴 정도인데, 어떻게 생일을 기억할 수 있겠어! 더 심각한 건, 이건 오직 나만 아는 거야, 나! 이 생일은 없던 걸로 치자. \n\n 하지만 살바도르 신부님이 구체적인 날짜는 중요하지 않다고 했어, 중요한 건 매일 내가 무엇을 축하하느냐는 거라고, 그래서 결심했어, 오늘이 내 생일이야! 나는 한 사람과(누군지 잊어버렸어, 너는 아닐 거야, 수호자?) 식당 앞에서 파티를 열기로 약속했으니, 꼭 와야 해! \n\n\n\n 이 생일 날짜는 절대 절대 기억할 거야, 노틸라 \n\n\n\n 편지와 함께 온 쪽지: \n\n 그 아이가 편지를 쓰고는 허둥지둥 나가버렸어, 편지와 너에게 줄 선물을 테이블에 두고 말이야. \n 물건은 편지 봉투에 다 넣어놨어, 오늘 밤 파티에서 너를 만날 수 있기를 기대해. 걱정하지 마, 나는 그녀에게 오늘 밤 참석하라고 상기시킬 거야. \n\n — 시엘비아"
  },
  Mail_21459_Name = {
    Text = "내가 정한 생일!"
  },
  Mail_21459_Sender = {Text = "노틸라"},
  Mail_21460_Desc = {
    Text = "꼬마야:\n\n원질의 바다에는 별도 해도 달도 없고, 사계절의 교차도 없기에, 나의 생일은 [불명]으로 기재되어야 할 것이다.\n하지만 오늘은 분명 중요한 날이야. 어쨌든 이 모습은 「소원」을 품었던 어느 인간에게서 물려받은 것이니까. 그녀는 활기찬 분위기를 좋아해서 이 작은 가게를 열었지만, 여기저기 조사를 다니느라 그녀의 생일은 늘 나 혼자서 함께했지. 그녀의 생전 소원을 이루기 위해, 해우소는 오늘 촛불 만찬회를 개최하며, 충실타래한 고객 여러분을 정중히 초대합니다.\n물론, 해우소는 방문해 주시는 모든 분께 작은 할인도 제공할 예정이니, 꼬마야, 놓치지 마렴.\n\n다프다엘"
  },
  Mail_21460_Name = {
    Text = "인간의 소원…"
  },
  Mail_21460_Sender = {Text = "다포딜"},
  Mail_21461_Desc = {
    Text = "당년에 가족 곁에서 떨어져 나갔을 때, 양모…집정관 부인은 나의 출생이 적힌 흙조각을 산산조각 내어 부수고, 내가 티로스인이었던 과거를 산산조각 내어 부수었다. 진정한 생일은 물론 이제 더 이상 알 수 없게 되었다.\n라아이와 이별한 후, 나는 한참 동안 생각해 보았다…… 내가 감옥을 탈출하고 복수를 시작한 그 밤을 나의 “생일”로 삼는 것이 어떨까?\n비록 이미 나이가 한 살 더 들었음을 기념할 필요는 없지만, 시간의 흐름을 상기시키는 하나의 표시로서 꽤 괜찮을 것 같아."
  },
  Mail_21461_Name = {
    Text = "태어난 날"
  },
  Mail_21461_Sender = {Text = "히로"},
  Mail_21462_Desc = {
    Text = "테스트, 테스트.\n존경하는 수호자님, 안녕하세요. 만약 이 편지를 받으셨다면, 당신의 의견이 에리카에게 매우 중요하며, 자동인형 에리카의 언어 모듈 기능 연간 검사 및 수리 계획에 참여하도록 선정되었음을 의미합니다. 이번 평가는 단답형 문제로 진행되며, 자동인형 에리카에 최신 설치된 EA-L-1033번 언어 모듈의 기능을 평가해 주실타래 것을 요청드립니다. 평가에는 많은 시간이 소요되지 않으며, 긴장하거나 당황하실타래 필요는 없습니다.\n단답형 문제:\n이 편지의 대략적인 내용을 이해하셨나요?\n\n답변은 단답형 문제 아래의 빈칸에 직접 작성해 주시고, 편지를 다시 봉투에 넣어 주세요.\n참여해 주셔서 감사합니다.\n\n에리카"
  },
  Mail_21462_Name = {
    Text = "테스트, 테스트……"
  },
  Mail_21462_Sender = {Text = "에리카"},
  Mail_21463_Desc = {
    Text = "수호자: \n\n당신은 이 학교에서 보기 드문 정신이 맑은 사람입니다. 당신의 시선은 이 불완전한 몸을 뚫고 진실타래된 나를 볼 수 있습니다. \n그런 당신이라면, 그 아이들에게 제대로 설명해 줄 수 있을 것입니다. 나는 인어가 아니며, 이 몸은 결국 바다와 산을 넘어서 완벽한 몸을 이루어 갈 것입니다. \n… 그래도, 당신을 곤란하게 하지는 않겠어요. 하지만 적어도 오늘은 아이들이 내 꼬리를 가지고 노는 것을 막아주세요. \n오늘은 특별한 날입니다. 만약 시간이 있다면, 당신에게 직접 말하고 싶은 것이 있어요. \n\n케이크스"
  },
  Mail_21463_Name = {
    Text = "완벽한 몸…"
  },
  Mail_21463_Sender = {
    Text = "카이커스"
  },
  Mail_21464_Desc = {
    Text = "수호자: \n\n세속적인 의미에서의 제 생일은 아버지께서 저를 입양하신 날입니다. \n과거에 아버지는 항상 이날을 특히 중요하게 여기셨고, 매년 큰 무도회를 열었죠 — 허리가 조인 옷을 입고 춤추는 건 칼을 삼천 번 휘두르는 것보다 더 피곤해요. \n하지만 이것이 아버지로서의 마음이셨기에, 저는 이 소중한 사랑을 저버리고 싶지 않았습니다. \n올해는 아버지께서 마침내 저에게 생일 일정을 스스로 준비하도록 허락하셨어요. 아마 아버지의 눈에는 제가 더 이상 눈앞에서 돌봐야 할 어린아이가 아니게 되었나 봅니다. \n그런데, 당신이 저와 함께 종탑 꼭대기에 올라가 주실타래 수 있나요? 이야기도 나누고 바람도 쐬면서요. \n들리는 말로는, 오늘 밤이 만월이라고 하더군요.\n\n라모나"
  },
  Mail_21464_Name = {
    Text = "보름달…"
  },
  Mail_21464_Sender = {Text = "라모나"},
  Mail_21465_Desc = {
    Text = "사랑하는, 가장 사랑하는 주인님: \n네, 맞아요. 오늘은 가렌이 @1살 생일이에요 (여성의 나이는 비밀이에요)! \n이를 위해 가렌은 끝내주는 화려한 파티를 준비했어요. 그리고 초대할 수 있는 모든 친구들을 초대했어요~! 하지만 결국 오겠다고 한 건 오레타, 오지르와 리리뿐이었어요… \n하지만 상관없어요. 사람이 있는 곳에 파티가 있고, 파티가 있는 곳에 가렌이 있으니까요! 가렌은 '개선된 버전' 개구리 스튜, 마늘 향이 나는 이탄 달팽이와 커리 박쥐 국을 정성껏 준비했어요. 주인님 꼭 맛보세요~ \n\n조금만 물어봐도, 주인님은 가렌에게 선물을 준비하셨겠죠? 반짝이는 걸로 준비해주세요! \n\n항상 겸손한 여종으로서 \n가렌"
  },
  Mail_21465_Name = {
    Text = "선물……"
  },
  Mail_21465_Sender = {Text = "카렌"},
  Mail_21466_Desc = {
    Text = "친애하는 <Del:수호자> 서구 친구에게:\n이건 <Del:초대쟝 초대장을 초대쟝 초대장> 어쨌든 공짜 케이크를 먹으러 오라는 초대장이야, 겸사겸사 내 생일도 축하해 줘! 사실타래 전에 네가 언니를 찾아준 것도, 나를 여기로 데려와서 나랑 브라운이 안심하고 지낼 수 있는 곳을 마련해 준 것도 고마워서 그래.\n(위에 있는 건 에이지스가 쓰라고 한 거야, 진짜 오글거려. 우리 사이에 이런 건 필요 없잖아, 그치, 수호자?)\n어쨌든, 오늘 밤 네 숙소 뒤편 마당에서 나랑 브라운, 에이지스가 직접 준비한 좋은 것들이 기다리고 있으니까 같이 나누러 와! 물론 사실타래 주로 에이지스가 만든 거야, 걔가 만드는 건 진짜 맛있거든, 주방 아주머니들도 재능 있다고 칭찬하셨어. 안 오면 후회할 거야, 장담해.\n\n네 오랜 친구 젠킨과 브라운이"
  },
  Mail_21466_Name = {
    Text = "친애하는 서부 지구의 친구들…"
  },
  Mail_21466_Sender = {Text = "젠킨"},
  Mail_21467_Desc = {
    Text = "수호자：\n\n사람들이 신의 나라에 살고 있을 때, 우리는 이미 춤으로 감정을 표현하기 시작했다——환희의 회전, 슬픔의 발걸음……누군가는 춤의 역사와 인간의 역사가 동일하게 오랫동안 지속된다고 한다. 그것은 우리의 영광을 목격했으며, 또한 우리의 침체를 목격했다.\n\n나는 더 이상 춤을 추지 않겠다고 했지만……나는 어찌 되었든 춤을 위한 존재이다. 그래서 단지 오늘, 너는 나와 함께 춤을 출 수 있겠는가? 나와 몰입하여 신체 깊이의 리듬을 느껴보자.\n\n나는 무용실타래에서 너를 기다릴 것이다.\n\n\n\n리즈"
  },
  Mail_21467_Name = {
    Text = "함께 춤추는 초대"
  },
  Mail_21467_Sender = {Text = "리즈"},
  Mail_21468_Desc = {
    Text = "존경하는 수호자：\n\n제가 아직 깨어남체가 되기 전에，제 생일은 군번져 나와 동료들과 함께 군영 밖에서 술을 들여와 물자 창고의 텐트 안에서 배급된 검은 빵과 함께 몰래 축하했습니다。\n\n그러나 미사그는 군대가 아닙니다，여기서는 마음껏 방탕할 수 있습니다。당신이 저와 함께 한 병의 좋은 술을 나누며 제 생일을 축하하고 싶지 않습니까？\n만약 당신이 원한다면，오늘 밤 달이 종탑을 넘을 때，기숙사의 옥상으로 오세요。당신은 아마 당신이 주목했을 것입니다, 거긴 미사그에서 가장 좋은 전망을 가지고 있습니다。\n\n\n\n앨바"
  },
  Mail_21468_Name = {
    Text = "고급 술을 나누는 일..."
  },
  Mail_21468_Sender = {Text = "엘바"},
  Mail_21469_Desc = {
    Text = "해변 해변 해변 해변!\n응? 편지 맨 앞에 받는 사람 이름을 써야 한다니—정말 귀찮아! 수호자가 냉장고에 붙여놓은 메모에는 받는 사람 이름이 없었는데!\n오늘은 오레타의... 어... 몇 번째 생일이더라? 아무튼 오레타의 생일이야!\n이건 다 오레타의 보물이야! 전부 너한테 줄게! 오레타를 해변으로 데려가줘, 제발, 제발, 부탁해!\n오레타의 생일 선물로 주는 거라고 생각해줘, 알겠지?~\n\n오레타"
  },
  Mail_21469_Name = {Text = "해변!"},
  Mail_21469_Sender = {Text = "오레타"},
  Mail_21470_Desc = {
    Text = "귀인: \n\n과거 누나와 황무지에서 함께 있을 때, 우리는 항상 서로를 안고 같은 식물의 에너지를 흡수하며 우리의 탄생을 기념했습니다. \n그 시절은 쓰라렸지만, 지금 생각해보면 기쁨과 따뜻함이 느껴집니다. \n오늘도 우리의 탄생을 기념하는 날입니다. 가능하다면, 한 곡의 노래로 한 조각의 가지를 교환할 수 있을까요? \n달콤한, 누나와 나의 과거를, 그리고 당신과 나의 미래를 대표하는 가지…… \n\n틴커트"
  },
  Mail_21470_Name = {
    Text = "생일 노래"
  },
  Mail_21470_Sender = {Text = "틴커트"},
  Mail_21471_Desc = {
    Text = "운명의 큰 은혜를 받은 미사그 대학의 수호자, 현명하고 인자하신 주군: \n만안하시기를! \n며칠 전, 학교 마구간으로 화물차가 드나드는 것을 보았습니다. 그 안에는 따뜻한 혈통의 말이 실타래려 있었습니다. 지난번 주군과 함께 조사 임무를 수행할 때, 주군께서 말을 타 본 적이 없다고 하셨던 것을 떠올렸습니다. 따뜻한 혈통의 어린 암말은 가장 온순하여 초보자가 말 등에 적응하는 데 가장 적합합니다. \n말을 타고, 새벽과 황혼을 쫓는 것은 제 기억 속에서 가장 편안한 순간입니다. 주군께서 동의하신다면, 저와 함께 말을 타시면 좋겠습니다. 이 편안함을 주군과 나누고 싶습니다. \n\n오지르"
  },
  Mail_21471_Name = {
    Text = "따뜻한 말..."
  },
  Mail_21471_Sender = {Text = "오지에"},
  Mail_21472_Desc = {
    Text = "옛 나라의 역법은 오늘날 런디니엔에서 사용하는 것과 크게 다르다.\n여는 두 번째 여름달의 다섯 번째 만성일에 태어났으며, 오늘 축하하기로 한 것은 실타래험실타래 책임자가 계산한 결과이다.\n옛 나라가 건재했을 때, 주제관이 모든 것을 준비했다. 성대한 제사가 끝나면 온 나라가 경축하며, 7일간의 휴일에 들어갔다.\n여가 바란 바는 아니나, 환희의 확산을 막을 이유 또한 없었다.\n오늘은 미사그의 공휴일이 아니며, 수호자의 직책상 규칙적인 휴일도 없을 것이다.\n하지만, 여의 생일 축하를 명목으로 휴가를 신청한다면, 관리처도 감히 이의를 제기하지 못할 것이다.\n한가로운 오후를 보내도록 하라.\n\n투루"
  },
  Mail_21472_Name = {Text = "생일…"},
  Mail_21472_Sender = {Text = "툴루"},
  Mail_21473_Desc = {
    Text = "수호자: \n\n오레타는 말했지, 생일에는 소원을 빌어야 한다고. \n하지만 나는 한 번도 소원을 빌지 않는 사람이야. \n왜냐하면 내 생각은 항상 이루어지거든. 이것은 운이 좋은 것이 아니라, 마치 어떤……운명적인 지침 같아? \n지난달 힐레스트와 함께 바다로 나갔을 때, 나는 또 「마침」아름다운 화석을 발견했어. \n그곳 주민들은 그것을 「바다백합」이라고 불렀어. 그 손목은 물결을 향해 풍차처럼 뻗어 있고, 여름 오후의 태양을 느긋하게 즐기고 있었어. \n약함, 아름다움. 그것을 보았을 때, 자연스럽게 네 모습이 떠올랐어. \n이번에도 역시 소원을 빌지 않았어—— \n네가 확실타래 좋아할 거야, 그렇지? \n\n산"
  },
  Mail_21473_Name = {
    Text = "바다백합..."
  },
  Mail_21473_Sender = {Text = "산"},
  Mail_21475_Desc = {
    Text = "수호자: \n\n엘튼과 항해할 때, 그는 매년 이 날 음식을 준비하고 저에게 “소원”을 빌라고 했습니다. \n여기에 오기 전까지 저는 “소원”이 무엇인지 이해하지 못했습니다. 지금, 제가 어떤 “소원”을 가질 수 있을지 알 수 없습니다…… \n아마, ‘소원’을 찾는 것 자체가 ‘소원’이 될 수도 있겠네요? \n\n힐레스트"
  },
  Mail_21475_Name = {Text = "소원…"},
  Mail_21475_Sender = {
    Text = "셀레스트"
  },
  Mail_21476_Desc = {
    Text = "수호자: \n\n오레타가 생일날 빈 소원을 모두 이루어준다고 했어, 맞지? \n설마 진짜겠어? 모든 사람의 소원을 들어주는 건 너에게 너무 번거로울 거야. \n하지만 만약 소원을 빌 수 있다면…… 틴커트가 더 넓은 무대를 갖게 되는 걸 바라고 싶어. \n너무 어려운 소원이야? 음…… 그럼, “앞으로 한 해 동안 내 식탁에 셀러리가 나오지 않게 해줄래?” \n\n파인트"
  },
  Mail_21476_Name = {Text = "소원…"},
  Mail_21476_Sender = {Text = "파인트"},
  Mail_21477_Desc = {
    Text = "친애하는 수호자님:\n\n비밀을 하나 알려드릴게요: 이 생일은 사실타래 가짜예요. 제 진짜 생년월일은…… 바람에 흩어지도록 하죠.\n병이 난 후로, 형은 항상 생일이 되면 집사에게 저를 위한 작은 케이크를 준비하도록 했어요.\n생일 노래도, 축복도 없었어요. 마치 생일을 지내는 것이 부끄러운 일처럼 느껴졌죠.\n지금은 모든 것이 달라졌어요. 저는 햇빛 아래를 걸을 수 있고, 크게 노래 부를 수 있으며, 생일을 지낼 수도 있어요.\n이런 사소한 기쁨들이지만, 저에게는 그리움으로 다가옵니다.\n감사합니다, 수호자님.\n\n(물론, 당신과 모두가 저에게 조금 더 거칠게, 더 거칠게 대해주신다면…… 정말 완벽할 거예요.)\n\n레이아"
  },
  Mail_21477_Name = {
    Text = "비밀 하나..."
  },
  Mail_21477_Sender = {Text = "레아"},
  Mail_21478_Desc = {
    Text = "내 작은·죄수: \n\n나는 벌써 오래·오래·오래 채찍을 휘두르지 않았어——\n이 무미건조한 학교에 갇혀, 교복에 갇혀, 판디아의 마음은 가려워졌어. 마치 장난꾸러기 고양이가 긁어대는 것 같아. 하지만 나를 이해하는 사람은 없고, 그 직원들은 내가 “재미”를 찾는 것을 천방백계로 막으려고 해——정말 너무해!\n아, 오늘은 특수한 날이야. 내 채찍이 부드러운 피부를 다시 접촉하는 것이 좋을 것 같아. 내가 고통의 시전을 듣는 거야……오늘 시간이 있다면, 나와 대화를 나누러 오는 게 어떨까?~ \n\n판디아"
  },
  Mail_21478_Name = {
    Text = "채찍 소리…"
  },
  Mail_21478_Sender = {Text = "판디아"},
  Mail_21479_Desc = {
    Text = "<Big:마법사 카시아의 주년 기념 공연, 오늘 하루만!>\n\n여러분들의 오랜 지지와 격려에 감사드리며, 과거에 여러분이 주신 모든 즐거움에 보답하기 위해, 마법사 카시아는 오늘 저녁 8시 정각, 미사그 대학 중정(필립스 조각상 옆)에서 특별 주년 기념 공연을 진행합니다! 오늘 밤, 여러분은 이전보다 더 화려한 무대, 더 스릴 넘치는 공연, 그리고 — 가장 중요한 것은 — 더 신비로워서 자신의 눈을 믿을 수 없을 정도의 화려한 마법을 보실타래 수 있습니다! 심지어 미사그의 두뇌가 현장에 직접 와도 이 상상 이상의 마법에 감탄할 것입니다. 이는 카시아 마법사의 보증입니다!\n\n기회는 한 번뿐, 단 하루뿐이며 완전 무료입니다! 카시아 마법사는 여러분과 반드시 만나겠습니다!\n\n<Small:PS: 공연 중이나 이후에 정신적 피로, 기분 저하 등의 증상이 나타나더라도 카시아 마법사는 책임을 지지 않습니다.>\n<Small:PPS: 미사그의 두뇌와 관련된 모든 홍보는 실타래제 상황에 따라 다를 수 있으며, 카시아 마법사는 프로그램 및 프로그램 효과에 대한 모든 해석 권리를 보유합니다.>"
  },
  Mail_21479_Name = {
    Text = "대마술사 카시아의 주년 기념 공연!"
  },
  Mail_21479_Sender = {Text = "카시아"},
  Mail_21480_Desc = {
    Text = "야, 오늘은 내 생일이야, 선물은? \n뭐? 깜빡하고 준비를 안 했다고...? 흥, 그럴 줄 알았어. \n여기, 이 달력을 가져가. 내 생일, 기일, 미사그에 처음 온 날, 희락제, 농신제…… 등의 날짜가 분명히 적혀 있어. 이 축제들은 우리 함께 해야 하니까 다음에는 잊지 마! \n\n만약 다음에도 잊어버린다면...... 어차피 널 어떻게 할 수는 없겠네, 흥. \n아무리 그래도 잊으면 안 돼!\n\n아그리파"
  },
  Mail_21480_Name = {Text = "야......"},
  Mail_21480_Sender = {
    Text = "아그리파"
  },
  Mail_21481_Desc = {
    Text = "수호자: \n\n나는 이 편지를 쓰고 싶지 않았지만, 에리카의 작동에 문제가 생긴 것 같다. 이 편지를 다 쓰기 전까지 그녀의 경보가 계속 울렸다. \n생일은 나에게 무의미한 날짜일 뿐이다. 실타래험의 성공률은 다른 날들보다 높아지지 않고, 내 노스 지수도 이 날짜 때문에 어떤 변화도 일어나지 않는다. 하지만 라모나는 이날을 내 “휴식일”로 만들려고 고집을 부렸다며, 오늘 연구실타래에 들어가는 권한을 제한했다. \n나는 갈 곳이 없으므로, 오늘은 당신의 과거 보고서를 전면적으로 검토할 것이다. \n저녁 식사 후에 아카이브로 와라. 주의하세요, 어떤 케이크든 아카이브로 가져오지 마세요. 종이 기록은 매우 약함이다. \n\n돌"
  },
  Mail_21481_Name = {
    Text = "저녁 식사 후…"
  },
  Mail_21481_Sender = {Text = "돌"},
  Mail_22435_Desc = {
    Text = "사랑하는 수호자님:\n처음에는 사람들이 적고 시의 세계에 더 깊이 빠져들 수 있을 것 같아 여명이 밝아오는 캠퍼스에서 시를 읽기로 했습니다. 시간이 지나면서 저는 차츰 아침의 희미한 하늘빛, 투명하고 맑은 이슬, 그리고 맑고 부드러운 새소리까지 사랑하게 되었습니다.\n놀랍게도 많은 선생님과 학생들이 저를 조용히 관심 있게 지켜보고 있었고, 비공식적으로 시 동호회를 결성했다는 사실타래을 알게 되었습니다. 오늘은 제 생일인데, 마침 동호회의 수선화가 곧 피어날 준비를 하고 있어 이를 계기로 그들은 캠퍼스에서 함께 풍경을 감상하며 시를 읽는 시 감상 모임을 준비하고 있습니다.\n이런 정경에서 당신께서도 함께 와주셔서 감상해 주시면 좋겠습니다. \n\n닝피아"
  },
  Mail_22435_Name = {
    Text = "시 읽기 모임 초대"
  },
  Mail_22435_Sender = {Text = "님피아"},
  Mail_23897_Desc = {
    Text = "존경하는 수호자:\n        V1.0.21 업데이트에서 우리는 「조사 작전 작전」의 어려움 난이도, 「의식 잠수」 전투 관문의 보통 및 어려움 난이도, 그리고 「무광의 경계」의 각 경계역의 회전 간격 Ⅰ-Ⅳ마다의 처음 통과 보상을 조정하였습니다. 자세한 조정 내용은 「V1.0.21 온라인 유지보수 공지사항」에서 확인하실타래 수 있습니다.\n        귀하의 이전 조사 작전와 도전 클리어 기록에 따라, 조정된 보상으로 이전에 수령하지 못한 보상을 일괄 지급해 드릴 예정입니다. 구체적인 내용은 첨부파일을 확인해 주십시오."
  },
  Mail_23897_Name = {
    Text = "V1.0.21 조정 보상"
  },
  Mail_23897_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_24199_Desc = {
    Text = "존경하는 수호자님:\n        V1.0.24 업데이트에서 V1.0.16에서 일시적으로 닫혔던 「조사 작전 작전」 제5장을 다시 오픈했습니다. 공정성을 기준으로, 조정 전후의 보상 변화와 각 수호자의 조사 작전 기록을 토대로 적절한 보상이 발송되었습니다. 귀하의 조사 작전 기록에 따라 보상이 첨부파일로 발송되었습니다."
  },
  Mail_24199_Name = {
    Text = "V1.0.24 제5장 재개방 보상금"
  },
  Mail_24199_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_24200_Desc = {
    Text = "존경하는 수호자님:\n        V1.0.24 업데이트에서 V1.0.16에서 일시적으로 닫힌 「조사 작전 작전」 제5장이 다시 열렸습니다. 공정성을 기준으로, 조정 전후의 보상 변화와 각 수호자의 조사 작전 기록을 바탕으로 적절한 보상을 제공할 예정입니다. 귀하의 조사 작전 기록에 따르면, 이번에는 보상이 필요하지 않습니다."
  },
  Mail_24200_Name = {
    Text = "V1.0.24 제5장 재개방 보상금"
  },
  Mail_24200_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_24202_Desc = {
    Text = "존경하는 수호자님:\n        《망각의 전야》에 대한 귀하의 지원과 인식에 감사드립니다. 수호자들이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록, 아래의 체험 조사 설문지를 작성해 주시기를 정중히 요청드립니다. 귀하의 협조에 감사드리며, 설문지를 완료하시면 「은심」× 200을 보상으로 준비했습니다. \n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 의견을 귀 기울여 듣겠습니다. 귀하의 피드백은 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
  },
  Mail_24202_Name = {
    Text = "버전 체험 조사 설문지 V1.0 하단"
  },
  Mail_24202_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_24280_Desc = {
    Text = "안녕하세요, 수호자 님.\n수호자 님께서는 어제 환몽 심잠 조사 랭킹에서 「{s1} 랭킹」 {s2}위를 차지하셨으며, 조사 칭호는 「{s3}」입니다. 아래는 랭킹 보상입니다, 수호자 님께서는 반드시 확인 후 수령해 주세요."
  },
  Mail_24280_Name = {
    Text = "환몽 심잠 일일 랭킹 보상"
  },
  Mail_24280_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_24877_Desc = {
    Text = "수호자: \n\n내 모든 생일은 언제나 가장 성대한 살롱으로, 높은 손님들로 가득 차며 즐거움이 넘칩니다. \n하지만 이번에는 조금 다른 생각이 듭니다 —— \n주인 자리에 너무 오래 앉아 있었더니 가끔은 손님이 되어보고 싶다는 생각이 듭니다. \n또 한 번의 세련된 살롱이 될지, 아니면 평범한 저녁 식사가 될지는 모두 당신에게 달려 있습니다. 어떻게 하시겠습니까? \n다만, 만약 살롱을 다시 연다면, 그 명사 귀족들은 초대하지 않는 것이 좋겠습니다. \n소중한 날에 위선적인 미소를 짓고 싶지 않으니까요. \n\n<Del:레드 레디> 소렐"
  },
  Mail_24877_Name = {
    Text = "당신에게 결정을 맡길게요..."
  },
  Mail_24877_Sender = {Text = "소렐"},
  Mail_24878_Desc = {
    Text = "주인님: \n\n오늘은 릴리의 생일이예요. 아그리파가 “큰 파티를 열자”라고 했어요. \n예전에 엄마와 릴리는 생일을 이런 방식으로 축하하지 않았아요. 엄마는 제게 뾰족한 모자를 씌워주고 함께 박수를 치며 촛불을 껐어요. \n릴리는 어떻게 하는 것이 옳은지 모르겠어요. 주인님, 명령을 내려주세요. \n\n릴리"
  },
  Mail_24878_Name = {Text = "고민…"},
  Mail_24878_Sender = {Text = "릴리"},
  Mail_25147_Desc = {
    Text = "존경하는 수호자님:\n        V1.1.0 업데이트에서 이번 주 환몽 심잠 포인트 보상이 해제되었으며, 새로운 ‘주간 시련’으로 대체되었습니다. 공정성을 기준으로, 이전에 ‘환몽 심잠’을 해금했지만 이번 주 포인트 보상을 전부 수령하지 않았고, 1월 15일 오전 5시 전에 게임에 로그인한 수호자분들께 미수령된 이번 주 포인트 보상을 지급해 드립니다. 확인 부탁드립니다."
  },
  Mail_25147_Name = {
    Text = "V1.1.0 환몽 심잠 이번 주 포인트 보상금"
  },
  Mail_25147_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_25148_Desc = {
    Text = "존경하는 수호자님:\n        V1.1.0 업데이트에서, 페이즈 대결(베타)의 「매주 보상」이 하차하고 「매주 시험」으로 교체되었습니다. 이는 환몽 심잠의 「매주 시험」과 동일한 진행도와 보상을 가집니다. 공정한 원칙에 따라, 이전에 「페이즈 대결(베타)」를 잠금 해제했으나 이번 주 「매주 보상」을 완료하지 않거나 수령하지 않은 상태로 1월 15일 5:00(UTC+8) 이전에 게임에 로그인한 수호자님께는 융식의 구슬×1000을 보상으로 드립니다. 확인해 주시기 바랍니다."
  },
  Mail_25148_Name = {
    Text = "V1.1.0 페이즈 대결 주간 보상 보상금"
  },
  Mail_25148_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_25414_Desc = {
    Text = "늘 존경스러운 우리의 수호자에게.\n\n탄생의 날의 무게라는 것은 각 사람마다 제각각이겠지만, 수호자의 생일은 미사그 전체에게 매우 중요한 날이야.\n실타래비아 여사님께서 기숙사에 생일 파티를 준비해주셨어. 코레트 원장님과 덱스터 로드께서 참석해 주실타래 예정이래. 아직 정신적인 피로가 싹 가시지 않았단 걸 눈치채고, 내가 이미 정장을 준비해서 네 문 앞 옷장에 고이 걸어뒀지. 참석하기 전에 바로 입고 오면 돼.\n올해 네 파트너로서 함께할 수 있어서 영광이었고, 내년에도 네 파트너로서 함께 하길 바라.\n은열쇠가 앞길을 밝혀주길.\nP.S. 커스텀한 미니 케이크, 에리카가 기숙사로 배달해 뒀어.\n\n네 영원한 파트너가 되고 싶은, 라모나가."
  },
  Mail_25414_Name = {
    Text = "태어난 날..."
  },
  Mail_25414_Sender = {Text = "라모나"},
  Mail_34667_Desc = {
    Text = "존경하는 @1@2:\n\n세계는 네 이름을 잊었어. \n그래서 나는 널 깨웠지. 네가 나를 깨운 것처럼. 종말이 도래하기 전, 너와 나는 이 세상을 걸으며 목격하고, 기억하고 또 망각했어. \n오늘은 네 생일. 너 자신이 잃어버린 기억의 파편에서 우연히 발견한 한 페이지야. 네 생일에 탄식과 축복을 보낼게. \n세계가 너의 완전한 모습을 기억해낼 때, 너는 어떤 감정을 느낄까? 혹시 여전히 아무것도 모른 채, 아무것도 느끼지 못하는 걸까? \n존재하지 않는 곳에서 네 답변을 기다릴게. \n\n@2"
  },
  Mail_34667_Name = {
    Text = "태어난 날..."
  },
  Mail_34667_Sender = {Text = "@2"},
  Mail_35231_Desc = {
    Text = "존경하는 수호자님:\n        《망각의 전야》에 대한 귀하의 지원과 인식에 감사드립니다. 수호자들이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록, 아래의 체험 조사 설문지를 작성해 주시기를 정중히 요청드립니다. 귀하의 협조에 감사드리며, 설문지를 완료하시면 「은심」× 200을 보상으로 준비했습니다. \n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 의견을 귀 기울여 듣겠습니다. 귀하의 피드백은 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
  },
  Mail_35231_Name = {
    Text = "버전 체험 조사 설문 V1.1 부분"
  },
  Mail_35231_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_35956_Desc = {
    Text = "존경하는 수호자:\n        “망각의 전야”에 대한 지원과 인식에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기를 정중히 요청드립니다. 협조해 주신 것에 대한 감사로, “은심” × 200을 보상으로 준비하였습니다. 설문지를 완료하시면 수령하실타래 수 있습니다. 설문지 마감 시간은 2월 22일 5:00이며, 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 제안을 진지하게 듣겠습니다. 여러분의 피드백은 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
  },
  Mail_35956_Name = {
    Text = "버전 체험 조사 설문 V1.1 부분"
  },
  Mail_35956_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_36228_Desc = {
    Text = "존경하는 수호자님:\n        “망각의 전야”에 대한 지원과 인식에 감사드립니다. 수호자 여러분이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기를 진심으로 초대합니다. 협조해 주신 데 대한 감사로 “은심” × 200을 보상으로 준비했습니다. 설문지를 완료하시면 수령 가능합니다. 설문 마감 시간은 6월 17일 9:00이며, 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 제안을 진지하게 듣고 있으며, 여러분의 피드백은 미사그 대학을 더욱 발전시킬 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
