  },
  Mail_36229_Desc = {
    Text = "존경하는 수호자:\n        “망각의 전야”에 대한 지원과 인정을 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 하실타래 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기를 정중히 요청드립니다. 협조해 주신 것에 대한 감사로 “은심” × 200을 보상으로 준비하였습니다. 설문지를 완료하시면 수령하실타래 수 있습니다. 설문 마감 시간은 7월 08일 9:00이며, 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 의견을 진지하게 듣고 있으며, 여러분의 피드백은 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
