  },
  Mail_36230_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_36231_Desc = {
    Text = "존경하는 수호자님:\n        《망각의 전야》에 대한 귀하의 지원과 인식에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록 아래의 경험 조사 설문지를 작성해 주시기 바랍니다. 귀하의 협조에 감사드리며, 「은심」× 200을 보상으로 준비했습니다. 설문지를 완료하시면 수령 가능하십니다. 설문 마감 시간은 8월 05일 9:00입니다. 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[ 클릭하여 작성하기 ]>\n        우리는 모든 수호자님의 제안을 진지하게 듣겠습니다. 귀하의 피드백이 미사그 대학을 더욱 발전시키는 데 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
  },
