  Mail_36234_Desc = {
    Text = "존경하는 수호자님:\n        《망각의 전야》에 대한 지원과 인정에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 하실타래 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기를 정중히 요청드립니다. 협조해 주신 것에 대한 감사로 「은심」× 200을 보상으로 준비했습니다. 설문을 완료하시면 수령하실타래 수 있습니다. 설문 마감 시간은 3월 14일 5:00이며, 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 각 수호자의 의견을 신중히 듣겠습니다. 여러분의 피드백은 미사그 대학을 더욱 발전시키는 데 기여할 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
