  Mail_36235_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_36865_Desc = {
    Text = "존경하는 수호자:\n        V1.2.4 업데이트에서 「환몽 심잠」 주간 시련의 보상이 조정되어 「융식의 구슬」, 「모방결정체」, 「장미 금권」 보상은 더 이상 제공되지 않습니다. 공평한 원칙에 따라 업데이트 전 「환몽 심잠」을 해금했지만, 이번 주 시련 보상을 전부 수령하지 않았고 3월 11일 오전 5시 이전에 게임에 로그인한 수호자에게 이번 주 시련에서 수령하지 않은 원래의 「융식의 구슬」, 「모방결정체」, 「장미 금권」 보상을 보상합니다. 확인해 주세요."
  },
  Mail_36865_Name = {
    Text = "V1.2.4 주간 시련 보상 조정 보상금"
  },
  Mail_36865_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_36866_Desc = {
    Text = "존경하는 수호자:\n        V1.2.4 업데이트에서 '피와 모래', '왜곡된 핵심', '기사의 소원'의 보통 모드 클리어 시 새로운 키오링 '분노의 피와 모래', '단시간의 영원', '마지막 서약'이 추가되었습니다. 업데이트 전에 위 챕터의 보통 모드를 완료한 수호자에게는 해당 키오링을 보상으로 제공합니다. 확인해 주세요."
  },
  Mail_36866_Name = {
    Text = "V1.2.4 의식 잠수 키오링 재발급"
  },
  Mail_36866_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_36867_Desc = {
    Text = "존경하는 수호자: \n        V1.2.4 업데이트에서 「초월적 존재」 드롭의 독특한 스킬 업그레이드 소재와 모방결정체 수량이 증가되었습니다. 공평한 원칙에 따라, 업데이트 전 이미 이번 주 「초월적 존재」 보상을 수령한 수호자에게는 해당 보상의 추천 등급에 따라 증가된 드롭과 동일한 가치의 「모방결정체」를 추가로 지급하겠습니다. 확인 부탁드립니다."
  },
  Mail_36867_Name = {
    Text = "V1.2.4 초월적 존재 보상 조정 보상"
  },
  Mail_36867_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_36871_Desc = {
    Text = "수호자 님, 안녕하세요.\n어제 환몽 심잠의 최고 난이도를 클리어한 결과, 다음과 같은 보상을 획득하셨습니다. 반드시 확인해 주세요."
  },
  Mail_36871_Name = {
    Text = "매일 환몽 심잠 보상"
  },
  Mail_36871_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_39293_Desc = {
    Text = "존경하는 수호자:\n        V1.2.7 업데이트에서 “의식 잠수: 보통 모드”의 “노래 같은 조각”, “백색 후예”, “한 걸음 차이”를 클리어하면 새로운 키오링 “뼈를 갉아먹는 포옹”, “호수에서 돌아보기”, “회고의 문을 넘어가다”가 해금됩니다. 업데이트 이전에 위 세 편의 보통 모드를 완료한 수호자에게는 해당 키오링을 추가로 지급하겠습니다. 확인 부탁드립니다."
  },
  Mail_39293_Name = {
    Text = "V1.2.7 의식 잠수 키오링 재발급"
  },
  Mail_39293_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_39548_Desc = {
    Text = "사랑하는 수호자:\n\n영원한 생명에게 있어서 생일을 기념하는 것은 불필요해 보입니다. 무한한 시간의 흐름에 비해, 인간들이 잊지 못할 혹은 빛나는 순간이라고 부르는 기억들은 조금…… 사소해 보이죠.\n그럼에도 불구하고, 인간들은 이들 “사소함”을 기념하기 위해 수많은 축제와 기념일을 발명했습니다. 물론, 이것이 바로 나를 관심을 갖게 만든 이유 중 하나입니다. 인간들은 정말로 귀엽습니다.\n하지만, 당신과의 만남은 이러한 “사소함” 중 하나로 치부할 수 없습니다. 당신은 그들과 다릅니다…… 그리고 이 “다름”이 미래에 어떤 폭풍을 일으킬지, 나는 매우 기대하고 있습니다.\n좋아요, 제 수다를 용서해 주세요…… 오늘은 제 생일이니까, “생일의 권리를” 행사하고 싶어요.\n당신이 해야 할 일은, 쫓지 말고…… 답은 제 침실타래에 있습니다. 오늘 밤 자정에 혼자 찾아오세요.\n\n완다"
  },
  Mail_39548_Name = {
    Text = "생일 주인공의 권리……"
  },
  Mail_39548_Sender = {Text = "완다"},
  Mail_39549_Desc = {
    Text = "오늘은 머피님의 생일——생일이니까 파티와 축제가 있어야 해! \n물자 관리처 사람들도 꽤 잘했지만, 그들은 정말 연기를 잘 하지 못해, 숨기려고 하는데——저는 이미 그들이 깨어남 계열 창고에 케이크 장식을 넣는 것을 봤어요. 음……당신은 그 직원들을 처벌하지 않을 거예요? 그,그들은 정말 잘했어요, 놀라움만 제대로 숨기지 못했을 뿐이죠……\n여기까지 쓰겠습니다, 누군가 저를 외출하러 부르는 것 같아——그들이 바보 같은 색종이 조각으로 저를 덮지 않는다면 좋겠네요. \n참고로, 케이크를 자를 때, 당신도 있을 거죠? \n\n머피"
  },
  Mail_39549_Name = {
    Text = "생일 파티…"
  },
  Mail_39549_Sender = {Text = "머피"},
  Mail_43571_Desc = {
    Text = "존경하는 비밀 지키는 사람에게:\n        V1.2.10 업데이트에서 [안개 도시 기행] 활동 태스크[조사 메인라인 1장 “동구의 비밀” 어려움 난이도 완료]와[조사 메인라인 2장 “로상의 이름으로” 어려움 난이도 완료]에 보상으로 [은심] × 1000이 추가되었습니다. 업데이트 전 이미 위의 태스크 보상을 받은 비밀 지키는 사람에게는 해당 은심을 보충해 드립니다. 확인 바랍니다."
  },
  Mail_43571_Name = {
    Text = "V1.2.10 안개 도시 기행 보상 재배포"
  },
  Mail_43571_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_43821_Desc = {
    Text = "존경하는 수호자:\n        V1.3.0 업데이트에서 「행동 보고서」 1/2/3/4/5/6 단계 보상에 각각 수호자 경험치 500/1000/1500/2000/2500/3000이 추가되었습니다. 업데이트 전에 위 단계 보상을 모두 수령한 수호자에게는 해당 경험을 보충 발송하겠습니다. 확인해 주세요."
