  },
  Mail_43821_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_44571_Desc = {
    Text = "존경하는 수호자:\n「영혼의 목자」는 4월 18일 오전 9시에 종료됩니다 [GMT+8]. 이벤트가 종료되면, 성당의 길, 성당 자선 판매 현장 등 해당 이벤트 입구가 닫히며, 기한 내에 사용하지 않은 의미 있는 판매권은 자동으로 사라집니다. 수호자는 이벤트 종료 전에 성당 자선 판매 현장에서 상품을 구매하도록 하세요."
  },
  Mail_44571_Name = {
    Text = "영혼의 목자 이벤트가 곧 끝납니다"
  },
  Mail_44571_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_44690_Desc = {
    Text = "안녕하세요, 수호자 님.\n수호자 님께서는 어제 환몽 심잠에서 대리 외근을 진행하셨으며, 조사 칭호는 「{s1}」입니다. 아래는 랭킹 보상입니다, 수호자 님께서는 반드시 수령해 주세요."
  },
  Mail_44690_Name = {
    Text = "환몽 심잠 대리 랭킹 보상"
  },
  Mail_44690_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_44831_Desc = {
    Text = "존경하는 수호자님:\n        V1.3.0 업데이트에서 「비 마을의 그림자」「장미의 찬미」「이야기의 마법」 보통 모드를 클리어하면 새로운 키오링 「회무진용」「장미의 승리」「중하의 꿈」이 추가로 해금됩니다. 업데이트 전에 위 스토리 보통 모드를 완료한 수호자님께는 해당 키오링을 보상으로 지급하겠습니다. 확인해 주세요."
