  },
  Mail_44831_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_44836_Desc = {
    Text = "존경하는 수호자님:\n        V1.3.0 업데이트에서 우리는 「환몽 심잠」 매주 시험 1승, 3승에 대한 보상을 추가했습니다: 「대리 증명서」 ×1. 업데이트 이전에 해당 보상을 수령한 수호자님께는 해당 수량의 「대리 증명서」를 보충 지급하겠습니다. 확인해 주시기 바랍니다."
  },
  Mail_44836_Name = {
