  },
  Mail_44836_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_44837_Desc = {
    Text = "경건한 창백한 사자님: \n\n오늘 아이들이 꽃다발과 과자를 가져왔습니다. 그제야 제가 홍적력법이 시작되기 백여 년 전 오늘, 아버지 신의 은혜를 받아 이 세상에 태어났다는 것을 기억해냈습니다. 얼마나 오래된 일인지, 어린 시절의 기억은 이미 희미해졌지만, 본다사 교회 안에서 향을 피우던 냄새만은 아직도 제 머릿속에서 떠나지 않습니다. 지금도 교회는 있지만, 향의 레시피는 그때와 같지 않을 것입니다. \n\n죄송합니다, 이런 감상적인 말은 제가 당신에게 편지를 쓰는 목적이 아닙니다. 아이들이 가져온 과자를 가지고 차 시간을 준비했습니다. 당신이 함께 해주기를 바랍니다. 제 생일을 축하하기 위해서가 아니라, 생명이 존재하는 매일을 축하하기 위해서입니다. 생명이 존재하는 매일을 기뻐합시다. \n\n당신의 생일은 언제인가요? 한 잔의 차 후에 꼭 말씀해 주세요. \n\n\n\n살바도르"
  },
  Mail_44837_Name = {
    Text = "창백한 전령..."
  },
  Mail_44837_Sender = {
    Text = "살바도르"
  },
  Mail_44843_Desc = {
    Text = "존경하는 비밀 수호자님께:\n        V1.3.0 업데이트에서 「핵심 과제」의 특전인 「환몽 심잠」 및 「상위 대국(beta)」에서 비밀 수호자 경험치치 2배 획득 혜택이 삭제되었습니다. 이에 대한 사과의 의미로, 이번 「핵심 과제」를 구매하신 비밀 수호자님께 매일 「비밀 수호자 경험치치」× 240의 보상을 이번 학기 과제 종료 시까지 지급해 드립니다. 확인 부탁드립니다."
  },
