  Mail_47308_Desc = {
    Text = "수호자 님, 안녕하세요.\n어제 환몽 심잠에서 수호자 님께서 최고 난이도 「{s1}」을(를) 완료하셨습니다.\n어제 페이즈 체스에서 수호자 님께서 「{s2}」 칭호를 획득하셨으며, 승리 횟수도 기록되었습니다.\n위 도전 성적을 종합하여 수호자 님께서 받으실타래 추가 보상은 아래와 같습니다. 반드시 확인해 주세요."
