  },
  Mail_48005_Desc = {
    Text = "사랑하는 수호자님:\n\n무례하게 방해드려 죄송합니다. 제 형편없는 필적이 당신의 기분을 망치지 않기를 바랍니다. 저는 글쓰기에 서툴러서……\n이 편지를 쓰는 이유는 제 생일이 다가온 것 같다는 것을 알려드리기 위해서입니다. 이를 위해 작은 쿠키를 몇 개 만들었습니다. 당신도 한 번 맛보셨으면 좋겠습니다.\n솔직히 말하면, 이 날짜가 정확한지 확신할 수 없습니다. 융식에 감염된 후, 저의 존재를 나타내는 흔적들이 점점 사라지고 있습니다. 돌 양반님은 저에게 물었습니다. 깨어있는 상태로 자신이 모두에게 잊혀지는 것을 보는 것이 어떤 느낌인지요?\n그것은 설명하기 어렵습니다… 마치 완전한 어둠 속에서 빛나는 강물 가장자리에 서 있는 것 같습니다. 사람들은 강 건너편에서 서로 이야기하고 각자 바쁘게 움직이며, 제 앞을 지나쳐 갑니다. 저는 그들을 볼 수만 있을 뿐, 한 점도 소리를 낼 수는 없습니다.\n이는 매우 고독한 느낌입니다. 다행히도, 그 사람들 중에는 당신이 포함되어 있지 않습니다.\n적어도 당신은 제 스토리를 기억해 주고 계시니까요, 그렇지 않나요?\n\n덧붙여, 열두 개의 작은 쿠키를 이 편지와 함께 보내드립니다.\n\n메이슨"
  },
  Mail_48005_Name = {
    Text = "방해해서 미안해..."
  },
  Mail_48145_Desc = {
    Text = "존경하는 수호자님:\n“다중 치유” 이벤트가 종료되었습니다. 수호자님의 남은 활동 통화 “기억 퍼즐”을 “인격 분석” 무제한 교환 비율로 회수하겠습니다. 수호자님께서는 확인해 주시기 바랍니다."
  },
