  },
  Mail_48914_Desc = {
    Text = "존경하는 수호자: \n        《망각의 전야》에 대한 귀하의 지원과 인식에 감사드립니다. 수호자가 미사그 대학에서 더 나은 게임 경험을 할 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기를 정중히 요청합니다. 귀하의 협조에 감사드리며, 설문지를 완료하시면 「은심」× 200을 보상으로 준비했습니다. 설문 마감 시간은 10월 28일 9:00이며, 제때 작성해 주시기 바랍니다. \n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 의견을 진지하게 듣고 있으며, 귀하의 피드백이 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다! \n        ——은열쇠가 앞길을 밝히기를."
  },
  Mail_48914_Name = {
    Text = "버전 이용 조사 설문 V1.6.3"
  },
  Mail_48914_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_48915_Desc = {
    Text = "존경하는 수호자:\n        “망각의 전야”에 대한 지원과 인식에 감사드립니다. 수호자가 미사그 대학에서 더욱 좋은 게임 경험을 할 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기 바랍니다. 협조해 주신 것에 대한 감사의 의미로, “은심” × 200을 보상으로 준비하였습니다. 설문지를 완료하면 수령하실타래 수 있습니다. 설문 마감 시간은 9월 30일 9:00이며, 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성]>\n        우리는 모든 수호자의 의견을 소중히 듣겠습니다. 귀하의 피드백은 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다!\n        — 은열쇠가 앞길을 밝히기를."
  },
  Mail_48915_Name = {
    Text = "버전 사용자 경험 조사 설문 V1.6.1"
  },
  Mail_48915_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_49931_Desc = {
    Text = "존경하는 수호자님:\n“욕망의 파도” 이벤트가 종료되었습니다. 수호자님이 보유한 “풍성한 종자핵”을 각각 “장미 금권”× 20으로 교환해 드렸으니, 확인해 주시기 바랍니다."
  },
  Mail_49931_Name = {
    Text = "풍성한 종자핵 회수"
  },
  Mail_49931_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_50344_Desc = {
    Text = "어린 묘목아:\n\n바람이 네 향기를 실타래어왔어, 처음 만났을 때보다 더 달콤한 향이 나는구나.\n너는 나의 사랑 속에서 자라, 나의 사랑으로 무르익었어……마치 벌과 꿀처럼.\n오늘은 특별한 날이야, 나를 만나러 와줄 수 있겠니?\n네가 원하는 대로 얌전히 오랫동안 기다렸잖아……이제 슬슬 보상을 줘야 하지 않겠니, 그렇지?\n\n타이이스"
  },
  Mail_50344_Name = {
    Text = "꿀처럼 달콤한…"
  },
  Mail_50344_Sender = {Text = "타이스"},
  Mail_51376_Desc = {
    Text = "존경하는 수호자님:\n“이야기의 마법” 이벤트가 종료되었습니다. 수호자님의 남은 “유영하는 영감”을 각각 “장미 금권”× 60으로 교환해 드렸으니, 확인해 주시기 바랍니다."
  },
  Mail_51376_Name = {
    Text = "유영하는 영감 회수"
  },
  Mail_51376_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_51777_Desc = {
    Text = "존경하는 수호자:\n“이야기의 마법: Rerun”이벤트은 종료됨, 남아 있는 “유영하는 영감”을 개당 “장미 금권” × 25의 비율로 전환해 드리오니, 수호자께서는 확인해 주시기 바랍니다."
  },
  Mail_51777_Name = {
    Text = "유영하는 영감 회수"
  },
  Mail_51777_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_53149_Desc = {
    Text = "이미 오래전에 결정했습니다. 나의 남은 생을 매일 그분께 바치기로 했습니다……제 어리석은 행동에 대한 속죄로 삼겠습니다. \n얕고 하찮은 존재의 “생일” 따위는 언급할 가치도 없고 기억할 필요도 없습니다. \n오늘은 과거나 미래의 어느 날과 다를 것이 없으며, 저는 변함없이 예배당으로 전향하겠습니다. \n하지만, 당신께서 오늘 제가 예배당을 떠나 미사그의 손님으로 있게 하고자 한다면, 주인의 뜻을 거스르지 않겠습니다. \n또한, 제 기도를 증언하고자 하신다면 언제든 환영합니다……온 마음으로 두려움과 감사를 담아, 깊이 환영드립니다. \n\n미리암"
  },
  Mail_53149_Name = {
    Text = "수행의 하루..."
  },
  Mail_53149_Sender = {Text = "미리암"},
  Mail_53151_Desc = {
    Text = "존경하는 수호자님:\n“심연의 제사” 이벤트가 종료되었습니다. 수호자님의 남은 “사제의 눈물”, “사제의 피”와 “사자지수”를 100개당 “장미 금권”× 2500으로 교환하였으니, 수호자님께서는 확인 후 수령해 주시기 바랍니다."
  },
  Mail_53151_Name = {
