  },
  Mail_53153_Desc = {
    Text = "존경하는 수호자님:\n“타오르는 군연” 이벤트가 종료되었습니다. 수호자님의 남은 “원생 경골”, “원엽석” 및 “나선 유적”을 각각 80개당 “천면인장”× 1로 교환하였으니, 수령해 주시기 바랍니다."
