  },
  Mail_53869_Desc = {
    Text = "존경하는 수호자님:\n“장미 책과 함께” 이벤트가 종료되었습니다. 현재 수호자님께 남은 “통령조의 부채”를 각 1개당 “장미 금권”× 50의 비율로 변환하여 드리니, 확인 부탁드립니다."
  },
  Mail_53869_Name = {
    Text = "통령조의 부채 회수"
  },
  Mail_53869_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_54803_Desc = {
    Text = "존경하는 수호자:\n        V1.5.1 업데이트에서 「성장 기록」 수호자 레벨 21-80의 「은심」 보상을 증가시켰으며, 「영역 숙련」Ⅰ~Ⅴ 단계의 임무 완료 시 「조사 배지」× 1000의 보상을 추가했습니다. 업데이트 전 이미 위 보상을 받은 수호자에게는 해당 「은심」 또는 「조사 배지」 보상을 보충해 드립니다. 확인 바랍니다."
  },
  Mail_54803_Name = {
    Text = "V1.5.1 매뉴얼 보상 추가"
  },
  Mail_54803_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_55168_Desc = {
    Text = "존경하는 수호자님:\n“봄이 시들기 전에” 이벤트가 종료되었습니다. 수호자님의 남은 “기쁜 시”, “우울한 시문”과 “유감의 시문”을 200개당 “장미 금권”× 5000으로 교환하였으니, 수호자께서 확인해 주세요."
  },
  Mail_55168_Name = {
    Text = "시문 회수"
  },
  Mail_55168_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_56101_Desc = {
    Text = "수호자%sirormadam%:\n\n오늘 새벽, 한 송이 장미가 초봄의 새소리 속에서 활짝 피었습니다.\n그것은 원래 봄의 꽃봉오리여야 했지만, 성 발렌틴 날, 제 생일에, 잘못된 계절에 피어났습니다.\n저는 서대를 회상했습니다. 매년 생일마다 서대의 거리는 항상 북적였습니다. 저는 꽃이 피는 소리를 들었고, 사람들의 얼굴을 붉히게 만드는 다정한 말들을 들었습니다. 하지만 저는 오랫동안 그것들을 만질 기회가 없었습니다……, 오늘에 이르러서야.\n수호자님, 우연을 믿으십니까? 저는 우연이 하나의 언어라고 생각합니다. 그리고 장미는 하나의 수사법입니다. 오늘, 미사그의 화려한 정원에서 이 장미는 피어나고, 그 꽃잎들은 아름답게 펼쳐져 마치 마음을 사로잡는 시처럼 보입니다.\n그래서, 오늘, 수호자님…… 저와 함께 이 장미가 피어나는 모습을 보시겠습니까?\n저와 꽃 모두 당신의 방문을 기다리고 있습니다.\n\n오를라"
  },
  Mail_56101_Name = {
    Text = "봄에 피어나는 장미 한 송이…"
  },
  Mail_56101_Sender = {Text = "오를라"},
  Mail_57328_Desc = {
    Text = "존경하는 수호자님:\n“별들이 제자리에 있습니다” 이벤트가 종료되었습니다. 수호자님의 남은 “무식한 배아”, “무욕의 배아”와 “무욕의 배아”를 각각 “장미 금권”× 40으로 교환하였으니, 수호자께서 확인해 주시기 바랍니다."
  },
  Mail_57328_Name = {
    Text = "배아 회수"
  },
  Mail_57328_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_57414_Desc = {
    Text = "존경하는 수호자님:\n“명탐정 수첩” 이벤트가 종료되었습니다. 수호자님의 남은 “결승 칩”을 각각 “장미 금권”× 40으로 교환하였으니, 확인 부탁드립니다."
  },
  Mail_57414_Name = {Text = "칩 회수"},
  Mail_57414_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_58253_Desc = {
    Text = "존경하는 수호자님:\n“영혼의 목자·Rerun” 이벤트가 종료됨에 따라, 수호자님이 남은 “의미 있는 판매권”을 200개당 “장미 금권”× 5000으로 교환해 드리오니, 수령 여부를 확인해 주시기 바랍니다."
  },
  Mail_58253_Name = {
    Text = "의미 있는 판매권 회수"
  },
  Mail_58253_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_58690_Desc = {
    Text = "존경하는 수호자님:\n“무형의 교향곡” 이벤트가 종료되었습니다. 수호자님의 남은 “높은 악장”을 각각 “장미 금권”× 40으로 교환하였으니, 수호자님께서 확인해 주시기 바랍니다."
