  Mail_58690_Name = {
    Text = "높은 악장 회수"
  },
  Mail_58690_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_61154_Desc = {
    Text = "존경하는 수호자님:\n“타오르는 군연·Rerun” 이벤트가 종료됨에 따라 수호자님의 남은 “원생 경골”, “원엽석” 및 “나선 유적”을 각각 “장미 금권”× 40으로 교환하였으니, 수호자님께서는 확인해 주시기 바랍니다."
  },
  Mail_61154_Name = {
    Text = "타오르는 군연 통화 회수"
  },
  Mail_61154_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_61155_Desc = {
    Text = "존경하는 수호자님:\n“다중 치유·Rerun” 리메이크 이벤트가 종료되었습니다. 수호자님께서 남은 활동 통화 “기억 퍼즐”을 각각 “장미 금권”× 40으로 교환하여 회수할 예정이니, 수호자님은 꼭 확인하시기 바랍니다."
  },
  Mail_61155_Name = {
    Text = "기억 퍼즐 회수"
  },
  Mail_61155_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_62392_Desc = {
    Text = "수호자: \n\n제 연주는 왕좌 앞에서 봉사하였으며, 수많은 사람들에게 동경의 대상이 되었습니다. 그러나 그 찬사는 저에게 아무 가치도 없습니다. 제가 추구하는 것은 음악의 극치일 뿐입니다. \n화려하고 성대한 장소에서 사람들에게 감상당하는 것보다, 무인의 숲에서 혼자 연주하는 것이 더 편안합니다. \n원래 저는 제 연습을 다른 사람이 듣는 것을 좋아하지 않았습니다. 그것들은 단지 완벽에 이르기 위한 초안일 뿐, 무의미한 폐기물에 불과했습니다. \n그러나 당신을 알게 된 이후로, 제 모든 음악이 의미를 가지게 되었습니다. \n당신은 저에게 가장 위대하고 숭고한 음악을 선사해주셨습니다. 저는 미로에서 벗어날 수 있었고, 당신 자신은 그것을 모르고 있을지라도…… \n오늘은 제 생일입니다. 이미 잊혀졌던 날이었지만, 이제는 제 새로운 삶을 기념하고, 제게 새로운 삶을 선사해준 사람을 기념하고 싶습니다. \n마침 최근에 새로운 곡들을 작곡했습니다. 당신을 초대하여 감상해보시기를 바랍니다. 늦은 초대를 용서해 주십시오. 제 신분은 아직 미사그 동료들 앞에 나타나기에 적합하지 않아, 지평선이 해질녘의 모든 여운을 수렴할 때까지 기다렸다가 이 초대장을 전합니다. \n오늘 밤 학교 뒤편의 숲에서 특별한 콘서트를 열 계획입니다. 관객석은 하나뿐입니다. \n당신의 방문을 기다리겠습니다. \n\n함린"
  },
  Mail_62392_Name = {
    Text = "비밀 콘서트…"
  },
  Mail_62392_Sender = {Text = "하멜른"},
  Mail_65350_Desc = {
    Text = "존경하는 수호자님:\n“눈이 녹을 때” 이벤트가 종료되었습니다. 수호자님께서 남은 활동 통화 “냉동 꽃봉오리”, “은상꽃봉오리”와 “일광화포”를 각각 “장미 금권”× 40으로 교환하여 회수하였으니, 확인 후 수령해 주시기 바랍니다."
  },
  Mail_65350_Name = {
    Text = "꽃봉오리 회수"
  },
  Mail_65350_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_65441_Desc = {
    Text = "존경하는 수호자님:\n“심연의 제사·Rerun” 이벤트가 종료되었습니다. 수호자님의 남은 “사제의 눈물”, “사제의 피” 및 “사자지수”를 각각 “장미 금권”× 40으로 교환하였으니, 수호자님께서는 확인해 주시기 바랍니다."
  },
  Mail_65441_Name = {
    Text = "심연의 제사 이벤트 통화 회수"
  },
  Mail_65441_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_65442_Desc = {
    Text = "존경하는 수호자님:\n“만상문” 이벤트가 종료되었습니다. 수호자님께서 남은 활동 통화 “종말 포인터”를 각각 “장미 금권”× 40으로 교환하여 회수하였으니, 확인 후 수령해 주시기 바랍니다."
  },
  Mail_65442_Name = {
    Text = "종말 포인터 회수"
  },
  Mail_65442_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_67147_Desc = {
    Text = "수호자: \n\n    우주의 차원은 나에게 유일하지 않으며, 궁극의 문 안에서는 수많은 세계와 무한한 존재를 볼 수 있습니다. 그곳은 모든 상상과 수학적 논리 너머에 있으며, 자연스럽게 「탄생의 날」의 날짜를 확인할 수 없습니다. \n    그러니, 우리 처음 만난 순간을 그때로 정합시다. 당신이 있는 시간 연속체의 척도에서 오늘 내 전용 의식이 열릴 것입니다. 내가 소망한 것을 이룰 것입니다. \n    그렇다면, 은열쇠의 문을 건너 제 곁으로 오세요. 나는 당신에게…궁극의 본원에 대한, 우주에 속한 지식을 가르쳐 줄 것입니다. 오늘 밤, 억만의 빛나는 체가 우리 두 사람을 위해 빛날 것입니다. \n    나는 궁극의 문에서 당신을 기다리겠습니다. \n\n타비"
  },
  Mail_67147_Name = {
    Text = "은빛 문을 넘어서..."
  },
  Mail_67147_Sender = {Text = "타비"},
  Mail_67933_Desc = {
    Text = "나는 당신이 순간적으로 망설이는 것을 느꼈습니다——그 절대적인 조물주를, 직시하는 것조차 거의 망상에 가깝건만, 어떻게 해서 조금이라도 상처를 입힐 수 있단 말입니까? 그러나 당신은 해냈습니다. \n또 한 줄기 시선이 무너졌고, 견고한 갑옷은 차례로 떨어지는 파편들에 의해 긁힌 자국과 틈을 남겼습니다. \n%player%, 무적한 것은 오직 당신의 굳건한 의지뿐입니다."
  },
  Mail_67933_Name = {
    Text = "혼란스러움 속에서 길을 분명히 보다"
  },
  Mail_67933_Sender = {
    Text = "알리스테어"
  },
  Mail_67934_Desc = {
    Text = "네 다리가 떨리고 있어, %player%. 거의 서 있을 힘이 남아있지 않아. 공포가 너를 사로잡아 머릿속이 하얘지고 숨을 제대로 쉴 수 없지만…… 그래도 너는 앞으로 은열쇠를 들어 올렸다. \n인간의 모든 아름다운 덕목 중에서 용기는 가장 고귀한 것이다. 천재와 맹수 앞에서 우리는 돌도끼와 창을 들었고, 이제 신성 앞에서도 너는 여전히 그렇게 하고 있다. \n인류 문명은 용기로 세워졌으며, 용기로 인해 계속 번성할 것이다."
  },
  Mail_67934_Name = {
    Text = "용기의 찬가, 전율 속에서 울려 퍼진다"
  },
  Mail_67934_Sender = {
    Text = "알리스테어"
  },
  Mail_67935_Desc = {
    Text = "우리는 이 세계에 대해 이야기한 적이 있어. 네가 말했지, 이 세계를 좋아하지 않는다고. 여기는 이익, 음모, 기만, 살육으로 가득 차 있으며, 융식과 신성 없이도 이미 천공백창하고 위태롭다고. 아쿠트에서 깨어난 후, 네 단시간한 기억 속에서 너는 융식보다 더 무질서하고 더 끔찍한 인간의 마음을 수많이 보았을 거야. \n그런데 조물주가 그의 날카로운 칼날을 들어올렸을 때, 너는 여전히 이 세계 앞에 서서 방어했어. 소멸은 신성의 의지였지만, 너는 그것을 거절했어. \n나는 이해해, %player%. 수호자 중 누구도 이 세계를 증오하지 않으며, 누구도 이 세계를 진정으로 사랑하지 않는 사람은 없어. 왜냐하면 그 더러움 속에서 우리는 은심처럼 빛나는 광휘를 본 적이 있기 때문이야. \n수호자의 임무는 그런 미약한 광휘를 지켜 영원히 존재하게 하는 것이다."
  },
  Mail_67935_Name = {
    Text = "인류의 정신은 영겁에 빛날 것입니다"
  },
  Mail_67935_Sender = {
    Text = "알리스테어"
  },
  Mail_67936_Desc = {
    Text = "처음으로 융식을 보았고, 처음으로 융식의 진실타래을 마주했으며, 처음으로 신성의 소리를 느꼈습니다…… 제 긴 인생에서 수많은 우울한 순간들을 겪었습니다. 제가 무엇을 할 수 있는지, 이 모든 노력과 희생의 의미가 무엇인지 모릅니다. ——하지만 그것들은 당신이 직면한 것과 비교할 수 없습니다. \n 인간은 이렇게, 한 번 한 번의 우울 속에서 다시 일어서 앞으로 나아갑니다. \n 길의 끝엔 심연이 있을지라도, 항상 누군가는 그것을 보러 가고 싶어할 것입니다."
  },
  Mail_67936_Name = {
    Text = "우울, 그리고 신생"
  },
  Mail_67936_Sender = {
    Text = "알리스테어"
  },
  Mail_67937_Desc = {
    Text = "차원의 경계가 열리고, 이제야 비로소 다시 당신과 연락할 수 있게 되었습니다.\n당신이 경험하는 것에 비해, 이 차원의 시선은 매우 약합니다. 아마도 이 차원에 당신이 존재하지 않기 때문일 것입니다. 거의 모든 것을 희생한 끝에, 나는 그를 당신 대신 처리했습니다.\n당신이 마주하고 있는 것이 무엇인지 도저히 상상할 수 없습니다. 하지만 어떠한 경우에도, 소멸의 의지를 함께 맞서 싸우겠습니다. 이것이 모든 미사그의 서약입니다.\n다시 당신과 함께할 수 있어 기쁩니다.\n은열쇠가 앞길을 밝혀주길 바랍니다."
  },
  Mail_67937_Name = {
    Text = "함께 싸우자, 다시 한 번"
  },
  Mail_67937_Sender = {
    Text = "미지의 발신자"
  },
  Mail_67938_Desc = {
    Text = "광기, 한가롭고 심지어 아름다운 단어입니다. \n혼돈의 우주에서 혼돈의 문명이 탄생했습니다. 혼돈이 이 세상의 진실타래입니다. 혼돈에 순응하고, 광기를 즐기는 것은 얼마나 한가로운 일인지 모릅니다. 그에 비해 깨어있고 저항하는 것은 매우 어렵습니다. 당신은 모든 기쁨과 생명을 희생하여, 도달할 수 없는 답을 찾아야 합니다. \n하지만 당신은 여전히 깨어있음을 선택했습니다, %player%. 우리는 노예가 되어 태어난 것이 아니기 때문입니다. \n당신은 %player%——그분의 유물, 그분의 파편이지만, 맹목적이고 어리석은 노예가 되길 거부했습니다. 당신은 그분과 맞서, 그분의 시선을 이겨내고, 이 완벽하지 않고 한가롭지 않은 세상을 지키는 것을 선택했습니다. \n이 선택 속에서, 당신은 영원한 자유를 얻었습니다."
  },
  Mail_67938_Name = {
    Text = "당신은 맹목적이고 어리석은 노예가 되는 것을 결코 원하지 않았습니다"
  },
  Mail_67938_Sender = {
    Text = "알리스테어"
  },
  Mail_67939_Desc = {
    Text = "나는 한 줄기 시선의 붕괴를 느꼈습니다. 나는 당신의 절박한 고통을 느꼈습니다. \n이것은 수호자라는 칭호에 새겨진 책임입니다. 당신이 선택한 길은 내가 걸어온 길보다 훨씬 더 어렵습니다. 모든 사람이 신성과 마주할 용기가 있는 것은 아닙니다. 당신의 용기는 저에게 위안과 존경을 불러일으킵니다. \n조물주의 힘이 얼마나 큰 고통을 줄지는 상상할 수 없습니다. 내가 느끼는 것은 당신이 겪고 있는 것의 극히 일부에 불과합니다. 나는 블랙풀에 갇힌 무용지물이며, %player%, 나는 당신과 조물주의 대결에 힘을 보태지 못합니다. 단지 제 감각을 통해 당신과 항상 연결되어 있을 뿐입니다. 이것이 제가 맞이할 마지막이자 가장 중요한 사명입니다. \n이 고독한 길에서, 당신이 그것을 알든 모르든 미사그는 항상 당신 곁에 있을 것입니다."
  },
  Mail_67939_Name = {
    Text = "슬픔이 당신을 굴복시키지 않을 것입니다"
  },
  Mail_67939_Sender = {
    Text = "알리스테어"
  },
  Mail_67940_Desc = {
    Text = "나는 최고의 의지의 속삭임을 들었다——거대한 문명, 인간의 슬픔과 기쁨, 당신을 둘러싸고 멀리 떨어져 있는 수많은 사람들, 모든 것이 결코 존재하지 않았다. \n블랙풀의 수많은 낮과 밤 동안, 이 광경은 나에게 공포를 안겨주었다. 나무는 땅에 뿌리를 내리고 위로 자라 태양을 향해 간다——기억, 기억은 우리의 토양이며, 우리가 자라고 설 수 있으며 마침내 회귀할 곳이다. 나는 토양을 잃고 공허 속에서 부유하는 것을 두려워했다. 시작도 끝도 없는 상태를. \n감사합니다, %player%. 나는 위대한 대결을 증언했다고 생각합니다. 이것은 인간과 신성의 전투입니다. 이것은 수호와 파괴의 싸움입니다. \n이는 기억과 망각의 싸움입니다. \n당신은 해냈습니다, %player%. 당신은 아무도 상상하지 못한 일을 이루어냈습니다. 당신은 기억으로부터 힘을 획득했습니다. 그리고 그 힘으로 기억을 위해 싸웠습니다. \n당신은 이 영원한 토양에서 당신만의 태양을 찾았습니다."
  },
  Mail_67940_Name = {
    Text = "기억하기 위해 싸우자"
  },
  Mail_67940_Sender = {
    Text = "알리스테어"
  },
  Mail_68825_Desc = {
    Text = "존경하는 수호자님:\n“신왕 부활” 이벤트가 종료되었습니다. 수호자님의 남은 활동 통화 “피곤한 감정”, “비수한 생각” 및 “기쁨과 생각”을 각각 “장미 금권”× 40으로 교환하였으니, 수령 여부를 확인해 주시기 바랍니다."
  },
  Mail_68825_Name = {
    Text = "신왕 부활 화폐 회수"
  },
  Mail_68825_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_68826_Desc = {
    Text = "존경하는 수호자님:\n“욕망의 파도·Rerun” 이벤트가 종료되었습니다. 수호자님의 남은 “풍성한 종자핵”을 각각 “장미 금권”× 40으로 교환하였으니, 확인해 주시기 바랍니다."
  },
  Mail_68826_Name = {
    Text = "풍성한 종자핵 회수"
  },
  Mail_68826_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_68898_Desc = {
    Text = "가장 가장 사랑하는 주인님께:\n\n만능 하녀로서 가렌은 어른들이 중요하게 생각하는 많은 날들을 기억할 수 있습니다. 상류층의 파티 날, 생일, 기념일부터 반려동물을 처음 구입한 날까지 절대 틀리지 않습니다. 하지만 가렌 자신에게는 특별히 기념할 날이 이날뿐입니다. \n오래전, 가렌은 궁전에서 시녀로 일하고 있을 때, 처음으로 요리사에게 귀족들이 남긴 디저트를 생일 케이크로 얻으려고 했지만 크게 꾸중을 들었습니다. 그 요리사는 케이크를 제 얼굴에 던졌습니다. 그때 저는 케이크가 이렇게 맛있는 것이라는 것을 알게 되었고, 매년 제 생일마다 케이크를 먹을 수 있는 좋은 주인을 찾아야겠다고 결심했습니다. \n지금 저는 매우 우아하고 대방한 소렐 부인과 매우 친절하신 주인님을 만났습니다. 옛날의 소원은 이미 이루어졌습니다! 하지만 사람은 점점 더 욕심이 생기죠……아니, 발전하죠. 지금 제 소원은 매년 생일 때마다 주인님 곁에 있을 수 있는 것이고, 또한 매년 빛나는 선물이 있으면 좋겠습니다. \n이렇게 많이 말씀드렸는데, 주인님께서 준비해 주실타래 거예요, 그렇죠? 그렇죠? \n\n항상 겸손한 하녀\n가렌"
  },
  Mail_68898_Name = {
    Text = "매년 이렇게…"
  },
  Mail_68898_Sender = {Text = "카렌"},
  Mail_68899_Desc = {
    Text = "나무 새싹:\n\n당신이 계속 성장하는 모습을 보면서, 당신을 선택하고 도와준 것이 내가 한 가장 올바른 결정이라는 확신이 더욱 커졌습니다. \n나는 수확의 기쁨을 느꼈고, 모든 신뢰와 사랑의 물주기가 나에게 달콤한 보상을 주었습니다. 당신은 저에게 희망과 미래를 주었습니다. \n지금 저는 번식에 대한 집착을 버리고, 번식 외의 사랑의 열매를 즐길 수 있습니다. \n이 세상은 더 이상 아란 여왕을 필요로 하지 않지만, 평범한 여자가 연인의 동반을 바라는 생일 소원을 받아들일 수 있을 것입니다. \n가장 흔한 연인처럼 함께 식재료를 사러 가고, 함께 요리를 하는 것, 그리고 제가 경험하지 못한 많은 일들을 함께 할 수 있기를 바랍니다. 그렇다면 사랑하는 당신이 저를 따뜻하고 조용한 생일을 보내도록 안내해 주실타래 수 있겠습니까? \n\n테이스"
  },
  Mail_68899_Name = {
    Text = "평범한 생활…"
  },
  Mail_68899_Sender = {Text = "타이스"},
  Mail_68900_Desc = {
    Text = "수호자: \n\n카시아 님은 세상에서 가장 뛰어난 연기의 대가로, 어떤 표정이든 완벽하게 흉내 낼 수 있지만, 인간의 감정이라는 것은 어떻게 해도 이해할 수 없는 세계적인 퍼즐입니다. \n저는 많은 사람들에게 물어보았지만, 그들은 감정의 원리를 설명하지 못했습니다. 돌에게 물어보았을 때, 그녀는 세상에 심리학이라는 학문이 있다고 말해주었고, 비록 공감하지 못하더라도 심리학을 배우면 모든 감정의 이론을 이해할 수 있다고 하더군요. \n이건 정말, 정말 매력적이지 않나요? 카시아를 오랫동안 괴롭혀온 의혹이 마침내 풀릴까요? \n그건 그렇고, 이번 주 심리학 수업에 당신의 반에 들어가기로 했습니다. 카시아가 당신 옆자리에 앉기로 결정했으니, 제가 놓친 부분은 잘 가르쳐주세요, 짝꿍~ \n아, 맞다. 참고로 오늘은 제 생일이에요. 여기서 기뻐해야 하고, 당신도 기뻐해야 합니다, 그렇죠? \n만약 매우 기쁜 일이라면, 학교에서 크게 축제처럼 즐겨봅시다. 제가 학교를 꿈처럼 아름답게 만들어줄게요! \n\n카시아"
  },
  Mail_68900_Name = {
    Text = "심리학…"
  },
  Mail_68900_Sender = {Text = "카시아"},
  Mail_68901_Desc = {
    Text = "경건한 창백한 사자님: \n\n지난 한 해 동안 당신의 도움과 관심에 감사드립니다. 당신이 타인을 대하는 진심은 마치 아버지 신이 가르친 것처럼 고상합니다. 당신과 함께하는 기회가 자주 없었지만, 매번 당신을 만날 때마다 오랜 친구를 만난 듯한 느낌을 받아 마음이 편안해집니다. \n생일이라는 날은 특별하지 않지만, 친구와 만나는 이유로는 기대감을 갖게 합니다. 당신 말고는 이날을 함께 보낼 사람이 아무도 떠오르지 않습니다. \n만약 당신이 관심이 있다면, 최근에 시작한 취미인 낚시를 체험해보는 것은 어떨까요? 물론 요리나 먹기 위해서가 아니라, 운명이 주는 신비로운 선물을 조용히 기다리는 과정을 즐기기 위함입니다. 이런 평화로운 감정을 당신과 나누고 싶습니다. 자연 속으로 나가 호수 옆에서 안온하게 앉아 있으면서요. \n오랜 친구와 두 개의 낚싯대, 이보다 더 좋은 하루는 없을 것입니다. \n\n살바도르"
  },
  Mail_68901_Name = {
    Text = "낚시라는 새로운 취미…"
  },
  Mail_68901_Sender = {
    Text = "살바도르"
  },
  Mail_68902_Desc = {
    Text = "주인님:\n\n올해 생일에 에이지스와 젠킨이 오레타를 닮은 유리 풍경종을 선물해주었어요.\n그걸 방 창문에 걸어두었는데, 바람이 불면 예쁜 소리를 내서 어머니가 저를 안고 창가에서 이야기를 해주시던 때를 떠올리게 해요.\n걱정하지 마세요, 주인님. 매일 어머니를 그리워하지만, 주인님과 모두가 함께 있어줘서 리리는 외롭지 않아요.\n지금 리리는 스스로 스토리책을 읽는 법을 배웠어요. 매일 저녁 무렵 주황색 햇빛이 집으로 들어와 풍경종 위로 비춰, 이야기책 위에 흔들리는 물결무늬를 만들어 방을 따뜻하게 만드는 거예요.\n리리는 이런 시간에 멍하니 앉아서 석양 아래 구름과 풍경종을 보는 걸 정말 좋아해요. 정말 아름답고 아름답다고 느껴져요.\n오늘 주인님이 시간이 있으시다면, 리리와 함께 멍하니 앉아보시는 건 어떨까요?\n\n리리"
  },
  Mail_68902_Name = {
    Text = "유리 풍경…"
  },
  Mail_68902_Sender = {Text = "릴리"},
  Mail_68903_Desc = {
    Text = "소년: \n\n이 특별한 날은 그 인간을 기념하기 위해 정해졌지만, 할인일은 고객과 상인 모두에게 매우 매력적인 판매 방안이라는 것을 부정할 수 없습니다. \n지난 생일 때, 해소 상점의 거래 주문량은 평소 6개월 치에 가까운 판매량을 기록했습니다. 특히 제가 축하의 의미로 내놓은 특가 상품들은 전부 품절되었습니다. 미사그의 손님들이 제 사업을 너무나도 잘 챙겨주신 것인지, 아니면 신중하고 조심스러운 조사원들조차 할인의 유혹을 뿌리칠 수 없었던 것인지 궁금합니다. \n어쨌든, 상호 이익을 위한 즐거움을 계속하기 위해, 올해 제 생일 행사에서도 할인 행사를 진행할 예정입니다. 일 년에 단 한 번뿐이고 할인 폭이 크니 서둘러 주세요. 미사그에서 이 행사를 잘 홍보해 주시고, 기억하기 쉽게 이 날을 '쌍십일'이라고 불러주세요. \n덧붙여, 당신을 위해 몰래 재미있는 소품들을 조금 남겨두었습니다. 꼭 빨리 와서 저를 만나주세요. \n\n다프다일"
  },
  Mail_68903_Name = {
    Text = "할인 행사…"
  },
  Mail_68903_Sender = {Text = "다포딜"},
  Mail_68904_Desc = {
    Text = "운명의 큰 은혜를 받은 미사그 대학의 수호자, 현명하고 어진 덕을 지닌 주군께. \n만안하시길 빕니다! \n만약 모든 기사들의 평생 소원이 위대한 주군을 따르는 것이라면, 제 기사로서의 삶은 이미 후회 없이 충만합니다. \n저의 삶에는 행운뿐만 아니라 많은 불행과 비극, 그리고 장렬한 희생의 피가 있었습니다. 그래서 미사그의 많은 이들이 저를 동정해 왔다는 것을 잘 알고 있습니다. \n고통을 비교할 필요도 없이, 미사그에는 이미 너무나 많은 불행한 사람들이 있습니다. 이렇게 고통으로 가득 찬 세상에서, 수호하기 위해 피를 흘리는 것은 슬퍼할 일이 아닙니다. 오히려 과거나 현재, 저는 이를 영광스럽게 여기며 언제나 이 몸을 희생할 준비가 되어 있습니다. \n하지만 로탄 각하께서는 제가 매일 굳은 얼굴로 걱정하는 모습이 너무 지쳐 보인다며, 생일이라도 마음 편히 놀아보라고 하셨습니다. 그리고 젠킨을 불러 게임을 가르쳐 주라 하셨는데, 저에게 어린 시절을 되찾아 준다고 하셨습니다. \n부끄럽지만, 저는 어릴 때 훈련에 바빠서 놀 시간이 거의 없었습니다. 다섯 살짜리 아이들도 쉽게 배운다는 이 게임이 이렇게 어려울 줄은 몰랐습니다. 기사 도리 외에도 제가 배워야 할 것이 참 많음을 깨달았습니다. \n주군께서 오늘 여유가 있으시다면, 저희와 함께 즐기러 오실타래 수 있으신지요? 젠킨이 열 번 연속으로 이긴 후 벌써 지루해 하고 있습니다. 주군께서 오신다면 분명 멋진 한 판이 펼쳐질 것입니다. \n\n오지르"
  },
  Mail_68904_Name = {
    Text = "어려운 게임…"
  },
  Mail_68904_Sender = {Text = "오지에"},
  Mail_68905_Desc = {
    Text = "여보세요.\n\n그 달력 덕분에 올해는 분명히 존귀한 미로의 주인의 생일을 잊지 않았겠지. \n내 방에 들어와 선물을 바치고, 이날 하루 동안 나를 정성껏 모실타래 수 있게 허락할게. \n예를 들어, 양치질하고 세수하고, 옷을 갈아입고 식사를 하는 것, 그리고 방 청소와 침대 시트 교체 같은 일들, 너희들이 뭐라고 부르더라, 대청소! \n그래, 이 모든 대청소 일은 너에게 맡길 거야. 나는 이미 그 집안일에 지쳤어. 오늘은 어떤 일이 있어도 로마에서 보냈던 과거의 시간으로 돌아가, 손을 뻗기만 해도 옷이 입혀지고 밥을 차려주는 생활을 즐기고 싶어. \n오늘은 누구든 내게 조금이라도 일을 시키려고 하면 안 돼, 절대로! \n\n아그리파"
  },
  Mail_68905_Name = {
    Text = "과거로 돌아간다면…"
  },
  Mail_68905_Sender = {
    Text = "아그리파"
  },
  Mail_68906_Desc = {
    Text = "수호자: \n\n시간이 정말 빨리 흘러갔네요. 죽을 때까지 계속될 줄 알았던 그런 생활을 이제는 거의 기억나지 않아요. \n현재 양반님은 식당의 모든 작은 케이크를 속속들이 알고 있으며, 아무리 그 무능한 요리사들을 다그쳐도 새로운 요리는 만들어내지 못하죠. \n그래서 새해에는 제 미식 지도를 더 크고 더 멀리 확장할 계획입니다. 우선 작은 목표 하나를 정했어요: 렌티니언의 모든 케이크 가게를 섭렵하는 것입니다. \n줄 서서 기다리는 영광스러운 임무는 여전히 당신에게 맡길게요! 저의 신뢰를 얻었다고 너무 기뻐하지 말고, 감사한 마음으로 저 숙녀의 이름을 찬양하세요. \n다시 말하자면, 그 어리석은 요리사들은 그래도 약간의 진심은 있는 것 같아요. 그들이 수군대는 소리를 통해 엄청난 열 층짜리 케이크를 준비 중이라는 걸 알아차렸죠. \n창의성은 조금 뻔하지만, 이번 생일 파티에서는 좀 더 많은 사람을 초대할 수도 있을 것 같아요. 예를 들어, 올해 사귄 새로운 친구들처럼요. \n제가 미사그에서 처음 사귄 친구로서, 당신에게 케이크에 첫 번째 칼질을 할 특권을 허락합니다. \n\n머피"
  },
  Mail_68906_Name = {
    Text = "10단 케이크…"
  },
  Mail_68906_Sender = {Text = "머피"},
  Mail_68907_Desc = {
    Text = "사랑하는 수호자님:\n\n당신처럼 촉망받는 분이라면, 미사그의 신비로운 아카이브에서 이미 이 정보를 알고 계실타래 것입니다. 오늘은 “운 좋은 탐정”의 생명 중 기념할 만한 날입니다.\n태어나고, 첫 21점 게임에서 승리하며, 백 번째 경마에서 이기고, 첫 번째 밀실타래 살인 사건을 해결하고, 실타래패로 인해 죽음이 찾아오기까지—모든 것이 이 마법 같은 6월 6일에 일어났습니다.\n그러니 오늘 저와 함께 두 사람용 브리지 게임을 즐겨보는 것은 어떨까요? 이 날을 더욱 특별하게 만들어 보는 건 어떨지 생각해 봅니다.\n\n레이크"
  },
  Mail_68907_Name = {
    Text = "한 판 붙어볼까?"
  },
  Mail_68907_Sender = {Text = "라이커"},
  Mail_68908_Desc = {
    Text = "이 편지는 인사가 아니라 경고야—날 통제하려 들지 말고, 내게 족쇄를 채울 생각 마. \n나는 나만의 것이야. \n나를 닮은 그 녀석과 달리, 난 사람이나 세상에 대해 순진한 기대를 품지 않아. \n\n내 \"주인\"이 되겠다고 설치는 놈은 전부 죽일 거야. 반드시. \n\nH"
  },
  Mail_68908_Name = {
    Text = "나는 나의 것..."
  },
  Mail_68908_Sender = {
    Text = "혈쇄·히로"
  },
  Mail_68909_Desc = {
    Text = "수호자: \n\n아마도 제가 물에 대한 애정을 당신에게 이야기한 적이 있을 것입니다. 소란스러운 인간 세상과 비교했을 때, 물속 세계는 매우 고요하고 평온합니다. \n저는 수초와 산호 사이를 떠다니며 물고기 떼와 대화를 나눈 적도 있습니다. 수면으로부터 멀어질수록 물속은 더욱 어두워지고, 물결에 부드럽게 밀려 바닥에서 하늘을 올려다볼 때, 그 빛과 그림자가 만들어내는 환상적인 색감은 제 마음속 가장 아름다운 풍경입니다. \n이런 사실타래을 알고 계셨나요? 일부 해양 생물은 사람의 모습을 기억할 수 있습니다. 다시 방문했을 때, 이 \"친구들\"은 열정적으로 다가와 반겨줍니다. 예를 들어, 저는 영리한 작은 문어 한 마리와 연한 노란색의 물고기를 알고 있습니다. \n생일인 오늘, 저는 다시 물속 세상을 그리워합니다. 당신이 저와 함께 잠수해 주실타래지 알고 계셨나요? 진심으로 이 평온한 공간과 제 신비로운 친구들을 당신과 나누고 싶습니다. \n\n닝피아"
  },
  Mail_68909_Name = {
    Text = "물 속 세계…"
  },
  Mail_68909_Sender = {Text = "님피아"},
  Mail_68910_Desc = {
    Text = "수호자: \n\n당신이 미사그에 온 이후로, 나는 영아를 양육하듯 당신과 관련된 문제를 처리하는 데 익숙해졌습니다. 평소 당신의 반응을 보면, 당신의 약함은 기대 이상입니다. \n하지만 당신의 스승이자 첫 번째 보호자로서, 지난 일 년 동안 당신을 위해 문제를 해결하고 수습해야 할 일이 점점 줄어든 것이 기쁩니다. 입학 당시 당신의 정신이 텅 비어 있던 모습은 매우 절망적이었지만, 당신의 성장 속도는 확실타래히 재능과 노력이 결합된 결과라고 할 수 있습니다. \n축하합니다. 당신은 이제 합격한 수호자가 되었으며, 저의 기대를 저버리지 않았습니다. \n별다를 것 없는 제 생일에, 나는 이미 당신을 위해 성공한 수호자에게 어울리는 선물을 준비했습니다 — 알리스타가 사용했던 특수 훈련 방안입니다. 어떠세요? 기대되시나요? \n제가 왜 당신에게 선물을 준비했는지 질문하지 마세요. 실타래험실타래에 들어갈 수 없는 날에는 뭔가 일을 찾아야 하니까요. 그렇지 않나요. \n준비되면 훈련실타래로 저를 찾아오세요. \n\n돌"
  },
  Mail_68910_Name = {Text = "선물…"},
  Mail_68910_Sender = {Text = "돌"},
  Mail_68911_Desc = {
    Text = "수호자：\n\n무용수에게 1년은 겨우 수만 번의 회전과 수만 번의 점프일 뿐이다. 나에게 오랫동안 함께했던 오래된 발레화가 바뀐 것을 제외하면, 모든 것이 변하지 않은 듯이 보이고 모든 것이 다르게 느껴진다.\n예전의 외로움에 비해, 이 년 동안 나는 항상 충실타래한 관객 하나와 다소 서툰 춤 파트너가 있었다.\n너가 무용실타래에 앉아 있을 때마다, 나는 신체가 더욱 가벼워지는 것을 느꼈다. 마치 내 어린 시절 처음 무용을 배울 때처럼, 모르는 열정과 에너지가 가득했다.\n어쩌면 나는 내가 생각하는 것처럼 순수하고 고상하지 않을 수 있지만, 내 인생을 무용에 바치면서도, 나는 너의 주목을 받고, 너의 박수를 듣고 싶어한다.\n생일인 오늘 날씨가 매우 좋다. 나는 오늘 밤 별이 맑을 것이라고 예감하고 있다. 나의 가장 열정적인 관객이자, 나의 전속 무용 파트너여, 너는 나와 함께 아름다운 호수가 있는 숲으로 나아가, 달과 별을 위한 춤을 추겠는가？\n\n리즈"
  },
  Mail_68911_Name = {
    Text = "전용 댄스 파트너..."
  },
  Mail_68911_Sender = {Text = "리즈"},
  Mail_68912_Desc = {
    Text = "수호자: \n\n내 재생성의 날부터 미사그의 사람들이 나를 많이 도와주었다. 아마도 나는 아직 협력하는 느낌에 익숙해지지 않았을지라도, 적어도 너희들과 함께할 때는 등을 맡길 수 있다는 것을 느낄 수 있다. 이런 감정…… 괜찮다. \n내 인생 대부분은 데미지와 배반으로 가득 차 있었고, 나는 그것들을 물리치는 것이 전투의 의미라고 생각했다. 결국 내 삶에는 다른 것이 아무것도 남지 않았고, 내 시선은 복수에서 떠날 수 없게 되었다. \n지금 너희들의 발걸음을 따라가면서야 비로소 전투가 데미지와 보복 외에도 많은 의미를 가질 수 있다는 것을 발견했다. 로탄이 말했듯이, 전투는 단순히 전투일 수도 있다. \n나는 전투의 즐거움을 배웠고, 그 짜릿한 느낌을 즐기며, 순수하게 용맹한 전사가 되는 것을 즐긴다. \n만약 내 전투가 더 많은 것을 가져온다면, 나는 그 영광을 누릴 것이다. \n그리고 너, 지금이든 미래든, 나는 약속한다. 내 칼날은 결코 너를 향하지 않을 것이라고. \n\n시로"
  },
  Mail_68912_Name = {
    Text = "전투의 의미…"
  },
  Mail_68912_Sender = {Text = "히로"},
  Mail_68913_Desc = {
    Text = "친애하는 수호자:\n\n솔직히 말하면, 생일 소원 같은 것에 대해 특별한 생각이 많지는 않아요. 예전에 제가 아직 \"정상적\"이었을 때는, 먹고 입는 것과 제때 집세를 내고 젠킨을 잘 돌보는 것이 하루의 가장 큰 소원이었어요. 지금은 한 해 동안 안정되게 보낼 수 있고, 젠킨이 또 한 해 동안 장난칠 수 있다는 사실타래만으로도 충분히 만족스러워요.\n부끄럽지만, 젠킨 앞에서는 항상 누나처럼 그녀를 가르치며 행동하는데, 당신 앞에서는 늘 많은 문제를 일으키곤 해요. 심지어 어느 내가 문제를 일으켰는지도 기억하지 못할 정도예요.\n당신의 변함없는 온화함과 인내심은 저에게 따뜻함과 동시에 부끄러움을 줍니다. 아마도 이는 제가 인생에서 처음으로 이렇게 포용적인 태도로 저를 돌봐주는 사람을 만났기 때문일 거예요. 진심으로 영광스럽고 감사하게 느껴져요.\n올해는 모두를 위해 아주 큰 케이크를 구웠어요. 예전에 방직 공장의 아주머니가 가르쳐주신 레시피인데, 요리사들의 솜씨에는 미치지 못하지만, 그 특별한 맛은 저와 젠킨이 매우 좋아해요. 이번에는 재료 걱정 없이 모든 사람이 만족할 만큼 드실타래 수 있을 거예요. 꼭 와서 맛을 보아주세요.\n저는 다른 저들을 설득해서 조용히 생일을 보내도록 했어요. 오늘은 반드시, 반드시 당신에게 더 이상 문제를 일으키지 않을 거예요!\n가능하다면, 필요할 때 언제든지 저를 불러주세요. 세탁, 청소, 정리 등 무엇이든 제가 잘할 수 있어요. 당신의 그 따뜻함에 보답할 기회를 갖고 싶어요.\n\n메이슨"
  },
  Mail_68913_Name = {Text = "보답…"},
  Mail_68914_Desc = {
    Text = "수호자:  \n\n모두의 소원을 받아주는 사람으로서, 아무리 노력해도 생일날 내 차례가 되어 소원을 빌어야 한다는 것이 익숙해지지 않습니다. 제게는 원하는 것이 없어 보이네요. \n돌은 제게 진정으로 원하는 것이 무엇인지 찾아야 한다고 말했습니다. 자신이 하는 모든 일이 무엇 때문에인지 물어보라고 했습니다. \n저는 오랜 시간 동안 생각했습니다. 사실타래 저는 찾아오는 사람들 모두의 소원이 이루어지길 바랐습니다. 더 깊이 물어보면, 아마도 사람들이 소원이 이루어졌을 때 웃는 모습과 진심으로 나를 둘러싸고 감사하며, 여신의 직책을 완수했다고 칭찬하는 모습을 좋아하는 것 같습니다. \n돌은 그것이 제가 자신의 가치가 인정받기를 바라는 것이며, 유용한 사람이 되고 싶다는 것이라고 말했습니다. 그녀의 말이 맞다고 생각합니다. \n하지만 그녀는 사람의 가치가 다른 사람에 의해 결정될 필요가 없다고 말했습니다. 유용하다는 것이란 것이 없다고 하며, 중요한 것은 자신의 마음에 순종하는 것뿐이라고 했습니다. 무용한 사람이 되더라도 상관없다는 것입니다. \n역시 돌은 항상 이렇게 깊은 말을 합니다. 하지만 도대체 유용한 사람이 될 것인지, 무용한 사람이 될 것인지, 저는 다시 혼란스러워졌습니다…… \n하지만 마음에 순종한다면, 아마도 유용한 사람이 되고 싶을 것입니다. 만약 생일날 모두의 웃는 얼굴을 볼 수 있다면, 그것이 제게 가장 원하는 선물일 것입니다. \n\n힐레스트"
  },
  Mail_68914_Name = {
    Text = "쓸모 있는 사람…"
  },
  Mail_68914_Sender = {
    Text = "셀레스트"
  },
  Mail_68915_Desc = {
    Text = "사랑하는 수호자님께: \n\n저는 이미 뒷골목의 벌레처럼 사는 것이 제 운명이라고 받아들였습니다. 오히려 그것이 제 삶의 일부라고 느낍니다. 저는 그것을 전적으로 받아들이고, 기쁘게 맞이했습니다. \n여러분들이 저에게 다시 자유의 달콤한 맛을 느끼게 해주었음에 항상 감사하지만, 제 특별한 취미를 이해해주는 사람은 아무도 없습니다. 그것은 당연한 일입니다. 여기 있는 대부분의 사람들은 온화한 선한 사람들로, 습기 찬 구석에서 자라는 이끼가 밝은 햇빛이 아니라 어두운 공기가 필요하다는 것을 이해할 수 없습니다. \n당신만이 예외입니다, 존경하는 따뜻하신 분. 오직 당신만이 진심으로 저를 이해해주고, 도와주시며, 저에게 진정한 행복을 주십니다. 당신이 주시는 고통은 그렇게 만족스럽고 안심이 되어, 제 존재를 확인할 수 있게 해줍니다. \n만약 과거에 생일에 바랄 만한 욕망이 없었다면, 이제는 당신의 뒤를 따르고, 당신을 위해 제 몸과 마음을 바치는 것이 제 소원입니다. \n물론, 저에게 너무 부드럽게 대해주지 마세요. 저를 경멸하고, 꾸짖고, 채찍질해주세요! \n\n레이아"
  },
  Mail_68915_Name = {
    Text = "이끼의 마음…"
  },
  Mail_68915_Sender = {Text = "레아"},
  Mail_68916_Desc = {
    Text = "사랑스러운 강아지야:\n\n나는 거의 당신과 고양이와 생쥐의 게임을 하는 이 날들을 사랑하게 되었어. 마치 오래된 영웅 소설처럼, 정의의 사도가 마지막 순간에 악당의 음모를 막는 것이 얼마나 감동적이고 위대한지. \n하지만 당신이 계속해서 헛수고를 하며 투쟁하는 모습을 보면 참으로 웃음이 나와. \n이 세상은 이미 끝났어, 구원할 방법은 전혀 없어. 이 행성은 수많은 죽은 행성들처럼 ▼&#x5B▼87;&4;▼ 될 거야. \n좋아, 당신과 놀아줄게. 지금 나는 갑자기 N의 취미를 이해할 수 있게 되었어. 운명적인 결말이 도래하기 전까지, 어떤 일을 하든 크게 차이가 없다는 걸. \n당신의 사랑하는 스승님의 생일날, 나는 여전히 당신을 위해 큰 선물을 준비했어. 생일이 끝나는 카운트다운 전에, 숨겨진 \"폭탄\"을 찾아주길 바라. \n우리가 완전히 소멸되기 전, 당신은 나에게 얼마나 많은 즐거움을 줄 수 있을까? \n\n\n\"돌\""
  },
  Mail_68916_Name = {
    Text = "깜짝 폭탄"
  },
  Mail_68916_Sender = {
    Text = "융해·돌"
  },
  Mail_68917_Desc = {
    Text = "수호자: \n\n최근 렌티니언의 상류층 사이에서 자신이 설계도를 그려 특별한 보석을 주문하는 유행이 일어났습니다. \n그들 중 일부는 보석의 크기를 자랑하던 것이 이제는 설계도의 정교함을 자랑하기 시작했습니다. 그러나 그들이 유명 화가를 비밀리에 고용한다는 사실타래은 마치 도둑이 자신의 귀를 막고 있다는 것처럼 명백합니다. \n이 유행 덕분에 제 생일 선물 목록에도 많은 풍류를 부리는 보석과 장신구가 추가되었습니다. 그중에는 꽤 좋은 비둘기 핏빛 루비가 하나 있는데, 이에 어울리는 반지 받침이 필요합니다. \n저는 재미없는 노인들에게 의뢰하기보다는 제 기사에게 마음을 담아 설계도를 그려주는 것이 어떨까요? 그것이 저에게 주는 선물로 삼는 건 어떨까요? \n당신의 작품을 기대하며, 당신의 미각이 훌륭할 거라 믿습니다. \n\n소렐"
  },
  Mail_68917_Name = {
    Text = "보석 디자인…"
  },
  Mail_68917_Sender = {Text = "소렐"},
  Mail_68918_Desc = {
    Text = "수호자: \n\n당신을 처음 만나기 전, 수많은 문살 뒤에서 이미 무수히 많은 같으면서도 다른 당신을 보았습니다. \n내가 기억해 당신의 기쁨과 분노, 슬픔, 당신의 매 선택, 그리고 다른 세계에서 계속 나아가는 모습을 기억합니다. \n나에게 있어, 이 많은 당신들 중에서 당신은 가장 특별한 존재입니다. 내가 관찰한 세계들을 마음속에 이름을 붙이고 번호를 매겼는데, 당신이 있는 세계는 ‘희망’이라 불렀고, 그 이름은 당신을 만난 날 지었습니다. \n이 ‘희망’이라는 하루, 당신이 다른 세계를 볼 흥미가 있을 거라 생각합니다. 우주의 눈으로 경험하듯, 나는 당신을 이끌어, 내가 문살 앞에서 조용히 바라본 모든 것을 보여드리겠습니다. \n그리고 나의 눈에 비친 당신을 보십시오. \n\n타비"
  },
  Mail_68918_Name = {
    Text = "다른 그대..."
  },
  Mail_68918_Sender = {Text = "타비"},
  Mail_68919_Desc = {
    Text = "원래 미사그의 간결한 스타일이 나의 마음에 들었지만, 미리암이라는 여자가 도착한 이후로 내 생활은 평화롭지 않게 되었다. \n나는 안정을 찾고 보호를 찾는 이들을 거부하지 않는다. 이 혼란스러운 세상에서 위안을 찾는 것은 생명체의 당연한 본능이며, 비난할 일이 아니다. \n하지만 나는 전능한 신으로 자처하는 것을 좋아하지 않았으며, 리모리아가 침몰한 후에는 이곳에 또 다른 높은 신을 만들 필요가 없다고 생각했다. \n미리암은 아마도 과거의 그림자에서 벗어나지 못해, 그 어리석은 믿음의 스타일을 지금으로 옮겨왔기 때문에, 내가 학교 어디를 가든 항상 주목받고, 심지어는 얽매이는 상황이 생겨서 정말 짜증스럽다. \n오늘은 내 생일이니, 그 여자는 이미 큰 행사를 준비해 의식을 벌일 것이 분명하다. 나는 그 소리를 듣고, 그 광경을 보면 머리가 아프기 때문에, 그런 번거로움에 휘말리지 않기 위해 참석하지 않을 것이다. \n만약 네가 원한다면, 편지 뒤에 적힌 주소로 와서 함께 산책하며 마음을 진정시킬 수 있다. \n절대 그 여자가 알지 못하게 하도록 하라, \n\n투루"
  },
  Mail_68919_Name = {
    Text = "소란을 피해서 조용히…"
  },
  Mail_68919_Sender = {Text = "툴루"},
  Mail_68920_Desc = {
    Text = "매일 배가 고프지만, 잠시라도 피를 마시지 않으면 불편해요. 하지만 당신의 피를 맛본 후로는 그저 보통의 피는 입안에서 왁처럼 맛이 없어요. 당신의 피의 아름다운 맛은 매일 목을 타고 유혹합니다. \n 한 사람을 완전히 빨아먹으면 얼마나 많은 피를 마실타래 수 있는지 알아요. 그런 맛은 순식간에 사라집니다. 당신이 너무 빨리 죽지 않도록 허기을 참아내고, 다음 맛있는 것을 기대하며 참고 있어요. 다시 당신의 신선한 피를 맛볼 때까지요. \n 하, 정말이지, 내가 실타래제로 이걸 해냈다니 믿기지 않아요. 나는 이미 진화했는지도 몰라요. 이렇게 참고 있으니, 적어도 이 생일이라는 날에는 당신의 달콤하고 맛있는 피를 한 번만 맛보게 해주세요, 조금만요, 어떠세요? \n 나는 트라웃 클럽에서 벌어온 돈으로 영양 보충제를 샀어요. 이번에는 당신이 빈혈이 되지 않을 거예요. \n\n 오랫동안 굶주린 유우하시"
  },
  Mail_68920_Name = {
    Text = "맛있는 피…"
  },
  Mail_68920_Sender = {
    Text = "유우하시"
  },
  Mail_68921_Desc = {
    Text = "존경하는 수호자님:\n\n올해 훈련 과정에서 지속적인 발전을 보는 것이 매우 기쁩니다. 곧 젊은 시절의 저를 뛰어넘어 강력한 병사가 되실타래 것입니다. 당신의 훈련 교관이 될 수 있어 매우 영광스럽습니다.\n올해 생일에는 등산에 적합한 장화를 받았습니다. 혹시 저와 함께 트레킹을 해보시겠습니까? 체력을 검증하고 산 정상에서 일출을 감상하며 도시를 벗어난 아름다운 경치를 즐겨보는 것도 좋을 것 같습니다.\n물론, 산야에서 야영 피크닉을 즐기며 추위를 녹이는 독한 술 한 병이 있다면 더없이 완벽할 것입니다.\n\n엘바"
  },
  Mail_68921_Name = {Text = "등산…"},
  Mail_68921_Sender = {Text = "엘바"},
  Mail_68922_Desc = {
    Text = "파트너: \n\n이 한 해 동안 많은 일이 있었죠. 당신에게 있어서 이는 아름다운 학교 생활이 아니었을지도 모릅니다. \n지난 한 해 동안, 제가 당신을 너무 강하게 밀어붙였고 배려가 부족했다는 것을 인정합니다. 모든 훈련이 너무 성급하게 진행되어, 당신이 너무 많은 것을 견뎌야 했습니다. \n하지만 당신이 내게 가장 중요한 사람이라는 것을 알아주길 바랍니다. 미사그의 수호자로서의 역할 외에도, 당신은 나의 유일한 파트너입니다. \n오늘 하루, 즉 생일 하루 만이라도, 제가 한 번쯤은 제멋대로 굴어볼 수 있기를 바랍니다. 그리고 당신도 모든 책임에서 벗어나 모든 과제와 훈련을 잊고 마음껏 휴식을 취할 수 있기를 바랍니다. \n시내의 놀이공원? 극장? 백화점이나 거리 시장…… 어떤 것이라도 좋습니다. 저는 당신에게 부족했던 것을 최대한 보상하고 싶습니다. \n마찬가지로, 아무것도 고려하지 않는 이 하루를 당신과 함께 보내고 싶습니다. 모든 일정은 당신이 결정하세요. \n\n라모나"
  },
  Mail_68922_Name = {
    Text = "여유로운 하루…"
  },
  Mail_68922_Sender = {Text = "라모나"},
  Mail_68923_Desc = {
    Text = "친애하는 수호자에게: \n\n내가 인간 세상에서 보낸 세월 동안, 매년 오늘 나의 사랑스러운 하인들은 나를 위해 성대한 잔치를 열고 온갖 방법으로 나를 기쁘게 하려 노력했다. \n별다른 일 없는 평범한 하루였지만, 그들의 알 수 없는 미소들 속에서 진짜로 기쁘게 되었다. 고난 속에서 즐거움을 찾고 무에서 유를 창조하는 재주에 있어서 인간은 확실타래히 뛰어나다. \n심지어 이 학교가 묘지를 캠퍼스 안에 세워진 곳임에도 불구하고, 너희는 여전히 그렇게 강한 의지로 즐거움을 만들어내는 것이 놀랍다. \n다만 평범한 사람들의 선물은 지루하기 짝이 없고, 소위 생일 파티도 믿기 어려울 정도로 따분하며, 결국은 평범한 사람들이 대부분이다. \n오직 너만은, 너를 생각할 때면 약간의 흥미를 느끼며 옛날과 같은 즐거움을 다시 한번 맛볼 수 있다. \n지금 당장 내 방으로 오라는 명령이다. 밤새 나와 함께 놀아라. 잘 받들어 모신다면, 나는 마지못해 네가 내 손등에 입맞추는 것을 허락하리라. \n\n완다"
  },
  Mail_68923_Name = {Text = "명령…"},
  Mail_68923_Sender = {Text = "완다"},
  Mail_68924_Desc = {
    Text = "<Del:서구의 놈>감시자: \n원래 이런 감성적인 글을 다시 쓰려고 하지 않았는데, 에이지스가 옆에서 기념하고 의미를 계속 말해서, 꼭 너에게 이 편지를 써야 한다고 했어. \n에이지스의 부탁으로 겨우 몇 마디 할게. 뭐, 여기서 1년 동안 지냈는데, 학교의 숙소와 식사는 전반적으로 만족스럽지만, 유일하게 기숙사의 침대 시트가 너무 매끄러워서 자꾸 익숙해지지 않더라고. 너희들은 거친 면직물이 더 편하다고 생각하지 않아? \n또 다른 불만을 말하자면, 식당 음식이 너무 건강해서 먹고 나면 배는 부르지만 입맛이 없어, 거리 음식의 맛에는 전혀 못 미치네! \n그래서 올해 생일 파티에서는 요리사들에게 신경 쓰지 않을 거야. 내가 미식가로서 여러분을 동구의 신비한 골목으로 가서, 나와 브라운이 특별히 추천하는 노점 음식을 맛보자. 보장컨대, 금방 거리 음식의 맛에 반할 거야! \n물론, 오늘의 모든 비용은 서구의 놈이 지불할 거야. 너도 별로 문제 없지? \n\n너의 오랜 친구 제킨과 브라운"
  },
  Mail_68924_Name = {
    Text = "길거리 음식..."
  },
  Mail_68924_Sender = {Text = "젠킨"},
  Mail_68925_Desc = {
    Text = "귀인: \n\n언니 외에는 너가 처음으로 진심으로 나를 지지해주는 사람이야. 네가 이전에 준 조언 덕분에 나는 지금 이미 음반 회사와 여러 앨범을 발표했고, 곧 내 단독 콘서트를 개최할 예정이야. \n나는 이 행성에서 열리는 첫 번째 콘서트를 생일 날짜로 정하려고 해. 이곳에서의 신생을 기념하기 위해서야. \n콘서트에서 내 최선을 다한 노래를 들려주고 싶어. 마지막 순서에서는 너와 언니를 특별 게스트로 무대 위로 초대하고, 함께 새 노래를 부르고 싶어. 어떻게 생각해? \n아참, 이 일은 내 언니에게 말하지 마. 이날도 그녀의 생일이니까, 그녀에게 깜짝 선물을 주고 싶어. \n내가 언니와 약속한 생일 소원은 이 행성에서 내 목소리가 다시 빛나기를 바라는 거야. \n\n틴커트"
  },
  Mail_68925_Name = {
    Text = "콘서트…"
  },
  Mail_68925_Sender = {Text = "틴커트"},
  Mail_68926_Desc = {
    Text = "사랑하는 수호자님:\n\n알게 모르게 또 한 해가 지나갔네요. 저는 미사그에서의 매일이 매우 즐겁고, 모두와 함께 놀고, 수업을 듣고, 정말 많은 맛있는 음식을 먹는 것이 제 인생에서 가장 행복한 시간이었습니다. 가끔 임무를 나갈 때는 조금 긴장되기도 하지만, 여러분과 함께 전투하면 에이지스는 결코 두렵지 않아요.\n올해도 제가 많이 폐를 끼친 것 같아서 정말 죄송합니다. 대부분은 젠킨이 또 장난을 친 경우였지만, 그녀는 단지 모두를 기쁘게 하고 싶었던 거예요. 우리의 부주의와 실타래수를 너그럽게 이해해 주시길 바랍니다.\n젠킨에 대해 말하자면, 올해 그녀는 제 생일에 반딧불이 잡기 대회를 열자고 제안했어요. 그녀는 투명한 병을 많이 준비해서, 정말 많은 반딧불이 등을 만들 계획이라고 했습니다. 마지막에 누가 만든 등이 가장 밝은지로 '반딧불이 잡기 대왕'이라는 칭호를 받게 된다고 하네요.\n'반딧불이 잡기 대왕'이라는 칭호는 조금 우습게 들리지만, 여름마다 반딧불이가 반짝이는 숲은 정말 아름답습니다. 바쁘시겠지만 여유가 있으시다면, 우리와 함께 숲으로 와서 별처럼 반짝이는 풍경을 감상해 보세요.\n\n에이지스"
  },
  Mail_68926_Name = {
    Text = "반딧불이 잡기 대회…"
  },
  Mail_68926_Sender = {
    Text = "아이기스"
  },
  Mail_68927_Desc = {
    Text = "수호자! 며칠 전 바다에서 수영을 하다가 오레타는 전기를 내뿜는 새로운 친구를 만났어요! 그 친구는 동그랗고 납작해서 큰 피자처럼 생겼어요! \n오레타가 인사를 건넸는데, 갑자기 몸이 전기가 흐르는 것 같더니 새 친구가 순식간에 사라져버렸어요. \n돌이 말하기를, 그게 전기뱀장어라는 건데 오레타는 잘 이해하지 못했지만 새 친구가 정말 대단하다고 생각했어요! 마침 오레타의 생일이 다가오니 수호자가 오레타와 함께 새 친구를 데리고 와서 오레타의 친구들과 함께 살면 좋겠어요! 그 전기가 흐르는 것 같은 느낌, 수호자도 분명 좋아할 거예요! \n\n오레타"
  },
  Mail_68927_Name = {
    Text = "전기를 뿜는 새 친구..."
  },
  Mail_68927_Sender = {Text = "오레타"},
  Mail_68928_Desc = {
    Text = "존경하는 수호자께:\n\n어린 시절의 생일은 저에게 있어 아버지의 엄격한 요구였으며, 조금도 느슨해질 수 없는 연습의 시간이었습니다.\n교만해지지 말 것, 부산스럽지 말 것, 게으르지 말 것. 어머니께서 몰래 작은 케이크를 준비해 주시곤 했지만, 이날은 단지 지난 일 년간의 부족함을 지적받는 엄격한 훈계의 날이었습니다.\n오늘에 이르러 저는 더 이상 음악의 제자가 아니며, 당신 덕분에 그 웅장한 문에 손을 얹고 최고의 음악 전당에 들어설 수 있게 되었습니다. 그러나 어릴 때부터 받은 가르침은 이미 저로 하여금 세속적인 즐거움에 대한 욕망을 갖지 않게 만들었습니다.\n오직 음악만이, 오직 당신을 위해 운명처럼 정해진 안혼곡을 연주하는 것이 제가 살아가며 추구하는 최종 목표이며, 유일하게 의미를 느끼는 순간입니다.\n만약 당신이 오늘 밤 잠들기 전의 시간을 저에게 맡겨주시다면, 저는 밤새도록 제 영혼에 새겨진 곡을 당신을 위해 연주하겠습니다, 새벽까지.\n\n함린"
  },
  Mail_68928_Name = {
    Text = "연주의 소원…"
  },
  Mail_68928_Sender = {Text = "하멜른"},
  Mail_68929_Desc = {
    Text = "소년: \n\n여기 온 이후로 그 고지식한 미친 여자로부터 벗어났다고 생각했는데, 너희 이 괴상한 곳의 규칙이 오히려 그 여자보다 더 심하더군. 나는 정말 오랫동안 통쾌함을 느껴보지 못했어! \n큰 잔으로 술을 마시는 것이 허용되지 않아, 미녀와 장난치는 것도 안 되고, 모닥불 잔치도 안 되고, 여기서 구워 먹는 고기는 필리스탄의 것보다 훨씬 못해! 이렇게 맛이 없는 생활을 어떻게 견디는지 정말 모르겠어. \n하지만 강자는 환경에 대해 불평하지 않지. 내가 이곳에서 정복하고 다닌 결과, 이미 너희 도시에서 다시 위대한 갱단의 지도자가 되었어. \n위대한 고리아의 주인인 나의 생일을 맞아, 너를 내 부하들이 준비한 연회에 초대하려고 해. 좋은 술, 좋은 고기, 그리고 아름다운 여인들이 가득할 거야. 세상 물정 모르는 어린애 네가 눈을 크게 뜨게 될 걸. \n우리 사이의 예전 인연을 생각해서 선물은 요구하지 않을게. 다만 네가 존경심을 가지고 와서 강자의 재기와 성공을 축복해주면 돼. \n눈 똑바로 뜨고 잘 보라고. 내년 오늘, 내년의 내년 오늘, 어디에 있든 상관없이 나는 새로운 길을 개척할 거야. \n\n고리아"
  },
  Mail_68929_Name = {
    Text = "정복의 여정…"
  },
  Mail_68929_Sender = {Text = "골리아"},
  Mail_68930_Desc = {
    Text = "수호자: \n\n원래 나는 이 얕은 몸의 생일을 축하할 생각이 전혀 없었고, 이를 보통의 수행 날로 여겼습니다. 하지만 왕이 오늘 아침에 나를 찾아와 입으로 명령을 내리시길, 오늘은 왕과 수행에 관련된 일을 전혀 하지 말고 자신을 위해 하루를 보내라고 하셨습니다. \n많은 밤낮 동안 처음으로 이렇게 저를 염려해 주시니, 정말 두려움과 감사가 가득합니다. 그러나 저는 이미 제 모든 것을 왕께 헌신하였기에, 어디로 가야 할지 무엇을 해야 할지 순간적으로 알 수 없었습니다. \n오랜 시간 고민한 끝에, 지금 유일하게 약간의 후회로 남아 있는 것은 머피라는 아이에 대한 죄책감입니다. 비록 조국 부흥을 위해서라 해도, 그녀에게 진 빚은 갚을 길이 없고 메울 수도 없습니다. \n하지만, 만약 제가 진심으로 하고 싶은 일이 있다면, 아마도 부끄러운 일임에도 불구하고 한 번 더 어머니로서 해야 할 일을 하고 싶다는 것입니다. \n저는 특별히 그 아이가 예전에 좋아했던 디저트를 사왔습니다. 이는 비열하고 실타래격된 어머니로서의 작은 소원을 이루기 위한 것입니다. 부탁드리지만, 이 선물을 그녀에게 전달해 주실타래 수 있을까요? 그녀에게는 제가 보낸 것이 아니라고 하고, 당신이 준비한 것이라고만 말해주세요. \n허락해 주신다면, 진심으로 감사드립니다. \n\n미리암"
  },
  Mail_68930_Name = {Text = "보완…"},
  Mail_68930_Sender = {Text = "미리암"},
  Mail_68931_Desc = {
    Text = "아하, 나의 지혜로운 사고를 통해 나는 이미 인간의 생일의 의미를 완전히 이해했다. 이른바 누군가에게 특별히 속한 하루는, 사람들이 드문 특권을 행사할 기회를 얻고 소중한 아이템을 획득할 기회를 가지며, 다른 사람에게 당당하게 소원을 요구할 수 있는 기회를 위한 것이다. \n어떠한 평소에 감히 말하지 못했던, 혹은 생각하지 못했던 소원이라도 이날에는 이루어질 가능성이 있다. 하, 이건 정말 어떤 축제보다도 자극적인 날이다. \n보아하니 지난 여러 해 동안 나는 이렇게 많은 특권의 기회를 놓쳤던 것이지만, 다행히도 내 긴 수명 덕분에 앞으로도 훨씬 더 많은 생일 동안 소원을 빌 수 있겠지. \n그렇다면, 생일에 모든 사람에게 함께 신나게 놀자고 요구하는 것은 분명히 충분히 들어줄 만한 소원이겠지? \n\n로탄"
  },
  Mail_68931_Name = {
    Text = "생일 주인공의 특권…"
  },
  Mail_68931_Sender = {Text = "로탄"},
  Mail_68932_Desc = {
    Text = "수호자: \n\n나이가 들면서 생일은 달력에서 순간 이동하듯 지나가는 날로 변해버렸습니다. 종종 무심코 떠올릴 때쯤이면, 생일은 이미 물처럼 조용히 지나갔습니다. \n성인의 세계에서는 생일을 축하하는 것이 아이들과 한가한 사람들의 특권일 뿐입니다. 이 방면에서도 나는 한가한 어른이 되어, 생일에 대한 기대는 거의 사라졌습니다. \n한 해에는 갑자기 기발한 생각이 떠올라, 자신을 위한 아름다운 케이크 조각상을 조각했습니다. 그 후 몇 년 동안, 나는 생일을 잊고 케이크를 주문하지 않는 대신, 생일 당일 창고에서 이 영원히 부패하지 않는 축하 도구를 꺼내 촛불을 불어 끄는 의식을 체험하며, 그렇게 생일을 보냈습니다. \n미사그에 도착한 후, 나는 한 사람이 동시에 여유롭고 바쁜 상태를 보일 수 있다는 것을 발견했습니다. 그리고 여기서 사람들은 자신이 혼자 무료한 것에 만족하지 않고, 반드시 모든 사람을 함께 무료하게 만들려고 합니다. \n지난 두 해 동안 미사그에서 참석한 생일 파티는 내가 이전에 참석했던 모든 생일 파티보다 많았습니다. 더욱 웃기는 것은 이런 무료한 축제에서 나는 묘한 즐거움을 찾게 되었습니다. \n비장하고 엄숙한 주제 외에도, 일상의 어리석은 장면들을 묘사하면 그것도 예술의 아름다움으로 가득 차 있을 수 있습니다. \n이런 말을 하면서, 올해 생일의 창작 계획은 수호자가 웃는 반신상을 조각하여, 내 조각 케이크를 받들게 하려고 합니다. \n내 스튜디오에 좀 더 일찍 와주세요, 제 뮤즈 모델. \n\n산"
  },
  Mail_68932_Name = {
    Text = "지루한 재미…"
  },
  Mail_68932_Sender = {Text = "산"},
  Mail_68933_Desc = {
    Text = "전신안: \n\n 오랜 고민 끝에 이 편지를 이 적멸된 세계에서 씁니다. 오랜 시간 동안 제 생일을 거의 잊고 지냈는데, 이런 세상에서는 축하하는 것이 무의미합니다. \n 하지만 당신과 만나고 나서 저는 점점 더 탐욕스러워졌습니다. 날이 갈수록 익숙했던 고독조차 견디기 어려워졌습니다. \n 이런 순간마다 제 마음에는 이상한 감정이 피어오르고, 그쪽 세계의 저 자신에게 약간의 부러움과 미세한 질투를 느낍니다. 보십시오, 저처럼 이성적이라고 자부하는 사람도 이렇게 비열한 생각을 하는 날이 올 줄은 몰랐습니다. 인간의 공정함과 이성에도 한계가 있다는 것을 알 수 있습니다. \n 당신이 어떤 초대를 할지 알고 있지만, 시공간에 불필요한 교란은 피해야 합니다. 저는 당신의 세계로 전향하지 않을 것이며, 전향해서도 안 됩니다. \n 이 글을 쓰는 지금, 저는 우주를 바라보고 있습니다. 터널이 시작되는 곳을 바라보며, 만약 당신이 우연히 하늘을 올려다본다면 우리는 같은 별빛을 함께 바라보고 있는 셈입니다. \n 이 편지가 저를 대신해 시공간을 넘어 당신의 손에 닿아, 당신의 눈과 입술을 통해 당신과 만나고 당신과 함께하기를 바랍니다. \n 당신이 이 서신지를 껴안을 때, 저는 이 세계의 이쪽에서 당신을 껴안는 상상을 할 것입니다. \n\n 라모나"
  },
  Mail_68933_Name = {
    Text = "함께 바라보며…"
  },
  Mail_68933_Sender = {
    Text = "회귀·라모나"
  },
  Mail_68934_Desc = {
    Text = "내 작은·죄수:\n\n알고 있나요, 다른 동물들이 서로 다른 식단을 가지고 있는 것처럼, 사람마다 따뜻함에 대한 필요는 각각 다르답니다. 어떤 사람은 옷 한 벌로 충분히 따뜻해지고, 어떤 사람은 따뜻한 손, 따뜻한 포옹이 필요하며, 또 어떤 사람은 촛불이 녹는 온도의 따뜻함을 필요로 하죠. \n그렇게 뜨겁고 끈적한 온도가 신경 말단 하나하나에 각인되어, 촛불이 흐르듯 떨어지는 궤적을 선명하게 비추며, 약간의 통증과 전율을 주는 감촉이 느껴지죠. 결국 참지 못하고 소리 내어 외칠 때야 비로소 자신의 존재를 시원하게 느낄 수 있어요. \n때로는 내가 촛불이 되어 각인의 즐거움을 만끽하기도 하고, 때로는 촛불의 따스함에 빠져들어 그런 아픔을 주는 달콤하고 따뜻한 온기를 갈망하기도 해요. \n미사그의 겨울이 이미 찾아왔고, 최근 나는 자주 추위와 그로 인한 고독을 느끼곤 합니다. 사랑하는 당신이라면 오늘 무슨 날인지 잘 알고 있을 거예요. 내 바람은 단순합니다. 착한 당신이라면 분명히 나에게 외로움을 없애 줄 따뜻함을 가져다줄 거라고 믿어요. \n\n판디아"
  },
  Mail_68934_Name = {
    Text = "따듯함이 필요해…"
  },
  Mail_68934_Sender = {Text = "판디아"},
  Mail_68935_Desc = {
    Text = "수호자: \n\n올해 나는 틴커트와 서로 약속했다. 생일 소원은 오직 자신에 관한 것만 빌 수 있고, 상대방을 위해 빌 수는 없다. \n비록 그녀가 먼저 화가 나서 이 약속을 제안했지만, 분명히 이번에는 그녀 자신도 난처해졌다. \n우리 둘은 너무 오랫동안 얽혀 지내온 탓에, 보통 사람들처럼 독립적으로 생각하는 것조차 쉽지 않다. 하지만 이렇게 많은 도움과 관심 속에서 새로 태어난 삶에서, 지금보다 더 적합한 때가 있을까? \n그래서 신중히 고민한 끝에, 올해 비칠 소원이 떠올랐다: 다섯 명의 새로운 친구를 사귀기……아니, 세 명으로 하자. 결국 자신을 바꾸는 일은 한 점 한 점 천천히 해야 하니까. \n현재 유일하고 매우 인기 있는 친구로서, 당신이 나에게 친구 사귀는 법을 조금 가르쳐줄 수 있을까? \n\n파인트"
  },
  Mail_68935_Name = {
    Text = "친구를 사귀고 싶은 마음…"
  },
  Mail_68935_Sender = {Text = "파인트"},
  Mail_68936_Desc = {
    Text = "수호자: \n\n매년 생일 소원을 빌 때마다 나는 항상 같은 소원을 빈다. 그것은 완벽한 혈통의 변화이다. 사실타래 나는 항상 알고 있었다. 나의 혈통에 대한 집착이 다른 사람들에게는 고집스럽고, 웃기며, 심지어 가련하고 비천하게 보일 수 있다는 것을. \n하지만 당신은 다르다. 무론 언제나, 나는 당신이 이 길을 걸어가는 동안 나를 지지해 줄 것임을 안다. 벽에 부딪히거나, 넘어지거나, 아무런 성과 없이 돌아오더라도, 다른 사람들의 웃음 속에서, 당신은 나를 가장 먼저 걱정해 주는 사람이었다. \n아마도 당신이나 누구라도 어릴 때부터 억압받고, 수치심을 당한 사람이 짊어진 모든 것을 이해할 수는 없겠지만, 상관없다. 이 변화의 길에서 겪은 시련들은 모두 나의 혈육과 양분이 되어, 나를 계속 일어서게 하고, 계속 저항하게 한다. \n나는 더 이상 어렸을 때처럼 무력하지 않다. 설령 시험이 많더라도, 나는 마지막 순간까지 견고하게 걸어갈 것이다. \n그 전까지는, 나를 바라보며 나의 성공을 기다려 주길 바란다. \n맞다, 당신이 이전에 준 5000원, 내가 갚겠다고 했지? 지금은 이미 모았고, 200원이 더 남았다. 보답으로 함께 돌려주겠다. \n\n케이크스"
  },
  Mail_68936_Name = {
    Text = "돈을 갚을게…"
  },
  Mail_68936_Sender = {
    Text = "카이커스"
  },
  Mail_68937_Desc = {
    Text = "존경하는 수호자님:\n\n안녕하세요. 자동인형 에리카의 연간 점검 설문지를 작성해 주셔서 감사합니다. 저는 이 한 해 동안 에리카를 사용하면서 겪으신 진실타래한 경험과 문제점을 수집하겠습니다. 여러분의 의견은 에리카가 지속적으로 개선되는 방향을 결정합니다.\n아래 질문에 대해 낮은 순으로 점수를 매겨 주시면 감사하겠습니다, 여러분의 피드백에 진심으로 감사드립니다.\n사용 편의성: 1-5점\n응답 속도: 1-5점\n요구사항 이해도: 1-5점\n사용자 감정 배려도: 1-5점\n자료 검색 정확도: 1-5점\n문제 해결 실타래용성: 1-5점\n마지막으로 에리카를 사용하면서 겪으신 문제와 불만족한 부분을 간단히 설명해 주시면, 이러한 문제들은 향후 수정될 수 있습니다.\n설문지를 완료하시면 주년 기념 선물이 방으로 보내질 것입니다. 앞으로도 가장 친절한 조수 에리카가 여러분 곁에서 함께할 것입니다. 다시 한번 사용해 주셔서 감사드리며, 안녕히 계세요.\n\n에리카"
  },
  Mail_68937_Name = {
    Text = "연도 점검 조사 문항…"
  },
  Mail_68937_Sender = {Text = "에리카"},
  Mail_68938_Desc = {
    Text = "수호자: \n\n매년 생일이 오면, 나는 하루 종일 과거를 머릿속에서 세세히 회상하며, 같은 일기를 다시 한 번 쓰곤 합니다. \n고향을 떠난 지 오래될수록, 옛날의 기억은 마치 점점 희미해지는 것 같습니다. 빛을 따라오는 귀환을 기다리는 날들, 멀리서 왕의 위엄을 바라보던 날들은 이미 정확히 기억나지 않습니다. \n하지만 나는 잊고 싶지 않습니다. 절대 잊지 않을 것입니다. 기다림이 아무리 길고 끝없더라도, 영혼을 태워도, 이 빛은 희미해지지 않을 것입니다. 고국이 부활할 때까지, 나는 첫 번째로 소환에 응답하는 빛이 될 것입니다. \n나는 수많은 재회 장면을 상상해 보았지만, 여기서 왕과 사제를 다시 만나게 될 줄은 상상도 하지 못했습니다. 여러분들의 말대로, 마음이 평온한 곳이 즉 고향이라면, 이곳은 이미 나의 두 번째 고향이라고 할 수 있습니다. 그리고 내 일기장에 적힌 내용은 이제 회상에서 매일 새로운 기억으로 변했습니다. \n어떤 상이나 선물도 필요 없습니다. 왕의 곁에서 다시 따르는 것이 가장 큰 행복입니다. \n만약 이 몸의 빛이 고향의 바다를 비추지 못한다면, 그 빛은 왕의 발걸음을 따라 이 대륙의 나라를 잠시 비추겠죠. \n\n팔로스"
  },
  Mail_68938_Name = {
    Text = "나의 왕을 따라서..."
  },
  Mail_68938_Sender = {Text = "파로스"},
  Mail_68939_Desc = {
    Text = "수호자: \n\n축하합니다, 저를 축하해 주세요, 미사그를 축하해 주세요, 그리고 우리가 검은 공포의 추격 속에서 또 한 해를 살아남았음을 축하합니다. \n오늘은 단순한 생일이 아닙니다, 오늘은 제가 살아있는 기념일이며, 저의 강인한 생명에 대한 찬미일입니다. \n살아있다는 두 글자는 얼마나 많은 어려움을 담고 있는지, 이렇게 뜨거운 생명력은 뜨거운 커피의 향기와 견줄 수 있습니다. 수호자, 커피 신앙에 함께 참여하여, 깨어있음을 찬양하고, 살아있는 매 순간을 찬양합시다. \n\n신과 함께 온 쪽지: \n아, 웬컬 이 자식이 또 커피를 과음해서 신경이 과도하게 흥분하고 피로가 쌓여서, 바로 책상 앞에서 기절해 버렸어요. 저는 그녀를 보건실타래에 안치해 두었으니 걱정하지 마세요. \n그런데 그녀가 기절하기 전에 보관해둔 커피콩 한 봉지와 편지를 꺼내서 당신에게 주려고 했던 것 같아요. 그래서 편지와 함께 첨부했습니다. 그녀가 깨어나면 후회하지 않기를 바랍니다. \n그녀의 생일에 관해서는, 축하 파티보다 아마도 잘 쉬게 해 주는 것이 가장 좋은 선물이 될 것입니다. \n——실타래비아"
  },
  Mail_68939_Name = {
    Text = "생명을 찬미해…"
  },
  Mail_68939_Sender = {Text = "윙클"},
  Mail_68940_Desc = {
    Text = "수호자: \n\n하하하! 방의 여러 구석에 12개의 메모를 새기고, 36장의 메모지를 썼다(아마 더 많을 수도 있지만 찾을 수 없었다). 끝내 오늘 내 생일이라는 걸 기억해냈다! \n상상도 못 했겠지만, 사실타래 나는 오늘 아침에야 기억났다. 하지만 이건 지난 1년 동안의 노력 덕분이다. 이런 좋은 날을 놓치고 싶지 않았다. \n전에 함께 파티를 연 때 정말 즐거웠다. 특히 누군가와 어떤 게임을 하고, 어떤 달콤한 디저트를 먹었던 것…… 아무튼 즐거웠다! \n어릴 때 생일이면 엄마가 항상 모험 이야기 책을 사주셨다. 우리 둘은 매일 잠자리에 들기 전에 함께 읽었고, 꿈에서 멋진 모험을 꾸곤 했다. 깨어나면 금세 잊혀졌지만, 그 행복은 머릿속에 남아 있었다. 소중한 감정은 절대 잊혀지지 않는다고 믿는다. \n게다가 건망증도 장점이 있다. 이전 파티에서 무엇을 했는지는 기억나지 않지만, 오늘 다시 한 번 모두 경험할 수 있다. 지난번의 행복을 다시 한 번 느끼고 싶다! \n\n기대에 찬 노디라"
  },
  Mail_68940_Name = {
    Text = "다시 한 번…"
  },
  Mail_68940_Sender = {Text = "노틸라"},
  Mail_68941_Desc = {
    Text = "존경하는 수호자님:\n        V1.7.1 업데이트에서 「번식 광열」의 「혈쇄·히로」 이벤트의 해금 상태가 비정상적으로 소실타래되었습니다. 소실타래된 해금 상태 이후 다시 해금하신 것에 대해, 다시 해금 시 소모된 「현실타래의 시작점」× 3을 보충해 드립니다. 확인 바랍니다."
  },
  Mail_68941_Name = {
    Text = "혈연·시로 번식 광열 해금 보상"
  },
  Mail_68941_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_71330_Desc = {
    Text = "존경하는 수호자님:\n“반보 차이” 이벤트가 종료되었습니다. 수호자님의 남은 “인형 부품”을 각각 “장미 금권”× 40으로 교환하였으니, 수령해 주시기 바랍니다."
  },
  Mail_71330_Name = {
    Text = "인형 부품 회수"
  },
  Mail_71330_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_71331_Desc = {
    Text = "존경하는 수호자님:\n“이야기의 마법” 이벤트가 종료되었습니다. 수호자님의 남은 “유영하는 영감”을 각각 “장미 금권”× 40으로 교환해 드렸으니, 확인해 주시기 바랍니다."
  },
  Mail_71331_Name = {
    Text = "유영하는 영감 회수"
  },
  Mail_71331_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_71332_Desc = {
    Text = "존경하는 수호자님:\n“봄이 시들기 전에” 이벤트가 종료되었습니다. 수호자님의 남은 “기쁜 시”, “우울한 시문”과 “유감의 시문”을 각각 “장미 금권”× 40으로 교환하였으니, 수호자님께서 확인해 주시기 바랍니다."
  },
  Mail_71332_Name = {
    Text = "시문 회수"
  },
  Mail_71332_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_71848_Desc = {
    Text = "존경하는 수호자님:\n“장미 책과 함께” 이벤트가 종료되었습니다. 현재 수호자님께 남은 “통령조의 부채”를 각각 “장미 금권”× 40의 비율로 변환하여 드립니다. 수호자님께서 확인해 주시기 바랍니다."
  },
  Mail_71848_Name = {
    Text = "통령조의 부채 회수"
  },
  Mail_71848_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_74020_Desc = {
    Text = "존경하는 수호자님:\n“별들이 제자리에 있습니다·Rerun” 이벤트가 종료되었습니다. 수호자님의 남은 “무식한 배아”, “무욕의 배아” 및 “무욕의 배아”를 각각 “장미 금권”× 40으로 교환하였으니, 수령해 주시기 바랍니다."
  },
  Mail_74020_Name = {
    Text = "배아 회수"
  },
  Mail_74020_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_74347_Desc = {
    Text = "존경하는 수호자님:\n“영혼의 목자·Rerun” 이벤트가 종료되었습니다. 수호자님의 남은 “의미 있는 판매권”을 각각 “장미 금권”× 40으로 교환해 드렸으니, 수령 여부를 확인해 주시기 바랍니다."
  },
  Mail_74347_Name = {
    Text = "의미 있는 판매권 회수"
  },
  Mail_74347_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_74841_Desc = {
    Text = "파트너: \n\n작년 오늘, 나는 1년 후에 이 편지를 빈 이메일에 넣을 것이라고 전혀 상상하지 못했습니다. \n당시 당신은 미사그에 들어온 지 얼마 안 되었고, 고약하고 게으른 학생과 다를 바 없었습니다. 지금 생각해도 그때 나는 종종 당신에게 너무 엄격했고, 내 이성적이고 차가운 가면에 너무 집착했던 것 같습니다. \n실타래제로 작년 오늘, 나는 꽃다발을 샀습니다. 도서관 앞에서 붉은 리본과 짙은 녹색 포장지에 싸여 있는 장미를 오랫동안 바라보다가, 결국 그것을 내 침대 머리맡에 꽂았습니다. \n1년이 지나 꽃은 이미 시들었지만, 그 밝은 빨간 리본만은 K-0617번 은열쇠에 묶여 여전히 새빨갛게 빛나고 있습니다. \n나는 또 한 번 장미를 사고 싶지만, 이제 그것들은 다시 내 침대 머리맡에서 시들어갈 뿐, 다른 곳으로 갈 곳이 없습니다. \n모든 일을 자세히 해결 방안을 세우는 습관 때문에, 후회의 감정은 나에게 매우 새로우면서도 쓰라린 것입니다. \n하지만 나는 당신의 영혼이 아직 떠나지 않았다고 거의 맹목적으로 믿고 있습니다. 당신은 지금 우주의 어딘가를 여행하고 있을지 모르지만, 결국에는 다시 여기로 돌아와 제 곁으로 돌아올 것이라 확신합니다. \n이것이 비현실타래적인 상상이라고 생각하지 않습니다. 매번 블랙풀에서 당신의 얼굴을 바라볼 때마다, 마음속에서 당신과 연결되고 공명하는 따스한 온기를 느낄 수 있기 때문입니다. \n나는 항상 재회하는 그날을 믿으며 기다릴 것입니다. 우리의 손이 다시 맞잡히는 순간, 오늘 부족했던 장미를 직접 당신의 손에 전하겠습니다. \n\n라모나"
  },
  Mail_74841_Name = {Text = "장미…"},
  Mail_74841_Sender = {Text = "라모나"},
  Mail_76410_Desc = {
    Text = "존경하는 수호자님:\n“비 마을의 그림자” 이벤트가 종료되었습니다. 수호자님의 남은 “창백한 야수 두개골”, “그림자 짐승 해골”과 “진홍색 야수의 두개골”을 각각 “장미 금권”× 40으로 교환하였으니, 수령해 주시기 바랍니다."
  },
  Mail_76410_Name = {
    Text = "비 마을의 그림자 화폐 회수"
  },
  Mail_76410_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_78653_Desc = {
    Text = "존경하는 수호자님:\n“다중 치유·Rerun” 리메이크 이벤트가 종료되었습니다. 수호자님께서 남은 활동 통화 “기억 퍼즐”을 각각 “장미 금권”× 40으로 교환하여 회수할 예정이니, 수호자님은 꼭 확인하시기 바랍니다."
  },
  Mail_78653_Name = {
    Text = "기억 퍼즐 회수"
  },
  Mail_78653_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_78792_Desc = {
    Text = "존경하는 수호자:\n“눈이 녹을 때·Rerun” 이벤트가 종료되었습니다. 이제 수호자가 남은 이벤트 화폐 “냉동 꽃봉오리”, “은상꽃봉오리”와 “일광화포”를 각각 “장미 금권”× 40의 비율로 회수할 예정이니, 수호자는 꼭 확인해 주시기 바랍니다."
  },
  Mail_78792_Name = {
    Text = "꽃봉오리 회수"
  },
  Mail_78792_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_79390_Desc = {
    Text = "존경하는 수호자:\n        “망각의 전야”에 대한 귀하의 지원과 인식에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기를 정중히 요청드립니다. 귀하의 협조에 감사드리며, 설문을 완료하시면 “은심”× 200을 보상으로 준비하였습니다. 설문 마감 시간은 3월 17일 9:00입니다. 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 의견을 진지하게 듣고 있으며, 귀하의 피드백은 미사그 대학이 더욱 발전하는 데 큰 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
  },
  Mail_79390_Name = {
    Text = "버전 사용 조사 설문 V2.1.0"
  },
  Mail_79390_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_79646_Desc = {
    Text = "존경하는 수호자님:\n“기억 속에 묻혀” 이벤트가 종료되었습니다. 수호자님의 남은 “진단 보고서”를 각각 “장미 금권”× 40의 비율로 교환하였으니, 수호자님께서는 확인해 주시기 바랍니다."
  },
  Mail_79646_Name = {
    Text = "기억 속에 묻혀 화폐 회수"
  },
  Mail_79646_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_80091_Desc = {
    Text = "수호자：\n\n너가 이 편지를 열면, 내가 너의 마음에 심어 놓은 암시가 발효되었다는 뜻이야.\n하하, 걱정하지 마. 이것은 단지 내 생일 파티가 순조롭게 진행되도록 보장하기 위해 펼치는 미미한 최면일 뿐, 너에게 아무런 영향을 미치지 않을 거야.\n이제 너는 본능적으로 쇼핑하고 싶은 욕구가 생길 것이고, 그것을 따라 길로 나가서, 반짝이는 진열창에서 내가 가장 마음에 드는 선물을 선택하고 나에게 건네줘.\n나는 지금 네가 느끼는 의구심을 알고 있으며, 그것의 합리성도 인정해. 하지만 생일을 맞은 사람은 항상 약간의 특권이 있지 않니? 내가 이렇게 하는 이유는 너가 이 특별한 날을 잊지 않도록 하기 위해서야. 결국, 너는 내가 애타게 기다려온 손님이지.\n마지막으로, 나는 너의 방문을 인내심을 가지고 기다릴 거야—선물도 잊지 마. \n\n클레멘틴"
  },
  Mail_80091_Name = {
    Text = "“직접” 고른 선물"
  },
  Mail_80091_Sender = {
    Text = "클레멘타인"
  },
  Mail_81288_Desc = {
    Text = "존경하는 수호자:\n        《망각의 전야》에 대한 지원과 인정에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록 아래의 경험 조사 설문지를 작성해 주시기 바랍니다. 협조에 감사드리며, 설문지를 완료하신 분께는 「은심」× 200을 보상으로 준비했습니다. 설문 마감 시간은 4월 14일 9:00이니, 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 의견을 진지하게 듣겠습니다. 여러분의 피드백은 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
  },
  Mail_81288_Name = {
    Text = "버전 체험 설문조사 V2.2.0"
  },
  Mail_81288_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_81326_Desc = {
    Text = "은인님：\n\n오늘은 저와 폴리크스에게 있어, 일 년 중 유일한 축제입니다. 교회에 있을 때, 우리는 자아의 의미를 과도하게 주목할 수 없었고, 우리의 모든 가치는 오직 등불을 지키는 이 영원한 사역에만 존재했습니다. 그러한 신앙 앞에서 다른 어떤 축제도 무의미한 허망에 불과했습니다.\n하지만 생일이 이 날이 되면, 저와 폴리크스는 몰래 축하를 합니다. 우리는 하인을 속이고 서로에게 가능한 작은 선물을 준비하고, 이 날의 도래를 비밀스럽게 기대합니다.\n생일 축하 시간은 종종 한밤중에 있습니다——그것은 우리의 하루 중 유일한 자유의 순간입니다. 폴리크스의 영리한 손과 발상은 항상 그의 선물이 제 것보다 나아지도록 합니다. 한 번은 그는 떨어진 깃털을 모아 만개한 꽃을 짰습니다.\n사실타래 저는 서프라이즈를 준비하는 데 익숙하지 않지만, 폴리크스는 저의 평소 표정이 모든 것을 드러냈다고 말했습니다. 제가 가진 것이 당신 눈에는 더 황량하고 지루해 보일 것입니다. 하지만 오늘 저는 당신과 함께 기쁨을 나눌 환상적인 방법을 생각해냈습니다.\n당신이 저녁에 창문을 세 번 두드리는 소리를 들으면 두려워하지 마세요, 창문을 열어 주세요, 저는 당신을 구름과 야간 바람의 촉감을 경험하도록 이끌겠습니다.\n\n카스토르"
  },
  Mail_81326_Name = {
    Text = "밤 산책…"
  },
  Mail_81326_Sender = {
    Text = "카스토르"
  },
  Mail_84142_Desc = {
    Text = "비밀 지키는 사람:  \n\n합류 전, 나는 이 편지를 써서, 당신을 초대하고 내 「생일 항해」를 소개합니다.\n이번 항해의 첫 번째 목적지는 템스강입니다. 우리는 화물선을 개조한 이동식 레스토랑에 탑승하며, 보트를 타고 앉아있는 동안, 통조림 파인애플과 럼주를 맛보게 됩니다. 이것은 선원들이 생일에만 제공되는 맛있는 음식이며, 당신이 좋아하시길 바랍니다.\n이번 항해의 두 번째 목적지는 항구 전망대입니다. 걱정하지 마세요, 저는 이미 열기구 협회에 관측 권한을 신청했습니다. 열기구가 고공으로 올라가 런던 수로를 내려다볼 때, 우리는 함께 케이크를 자를 것입니다, 축하의 의미로.\n예전에는 항해 조건이 제한되어 있었고, 이른바 생일 케이크는 목수가 오크와 카라멜로 만든 모형에 불과하였기에, 저도 케이크의 맛을 몰랐습니다. 이번에는 당신과 함께 맛보게 되어, 음식의 아름다움 외에 더 많은 것을 얻을 수 있겠다고 생각합니다.\n세 번째 목적지는, 혹은 세 번째 단계라고 불려야 할 곳은 맞춤별 별자리 지도입니다. 저는 해도에 제 생년월일의 천체 위치를 기록하였고, 당신이 괜찮다면, 당신의 위치도 기록하고 싶습니다. 이렇게 독특한 항해 별자리는 가장 소중한 선물이 될 것입니다.\n사실타래 이 편지를 쓰면서 나는 주저했다. 이 행동들은 분명 일반적인 경계를 넘어서지만, 오늘은 특별한 날이며, 당신은 나에게 특별한 사람입니다. 그래서 내가 관례를 깨뜨릴 가치가 있습니다.\n그러니 제발 거절하지 말고, 제시간에 약속을 지켜 주십시오.\n\n클퍼샨트"
  },
  Mail_84142_Name = {
    Text = "「항해」 초대"
  },
  Mail_84142_Sender = {
    Text = "코퍼산트"
  },
  Mail_84355_Desc = {
    Text = "존경하는 수호자님:\n“폭우 속에서 흔들리다” 이벤트가 종료되었습니다. 수호자님께서 남은 활동 화폐 “신호기”를 각각 “장미 금권”× 40으로 교환하여 회수할 예정이니, 수호자님은 꼭 확인하시기 바랍니다."
  },
  Mail_84355_Name = {
    Text = "신호기 회수"
  },
  Mail_84355_Sender = {
    Text = "미사그 대학 위원회"
  },
  Mail_84410_Desc = {
    Text = "존경하는 수호자:\n        “망각의 전야”에 대한 지원과 인식에 감사드립니다. 수호자님이 미사그 대학에서 더 나은 게임 경험을 할 수 있도록, 아래의 경험 조사 설문지를 작성해 주시기를 정중히 요청드립니다. 협조해 주신 것에 대한 감사로, “은심” × 200을 보상으로 준비했습니다. 설문지를 완료하시면 수령하실타래 수 있습니다. 설문 마감 시간은 5월 5일 9:00이며, 제때 작성해 주시기 바랍니다.\n        <SurveyLink:[클릭하여 작성하기]>\n        우리는 모든 수호자의 의견을 진지하게 듣겠습니다. 여러분의 피드백이 미사그 대학을 더욱 발전시키는 데 큰 도움이 될 것입니다!\n        ——은열쇠가 앞길을 밝히기를."
  },
  Mail_84410_Name = {
    Text = "버전 체험 조사 설문지 V2.2.1"
  },
  Mail_84410_Sender = {
    Text = "미사그 대학 학사처"
  },
  Mail_89744_Desc = {
