  Mail_94424_Desc = {
    Text = "존경하는 수호자님:\n“위대한 정복” 이벤트가 종료되었습니다. 이제 수호자님의 남은 “맛있는 레오 바베큐”를 각각 “장미 금권” × 40으로 전환할 비율로 전환합니다. 수호자님께서 꼭 확인해 주시기 바랍니다."
