  Mail_94503_Desc = {
    Text = "내 빛나는 등불：\n\n내가 카스토르와 함께 여기 오고부터, 당신은 우리를 돌봐주셨고, 마치 우리에게 새 생명을 주신 것과 같다. 당신이 정성껏 준비해 주신 생일 케이크에 감사드리며, 케이크 위에 그린 두 개의 작은 새를 나비로 잘못 알게 되어 대단히 죄송하지만, 우리는 이 선물이 정말 마음에 듭니다. 이것이 우리에게 처음으로 다른 사람에게서 받은 생일 선물입니다.\n우리는 또한 코르트 학장으로부터 학교가 준 카드를 받았는데, 그 하얀 봉투에는 금색의 화려한 도장이 붙어 있었고, 그 안에는 아름다운 축복이 가득 쓰여 있었다. 이것은 정말 따뜻한 곳이다. 우리 인생에서 지금처럼 행복한 순간은 없었다.\n당신도 나와 카스토르의 생일을 축하하러 오세요. 이것은 우리가 어린 시절부터 고수해온 의식이며, 우리의 은인으로서 우리도 당신을 위해 교환할 선물을 준비했습니다. 이는 내가 카스토르가 떨어뜨린 깃털로 만든 왕관입니다.\n나는 이 조잡한 왕관을 당신께 바쳐, 우리의 경의를 표하고자 합니다. 나는 내 남은 생을 다해 당신 곁에 따르며, 이 학교의 위대한 비전을 실타래현하고 진정한 죄악과 어둠을 없애겠습니다.\n오랫동안 이런 일을 해보지 않았고, 카스토르는 내 기술이 어린 시절보다 못하다고 웃던 적이 있습니다. 당신이 싫어하지 않기를 바랍니다.\n\n폴룩스"
  },
  Mail_94503_Name = {
    Text = "깃털 왕관…"
  },
  Mail_94503_Sender = {Text = "폴룩스"},
  Mail_95382_Desc = {
    Text = "귀여운 작은 친구：\n\n작은 친구, 오늘은 내가 강림하는 날입니다.\n끊임없이 타오르는 불덩어리로서가 아니라, 케티굴라라는 소녀의 생일로서 말이죠.\n생전의 습관에 따라, 이 날 우리는 성대한 만찬을 열고, 좋은 술과 구운 고기를 마음껏 즐겼습니다.\n물론, 분위기와 관계없이 유치한 애송이들이 나이가 한 살 더 많아졌다고 놀리기 때문에, 나는 그들의 머리를 주먹으로 맞았습니다.\n현재 이 만찬에는 추가된 기능이 있습니다, 우리가 예전의 시간을 회상할 수 있도록 말입니다.\n올해는 또 하나의 활동을 추가할 계획입니다. 그것은 - 우리의 작은 친구를 사냥하는 것입니다!\n알고 있나요? 나는 당신을 이 만찬에 초대하고 싶어서, 당신의 부끄럽고 어리둥절한 표정, 반쯤 취한 모호한 눈빛, 내면에서 나오는 감미로운 향기로 올해의 생일 만찬을 꾸미고 싶습니다. 이것은 내가 태어난 이래 가장 좋은 생일 선물이 될 것입니다!\n이제 도주 계획을 세우기에는 늦었습니다. 왜냐하면 당신이 이 편지를 볼 때… 나는 이미 당신의 문 앞에 와 있습니다.\n두려워하지 마세요, 작은 친구, 만약 모든 것이 정상이라면, 당신은 여기에 가장 좋은 이야기를 듣고, 가장 맛있는 음식을 맛볼 것입니다.\n물론, 잡힌 작은 짐승에게는 사건이 발생하는 것도 정상 아닐까요.\n순순히 나와 함께 가라, 작은 친구, 당신의 멋진 시간은 반드시 나와 함께 보내게 될 것입니다.\n\n케티굴라"
  },
  Mail_95382_Name = {
