  Mail_96012_Desc = {
    Text = "존경하는 수호자님:\n“하늘에서 내려오는 수많은 빛” 이벤트가 종료되었습니다. 수호자님의 남은 “부의 “인장””, “피의 “인장””, “전쟁의 “인””을 각각 “장미 금권”× 40으로 교환하였으니, 수령해 주시기 바랍니다."
