  },
  Mail_96323_Desc = {
    Text = "수호자 각하：\n\n산 자가 생일을 축하하는 것은 남은 삶에서 의미를 찾기 위해서입니다. 그러나 저는 이 밤을 빌려 죽음의 향기를 더욱 짙게 요리할 뿐입니다.\n더 이상 고통받지 않고, 더 이상 집착하지 않는 죽은 자들은 생전의 모든 오염이 정화되고, 그들의 후회는 세심한 소금처럼 적절한 불길 속에서 피 속에 스며들어 촉촉하고 순한 향기를 형성합니다. 그들의 골격은 낮은 소리로 깨지며, 피부에서 스며 나오는 기름은 박하처럼 단정하고, 혼의 깊숙한 곳에서의 미완성된 말은 천천히 양조되는 동안 흘러나옵니다, 남겨진 것은 세심한 단맛입니다. 이미 당신이 고요한 물체로 변모한 모습을 상상하기 시작했습니다. - 피부가 난로 앞에서 조여질 때의 소리, 골육 사이에서 증발하는 감정, 당신의 순수한 혼이 점점 먹혀 들어가는 달콤한 맛...\n그러나 당신은 다릅니다.\n당신은 여전히 빛나고, 여전히 뛰며, 어떤 죽은 자도 비교할 수 없는 향기로 사람을 매혹시킵니다. 당신은 제가 기다리기를 기꺼이 선택한 숙성입니다. 저는 심지어 이 기다림이 영원보다 더 오래 지속되기를 바랍니다.\n이 무수한 반복적인 연륜 속에서, 당신의 존재는 제 생일에 의미를 주었습니다. 더 이상 단순히 훌륭한 식사를 위해서가 아니라, 여전히 뛰고 있는 당신의 생명을 위해서입니다.\n\n두르르사인"
